def user_project_names(user: dict) -> list[str]:
    names = []
    if user.get("projectName"):
        names.append(user.get("projectName"))
    if user.get("project_name"):
        names.append(user.get("project_name"))
    ap = user.get("assignedProjects", user.get("assigned_projects", []))
    try:
        if isinstance(ap, str):
            ap = json.loads(ap)
    except Exception:
        ap = []
    if isinstance(ap, list):
        names.extend([str(x) for x in ap if x])
    return sorted(set([x for x in names if x]))

def user_package_names(user: dict) -> list[str]:
    packages = user.get("assignedPackages", user.get("assigned_packages", []))
    try:
        if isinstance(packages, str):
            packages = json.loads(packages)
    except Exception:
        packages = []
    if not isinstance(packages, list):
        return []
    return sorted(set([str(x).strip() for x in packages if str(x or "").strip()]))

def has_package_access(user: dict, work_package: str = "") -> bool:
    role = user.get("role")
    if can_see_all_company_data(user) or role in ("технадзор", "стройконтроль"):
        return True
    if role == "прораб":
        return True
    packages = user_package_names(user)
    if role in PACKAGE_LIMIT_ROLES:
        if not packages:
            return False
        return bool((work_package or "Основная").strip() in packages)
    return True

def package_access_filter(user: dict, column: str = "work_package"):
    role = user.get("role")
    if role not in PACKAGE_LIMIT_ROLES:
        return "", []
    if role == "прораб":
        return "", []
    packages = user_package_names(user)
    if not packages:
        return " AND FALSE", []
    return f" AND COALESCE(NULLIF({column},''),'Основная') = ANY(%s)", [packages]

def has_work_execution_package_access(user: dict, project: str, work_package: str = "") -> bool:
    package = (work_package or "Основная").strip() or "Основная"
    return has_package_access(user, package)

def _worker_contract_scope_pairs(cur, user: dict) -> list[tuple[str, str]]:
    if user.get("role") not in WORKER_EXECUTION_ROLES:
        return []
    try:
        user_id = int(user.get("id") or 0)
    except Exception:
        user_id = 0
    user_name = (user.get("name") or "").strip()
    if user_id <= 0 and not user_name:
        return []
    cur.execute("""SELECT DISTINCT
                          bc.project_name,
                          COALESCE(NULLIF(bci.work_package,''), NULLIF(bc.work_package,''), 'Основная') AS work_package
                   FROM brigade_contract_items bci
                   JOIN brigade_contracts bc ON bc.id=bci.contract_id
                   WHERE COALESCE(bc.status,'') NOT IN ('Аннулирован','Удалён','Удален')
                     AND (
                       COALESCE(bc.contractor_id,0)=%s
                       OR (
                         COALESCE(bc.contractor_id,0)=0
                         AND LOWER(TRIM(COALESCE(bc.brigade_name,'')))=LOWER(TRIM(%s))
                       )
                     )""", (user_id, user_name))
    scopes = []
    for row in cur.fetchall() or []:
        project = (row.get("project_name") if isinstance(row, dict) else row[0]) or ""
        package = (row.get("work_package") if isinstance(row, dict) else row[1]) or "Основная"
        project = str(project).strip()
        package = str(package).strip() or "Основная"
        if project:
            scopes.append((project, package))
    return scopes

def enrich_worker_project_links(cur, user: dict) -> dict:
    """Назначенные договорные позиции тоже открывают исполнителю объект и пакет."""
    if user.get("role") not in WORKER_EXECUTION_ROLES:
        return user
    try:
        scopes = _worker_contract_scope_pairs(cur, user)
    except Exception:
        return user
    if not scopes:
        return user
    enriched = dict(user)
    projects = _safe_project_list(enriched.get("assignedProjects", enriched.get("assigned_projects", [])))
    packages = _safe_project_list(enriched.get("assignedPackages", enriched.get("assigned_packages", [])))
    for project, package in scopes:
        if project and project not in projects:
            projects.append(project)
        if package and package not in packages:
            packages.append(package)
    if not (enriched.get("projectName") or enriched.get("project_name")) and projects:
        enriched["project_name"] = projects[0]
        enriched["projectName"] = projects[0]
    enriched["assigned_projects"] = projects
    enriched["assignedProjects"] = projects
    enriched["assigned_packages"] = packages
    enriched["assignedPackages"] = packages
    return enriched

def _normalize_supplier_name_key(value: str) -> str:
    text = str(value or "").lower().replace("ё", "е")
    text = re.sub(r"(?:,|\s)\s*(инн|кпп|огрн|огрнип|тел\.?|телефон|р/с|расч[её]тн|адрес)\b.*$", " ", text)
    text = re.sub(r"\b(инн|кпп|огрн|огрнип)\s*[:№#-]?\s*\d+\b", " ", text)
    text = re.sub(r"\b(ооо|оао|ао|пао|зао|ип|индивидуальный предприниматель)\b", " ", text)
    return _norm_key_text(text)

def _supplier_digits(value) -> str:
    return re.sub(r"\D", "", str(value or ""))

def _supplier_payload_text(payload: dict, *keys: str) -> str:
    payload = payload or {}
    for key in keys:
        value = payload.get(key)
        if value is not None and str(value).strip():
            return str(value).strip()
    return ""

def _supplier_extract_requisites(payload: dict) -> dict:
    payload = payload or {}
    name = _supplier_payload_text(
        payload,
        "supplierName", "supplier_name", "supplier", "name", "companyName", "company_name",
        "seller", "shipper", "consignor", "sender",
    )
    raw_text = " ".join(str(v or "") for v in payload.values() if isinstance(v, (str, int, float)))
    inn = _supplier_digits(_supplier_payload_text(payload, "supplierInn", "supplier_inn", "inn"))
    kpp = _supplier_digits(_supplier_payload_text(payload, "supplierKpp", "supplier_kpp", "kpp"))
    ogrn = _supplier_digits(_supplier_payload_text(payload, "supplierOgrn", "supplier_ogrn", "ogrn", "ogrnip"))
    if not inn:
        match = re.search(r"\bинн\s*[:№#-]?\s*([0-9\s-]{10,20})", raw_text, re.IGNORECASE)
        if match:
            inn = _supplier_digits(match.group(1))
    if not kpp:
        match = re.search(r"\bкпп\s*[:№#-]?\s*([0-9\s-]{9,16})", raw_text, re.IGNORECASE)
        if match:
            kpp = _supplier_digits(match.group(1))
    if not ogrn:
        match = re.search(r"\bогрн(?:ип)?\s*[:№#-]?\s*([0-9\s-]{13,20})", raw_text, re.IGNORECASE)
        if match:
            ogrn = _supplier_digits(match.group(1))
    phone = _supplier_digits(_supplier_payload_text(payload, "supplierPhone", "supplier_phone", "phone", "tel", "telephone"))
    email = _supplier_payload_text(payload, "supplierEmail", "supplier_email", "email").lower()
    return {
        "name": name,
        "nameKey": _normalize_supplier_name_key(name),
        "inn": inn if len(inn) in (10, 12) else inn,
        "kpp": kpp if len(kpp) == 9 else kpp,
        "ogrn": ogrn if len(ogrn) in (13, 15) else ogrn,
        "phone": phone,
        "email": email if "@" in email else "",
    }

def _supplier_identity_keys(payload: dict) -> set:
    req = _supplier_extract_requisites(payload or {})
    keys = set()
    if req["inn"] and len(req["inn"]) >= 10:
        keys.add("inn:" + req["inn"])
    if req["ogrn"] and len(req["ogrn"]) >= 13:
        keys.add("ogrn:" + req["ogrn"])
    if req["email"]:
        keys.add("email:" + req["email"].lower())
    if req["phone"] and len(req["phone"]) >= 7:
        keys.add("phone:" + req["phone"])
    return keys

SUPPLIER_MATCH_SELECT = "id,name,phone,email,inn,kpp,ogrn,status"

def _supplier_match_dict(row):
    if not row:
        return None
    return {
        "id": _row_get(row, "id", 0, 0),
        "name": _row_get(row, "name", 1, ""),
        "phone": _row_get(row, "phone", 2, ""),
        "email": _row_get(row, "email", 3, ""),
        "inn": _row_get(row, "inn", 4, ""),
        "kpp": _row_get(row, "kpp", 5, ""),
        "ogrn": _row_get(row, "ogrn", 6, ""),
        "status": _row_get(row, "status", 7, ""),
    }

def _supplier_find_match(
    cur,
    payload: dict,
    allow_name_match: bool = False,
    allow_alias_name_match: bool = True,
    allow_contact_match: bool = True,
):
    req = _supplier_extract_requisites(payload)
    try:
        explicit_id = int(_supplier_payload_text(payload, "supplierId", "supplier_id", "id") or 0)
    except Exception:
        explicit_id = 0
    if explicit_id:
        cur.execute(f"SELECT {SUPPLIER_MATCH_SELECT} FROM suppliers WHERE id=%s LIMIT 1", (explicit_id,))
        row = cur.fetchone()
        if row:
            return _supplier_match_dict(row)
    if req["inn"]:
        cur.execute(f"""SELECT {SUPPLIER_MATCH_SELECT}
                        FROM suppliers
                        WHERE regexp_replace(COALESCE(inn,''), '\\D', '', 'g')=%s
                        ORDER BY id LIMIT 1""", (req["inn"],))
        row = cur.fetchone()
        if row:
            return _supplier_match_dict(row)
        cur.execute(f"""SELECT s.{SUPPLIER_MATCH_SELECT.replace(',', ',s.')}
                        FROM supplier_aliases a
                        JOIN suppliers s ON s.id=a.supplier_id
                        WHERE regexp_replace(COALESCE(a.inn,''), '\\D', '', 'g')=%s
                        ORDER BY s.id LIMIT 1""", (req["inn"],))
        row = cur.fetchone()
        if row:
            return _supplier_match_dict(row)
    if req["ogrn"]:
        cur.execute(f"""SELECT {SUPPLIER_MATCH_SELECT}
                        FROM suppliers
                        WHERE regexp_replace(COALESCE(ogrn,''), '\\D', '', 'g')=%s
                        ORDER BY id LIMIT 1""", (req["ogrn"],))
        row = cur.fetchone()
        if row:
            return _supplier_match_dict(row)
        cur.execute(f"""SELECT s.{SUPPLIER_MATCH_SELECT.replace(',', ',s.')}
                        FROM supplier_aliases a
                        JOIN suppliers s ON s.id=a.supplier_id
                        WHERE regexp_replace(COALESCE(a.ogrn,''), '\\D', '', 'g')=%s
                        ORDER BY s.id LIMIT 1""", (req["ogrn"],))
        row = cur.fetchone()
        if row:
            return _supplier_match_dict(row)
    if allow_contact_match and req["email"]:
        cur.execute(f"""SELECT {SUPPLIER_MATCH_SELECT}
                        FROM suppliers
                        WHERE LOWER(COALESCE(email,''))=LOWER(%s)
                        ORDER BY id LIMIT 1""", (req["email"],))
        row = cur.fetchone()
        if row:
            return _supplier_match_dict(row)
    if allow_contact_match and req["phone"] and len(req["phone"]) >= 7:
        cur.execute(f"""SELECT {SUPPLIER_MATCH_SELECT}
                        FROM suppliers
                        WHERE regexp_replace(COALESCE(phone,''), '\\D', '', 'g')=%s
                        ORDER BY id LIMIT 1""", (req["phone"],))
        row = cur.fetchone()
        if row:
            return _supplier_match_dict(row)
    if req["nameKey"] and allow_name_match:
        cur.execute(f"SELECT {SUPPLIER_MATCH_SELECT} FROM suppliers ORDER BY id")
        for row in cur.fetchall() or []:
            if _normalize_supplier_name_key(_row_get(row, "name", 1, "")) == req["nameKey"]:
                return _supplier_match_dict(row)
    if req["nameKey"] and allow_alias_name_match:
        cur.execute(f"""SELECT s.{SUPPLIER_MATCH_SELECT.replace(',', ',s.')}
                        FROM supplier_aliases a
                        JOIN suppliers s ON s.id=a.supplier_id
                        WHERE a.alias_key=%s
                          AND COALESCE(a.source,'') IN ('manual_supplier_duplicate_link','manual_supplier_user_link')
                        ORDER BY s.id LIMIT 1""", (req["nameKey"],))
        row = cur.fetchone()
        if row:
            return _supplier_match_dict(row)
    return None

def _supplier_has_strong_identity_match(cur, supplier_id: int, payload: dict, supplier_row: dict = None) -> bool:
    req = _supplier_extract_requisites(payload)
    supplier_req = _supplier_extract_requisites(supplier_row or {})
    if req["inn"] and supplier_req["inn"] and req["inn"] == supplier_req["inn"]:
        return True
    if req["ogrn"] and supplier_req["ogrn"] and req["ogrn"] == supplier_req["ogrn"]:
        return True
    if req["email"] and supplier_req["email"] and req["email"].lower() == supplier_req["email"].lower():
        return True
    if req["phone"] and supplier_req["phone"] and len(req["phone"]) >= 7 and req["phone"] == supplier_req["phone"]:
        return True
    if not supplier_id or not (req["inn"] or req["ogrn"]):
        return False
    cur.execute(
        """
        SELECT id
          FROM supplier_aliases
         WHERE supplier_id=%s
           AND (
             (%s<>'' AND regexp_replace(COALESCE(inn,''), '\\D', '', 'g')=%s)
             OR (%s<>'' AND regexp_replace(COALESCE(ogrn,''), '\\D', '', 'g')=%s)
           )
         LIMIT 1
        """,
        (supplier_id, req["inn"], req["inn"], req["ogrn"], req["ogrn"]),
    )
    return bool(cur.fetchone())

def _supplier_backfill_review_state(cur, warehouse_invoice: dict, supplier_payload: dict, supplier_id=None, matched_supplier: dict = None, created_supplier: bool = False) -> dict:
    reasons = []
    amount = _float_or_zero(
        (warehouse_invoice or {}).get("total_with_vat")
        or (warehouse_invoice or {}).get("total_base")
        or (supplier_payload or {}).get("amount")
        or 0
    )
    if amount <= 0:
        reasons.append("в накладной нет суммы для сверки")
    explicit_supplier_id = _positive_int_or_none((warehouse_invoice or {}).get("supplier_id")) or _positive_int_or_none((supplier_payload or {}).get("supplierId") or (supplier_payload or {}).get("supplier_id"))
    if created_supplier:
        reasons.append("поставщик создан из старой накладной и не подтвержден")
    elif not supplier_id:
        reasons.append("поставщик не определен")
    elif explicit_supplier_id and not matched_supplier:
        reasons.append("явная карточка поставщика из накладной не найдена")
    elif not explicit_supplier_id and not _supplier_has_strong_identity_match(cur, supplier_id, supplier_payload, matched_supplier):
        reasons.append("поставщик сопоставлен только по названию, без ИНН/ОГРН/email/телефона")
    needs_review = bool(reasons)
    return {
        "needsReview": needs_review,
        "reviewReason": "; ".join(reasons),
        "accountingStatus": "Нужно уточнение" if needs_review else "На проверке",
        "supplierInvoiceStatus": "Нужно уточнение" if needs_review else "На утверждении",
    }

def _supplier_backfill_preview_review_state(row: dict) -> dict:
    reasons = []
    amount = _float_or_zero((row or {}).get("total_with_vat") or (row or {}).get("total_base") or 0)
    if amount <= 0:
        reasons.append("в накладной нет суммы для сверки")
    if not _positive_int_or_none((row or {}).get("supplier_id")):
        reasons.append("поставщик будет сопоставляться без явной supplier_id")
    needs_review = bool(reasons)
    return {
        "needsReview": needs_review,
        "reviewReason": "; ".join(reasons),
        "accountingStatus": "Нужно уточнение" if needs_review else "На проверке",
    }

def _remember_supplier_alias(cur, supplier_id: int, payload: dict, source: str = "", confidence: float = 1.0):
    if not supplier_id:
        return
    req = _supplier_extract_requisites(payload)
    if not req["nameKey"] and not req["inn"] and not req["ogrn"]:
        return
    cur.execute("""SELECT id FROM supplier_aliases
                   WHERE supplier_id=%s
                     AND (
                       (%s<>'' AND alias_key=%s)
                       OR (%s<>'' AND regexp_replace(COALESCE(inn,''), '\\D', '', 'g')=%s)
                       OR (%s<>'' AND regexp_replace(COALESCE(ogrn,''), '\\D', '', 'g')=%s)
                     )
                   LIMIT 1""", (
        supplier_id,
        req["nameKey"], req["nameKey"],
        req["inn"], req["inn"],
        req["ogrn"], req["ogrn"],
    ))
    if cur.fetchone():
        return
    cur.execute("""INSERT INTO supplier_aliases
                      (supplier_id, alias_name, alias_key, inn, kpp, ogrn, source, confidence)
                   VALUES (%s,%s,%s,%s,%s,%s,%s,%s)""", (
        supplier_id, req["name"], req["nameKey"], req["inn"], req["kpp"], req["ogrn"],
        (source or "")[:100], confidence,
    ))


def _remember_supplier_duplicate_alias(cur, supplier_id: int, related_supplier_id: int, payload: dict):
    """Persist an explicit director-approved name link even if a weaker alias exists."""
    if not supplier_id or not related_supplier_id:
        return
    req = _supplier_extract_requisites(payload or {})
    cur.execute(
        """
        SELECT id
          FROM supplier_aliases
         WHERE supplier_id=%s
           AND (
             related_supplier_id=%s
             OR (%s<>'' AND alias_key=%s)
           )
         ORDER BY id
         LIMIT 1
        """,
        (supplier_id, related_supplier_id, req["nameKey"], req["nameKey"]),
    )
    existing = cur.fetchone()
    if existing:
        cur.execute(
            """
            UPDATE supplier_aliases
               SET alias_name=%s,
                   inn=CASE WHEN COALESCE(inn,'')='' THEN %s ELSE inn END,
                   kpp=CASE WHEN COALESCE(kpp,'')='' THEN %s ELSE kpp END,
                   ogrn=CASE WHEN COALESCE(ogrn,'')='' THEN %s ELSE ogrn END,
                   related_supplier_id=%s,
                   source='manual_supplier_duplicate_link',
                   confidence=GREATEST(COALESCE(confidence,0),0.99)
             WHERE id=%s
            """,
            (
                req["name"],
                req["inn"],
                req["kpp"],
                req["ogrn"],
                related_supplier_id,
                _row_get(existing, "id", 0, 0),
            ),
        )
        return
    cur.execute(
        """
        INSERT INTO supplier_aliases
            (supplier_id,related_supplier_id,alias_name,alias_key,inn,kpp,ogrn,source,confidence)
        VALUES (%s,%s,%s,%s,%s,%s,%s,'manual_supplier_duplicate_link',0.99)
        """,
        (
            supplier_id,
            related_supplier_id,
            req["name"],
            req["nameKey"],
            req["inn"],
            req["kpp"],
            req["ogrn"],
        ),
    )

def _update_supplier_missing_fields(cur, supplier_id: int, payload: dict, user_id=None):
    payload = payload or {}
    req = _supplier_extract_requisites(payload)
    values = {
        "name": req["name"],
        "phone": _supplier_payload_text(payload, "phone", "supplierPhone", "supplier_phone"),
        "email": _supplier_payload_text(payload, "email", "supplierEmail", "supplier_email"),
        "specialization": _supplier_payload_text(payload, "specialization", "workType", "work_type"),
        "category": _supplier_payload_text(payload, "category", "counterpartyType", "counterparty_type"),
        "status": _supplier_payload_text(payload, "status") or "Активный",
        "inn": req["inn"],
        "kpp": req["kpp"],
        "ogrn": req["ogrn"],
        "legal_address": _supplier_payload_text(payload, "legalAddress", "legal_address"),
        "actual_address": _supplier_payload_text(payload, "actualAddress", "actual_address", "address"),
        "bank": _supplier_payload_text(payload, "bank"),
        "bik": _supplier_payload_text(payload, "bik"),
        "account": _supplier_payload_text(payload, "account", "bankAccount", "bank_account"),
        "kor_account": _supplier_payload_text(payload, "korAccount", "kor_account", "corrAccount", "corr_account"),
        "director_name": _supplier_payload_text(payload, "directorName", "director_name", "signerName", "signer_name"),
        "director_position": _supplier_payload_text(payload, "directorPosition", "director_position", "signerBasis", "signer_basis"),
        "contract_url": _supplier_payload_text(payload, "contractUrl", "contract_url"),
        "contract_number": _supplier_payload_text(payload, "contractNumber", "contract_number"),
        "license_url": _supplier_payload_text(payload, "licenseUrl", "license_url"),
        "price_url": _supplier_payload_text(payload, "priceUrl", "price_url"),
        "website": _supplier_payload_text(payload, "website"),
        "notes": _supplier_payload_text(payload, "notes"),
        "source_type": _supplier_payload_text(payload, "sourceType", "source_type"),
        "source_detail": _supplier_payload_text(payload, "sourceDetail", "source_detail"),
    }
    cur.execute("""
        UPDATE suppliers SET
          name=CASE WHEN COALESCE(name,'')='' THEN %s ELSE name END,
          phone=CASE WHEN COALESCE(phone,'')='' THEN %s ELSE phone END,
          email=CASE WHEN COALESCE(email,'')='' THEN %s ELSE email END,
          specialization=CASE WHEN COALESCE(specialization,'')='' THEN %s ELSE specialization END,
          category=CASE WHEN COALESCE(category,'')='' THEN %s ELSE category END,
          status=CASE WHEN COALESCE(status,'')='' THEN %s ELSE status END,
          inn=CASE WHEN COALESCE(inn,'')='' THEN %s ELSE inn END,
          kpp=CASE WHEN COALESCE(kpp,'')='' THEN %s ELSE kpp END,
          ogrn=CASE WHEN COALESCE(ogrn,'')='' THEN %s ELSE ogrn END,
          legal_address=CASE WHEN COALESCE(legal_address,'')='' THEN %s ELSE legal_address END,
          actual_address=CASE WHEN COALESCE(actual_address,'')='' THEN %s ELSE actual_address END,
          bank=CASE WHEN COALESCE(bank,'')='' THEN %s ELSE bank END,
          bik=CASE WHEN COALESCE(bik,'')='' THEN %s ELSE bik END,
          account=CASE WHEN COALESCE(account,'')='' THEN %s ELSE account END,
          kor_account=CASE WHEN COALESCE(kor_account,'')='' THEN %s ELSE kor_account END,
          director_name=CASE WHEN COALESCE(director_name,'')='' THEN %s ELSE director_name END,
          director_position=CASE WHEN COALESCE(director_position,'')='' THEN %s ELSE director_position END,
          contract_url=CASE WHEN COALESCE(contract_url,'')='' THEN %s ELSE contract_url END,
          contract_number=CASE WHEN COALESCE(contract_number,'')='' THEN %s ELSE contract_number END,
          license_url=CASE WHEN COALESCE(license_url,'')='' THEN %s ELSE license_url END,
          price_url=CASE WHEN COALESCE(price_url,'')='' THEN %s ELSE price_url END,
          website=CASE WHEN COALESCE(website,'')='' THEN %s ELSE website END,
          notes=CASE WHEN COALESCE(notes,'')='' THEN %s ELSE notes END,
          source_type=CASE WHEN COALESCE(source_type,'')='' THEN %s ELSE source_type END,
          source_detail=CASE WHEN COALESCE(source_detail,'')='' THEN %s ELSE source_detail END
          """ + (", user_id=COALESCE(user_id,%s), registered_at=COALESCE(registered_at,NOW())" if user_id else "") + """
        WHERE id=%s
        RETURNING *
    """, (
        values["name"], values["phone"], values["email"], values["specialization"],
        values["category"], values["status"], values["inn"], values["kpp"], values["ogrn"],
        values["legal_address"], values["actual_address"], values["bank"], values["bik"],
        values["account"], values["kor_account"], values["director_name"], values["director_position"],
        values["contract_url"], values["contract_number"], values["license_url"], values["price_url"],
        values["website"], values["notes"], values["source_type"], values["source_detail"],
        *(([user_id] if user_id else [])),
        supplier_id,
    ))
    return cur.fetchone()


def _resolve_or_create_document_supplier(cur, data: dict, fallback_name: str = "", source_detail: str = ""):
    """Resolve a supplier by legal identity, or create one without trusting a name-only OCR match."""
    payload = build_document_supplier_payload(data, fallback_name=fallback_name)
    supplier_name = str(payload.get("supplierName") or "").strip()
    if not supplier_name:
        raise HTTPException(status_code=422, detail="В документе не распознано название поставщика")
    if not has_legal_supplier_identity(payload):
        raise HTTPException(
            status_code=422,
            detail="Не удалось надёжно определить нового поставщика: распознайте ИНН или ОГРН",
        )

    payload["sourceType"] = "accounting_document_recognition"
    payload["sourceDetail"] = source_detail or "Определено по реквизитам бухгалтерского документа"
    requisites = _supplier_extract_requisites(payload)
    identity_key = "inn:" + requisites["inn"] if requisites["inn"] else "ogrn:" + requisites["ogrn"]
    cur.execute("SELECT pg_advisory_xact_lock(hashtext(%s))", ("supplier:" + identity_key,))

    matched = _supplier_find_match(
        cur,
        payload,
        allow_name_match=False,
        allow_alias_name_match=False,
        allow_contact_match=False,
    )
    if matched:
        matched_requisites = _supplier_extract_requisites(matched)
        if requisites["inn"] and matched_requisites["inn"] and requisites["inn"] != matched_requisites["inn"]:
            raise HTTPException(status_code=409, detail="ИНН документа противоречит карточке поставщика")
        if requisites["ogrn"] and matched_requisites["ogrn"] and requisites["ogrn"] != matched_requisites["ogrn"]:
            raise HTTPException(status_code=409, detail="ОГРН документа противоречит карточке поставщика")
        updated = _update_supplier_missing_fields(cur, matched["id"], payload) or matched
        _remember_supplier_alias(cur, matched["id"], payload, source="accounting_document_recognition")
        return {
            "id": matched["id"],
            "name": _row_get(updated, "name", 1, "") or matched["name"] or supplier_name,
            "created": False,
        }

    cur.execute(
        """
        INSERT INTO suppliers
            (name,phone,email,specialization,category,rating,status,
             inn,kpp,ogrn,notes,source_type,source_detail)
        VALUES (%s,'','','','Материалы',5.0,'На проверке',%s,%s,%s,%s,%s,%s)
        RETURNING id,name
        """,
        (
            supplier_name,
            requisites["inn"],
            requisites["kpp"],
            requisites["ogrn"],
            payload["sourceDetail"],
            payload["sourceType"],
            payload["sourceDetail"],
        ),
    )
    created = cur.fetchone()
    supplier_id = _row_get(created, "id", 0, 0)
    updated = _update_supplier_missing_fields(cur, supplier_id, payload) or created
    _remember_supplier_alias(cur, supplier_id, payload, source="accounting_document_recognition")
    return {
        "id": supplier_id,
        "name": _row_get(updated, "name", 1, "") or supplier_name,
        "created": True,
    }


def _resolve_or_create_linked_invoice_supplier(
    cur,
    supplier_invoice: dict,
    fallback_name: str = "",
    warehouse_invoice_id: int = 0,
):
    """Resolve a linked bill supplier by name, or create a provisional review card.

    This is deliberately narrower than document recognition: it is called only after
    the accounting route has locked and validated a linked supplier invoice belonging
    to the same company and project as the warehouse invoice.
    """
    supplier_name = str(
        (supplier_invoice or {}).get("supplier_name")
        or fallback_name
        or ""
    ).strip()[:255]
    supplier_name_key = _normalize_supplier_name_key(supplier_name)
    if not supplier_name_key:
        raise HTTPException(
            status_code=422,
            detail="В связанном счёте не указано название поставщика",
        )

    payload = {
        "supplierName": supplier_name,
        "sourceType": "linked_supplier_invoice",
        "sourceDetail": "Создано из связанного счёта для складской накладной #"
        + str(warehouse_invoice_id),
    }
    # Serialize name-only creation and re-check after acquiring the lock so two
    # simultaneous clicks cannot create duplicate provisional supplier cards.
    cur.execute(
        "SELECT pg_advisory_xact_lock(hashtext(%s))",
        ("linked_supplier:" + supplier_name_key,),
    )
    matched = _supplier_find_match(
        cur,
        payload,
        allow_name_match=True,
        allow_alias_name_match=True,
        allow_contact_match=False,
    )
    if matched:
        _remember_supplier_alias(
            cur,
            matched["id"],
            payload,
            source="linked_supplier_invoice",
        )
        return {
            "id": matched["id"],
            "name": matched.get("name") or supplier_name,
            "created": False,
            "needsReview": False,
        }

    cur.execute(
        """
        INSERT INTO suppliers
            (name,phone,email,specialization,category,rating,status,
             notes,source_type,source_detail)
        VALUES (%s,'','','','Материалы',5.0,'На проверке',%s,%s,%s)
        RETURNING id,name
        """,
        (
            supplier_name,
            "Реквизиты требуют проверки перед фактической оплатой",
            payload["sourceType"],
            payload["sourceDetail"],
        ),
    )
    created = cur.fetchone()
    supplier_id = _row_get(created, "id", 0, 0)
    _remember_supplier_alias(
        cur,
        supplier_id,
        payload,
        source="linked_supplier_invoice",
    )
    return {
        "id": supplier_id,
        "name": _row_get(created, "name", 1, "") or supplier_name,
        "created": True,
        "needsReview": True,
    }


def _linked_supplier_invoice_status_after_accounting(
    current_status,
    next_accounting_status,
    resolved_automatically: bool = False,
):
    """Return the linked bill status change justified by this accounting action."""
    if str(next_accounting_status or "").strip() != "К оплате":
        return None
    current = str(current_status or "").strip()
    if current in ("", "На утверждении"):
        return "Утверждён"
    if resolved_automatically and current == "Нужно уточнение":
        return "Утверждён"
    return None


def _remove_resolved_supplier_clarification(comment) -> str:
    """Remove only the obsolete missing-supplier line from an accounting comment."""
    obsolete = {
        "поставщик не определен",
        "нужно уточнение: поставщик не определен",
        "поставщик не указан",
        "нужно уточнение: поставщик не указан",
    }
    kept = []
    for line in str(comment or "").splitlines():
        normalized = " ".join(
            line.lower().replace("ё", "е").strip(" .:;").split()
        )
        if normalized not in obsolete and line.strip():
            kept.append(line.strip())
    return "\n".join(kept)

def current_supplier_id(cur, user: dict):
    cur.execute("""SELECT id FROM suppliers
                   WHERE user_id=%s
                      OR (%s<>'' AND LOWER(email)=LOWER(%s))
                      OR (%s<>'' AND name=%s)
                   ORDER BY CASE WHEN user_id=%s THEN 0 ELSE 1 END, id
                   LIMIT 1""",
                (
                    user.get("id"),
                    user.get("email") or "", user.get("email") or "",
                    user.get("name") or "", user.get("name") or "",
                    user.get("id"),
                ))
    row = cur.fetchone()
    if not row:
        supplier = _supplier_find_match(cur, {
            "name": user.get("name") or "",
            "email": user.get("email") or "",
            "phone": user.get("phone") or "",
        })
        row = supplier
        if not row:
            return None
    try:
        return row["id"]
    except Exception:
        return row[0]

def current_supplier_ids(cur, user: dict):
    supplier_id = current_supplier_id(cur, user)
    if not supplier_id:
        return []
    return supplier_related_ids(cur, supplier_id)

def supplier_related_ids(cur, supplier_id: int):
    try:
        supplier_id = int(supplier_id or 0)
    except (TypeError, ValueError):
        return []
    if not supplier_id:
        return []

    metadata = _load_supplier_relation_metadata(cur)
    return metadata.get(supplier_id, {}).get("relatedSupplierIds") or [supplier_id]


def _supplier_relation_identity_keys(row):
    row = row or {}
    return _supplier_identity_keys({
        "name": row.get("name") or "",
        "phone": row.get("phone") or "",
        "email": row.get("email") or "",
        "inn": row.get("inn") or "",
        "kpp": row.get("kpp") or "",
        "ogrn": row.get("ogrn") or "",
    })


def _relation_rows_as_dicts(rows, columns):
    return [
        dict(row) if isinstance(row, dict) else dict(zip(columns, row))
        for row in (rows or [])
    ]


def _load_supplier_relation_metadata(cur):
    columns = [
        "id", "name", "phone", "email", "inn", "kpp", "ogrn", "user_id",
        "registered_at", "status", "legal_address", "actual_address", "website",
        "specialization",
    ]
    cur.execute(
        """
        SELECT id,name,phone,email,inn,kpp,ogrn,user_id,registered_at,status,
               legal_address,actual_address,website,specialization
          FROM suppliers
         ORDER BY id
        """
    )
    supplier_rows = _relation_rows_as_dicts(cur.fetchall() or [], columns)
    return _supplier_relation_metadata(cur, supplier_rows)


def _supplier_relation_metadata(cur, supplier_rows):
    alias_columns = [
        "supplier_id", "related_supplier_id", "name", "alias_key", "inn", "kpp",
        "ogrn", "source",
    ]
    cur.execute(
        """
        SELECT supplier_id,related_supplier_id,alias_name AS name,alias_key,inn,kpp,ogrn,source
          FROM supplier_aliases
         ORDER BY id
        """
    )
    aliases = _relation_rows_as_dicts(cur.fetchall() or [], alias_columns)
    return build_supplier_relation_metadata(
        supplier_rows,
        aliases,
        identity_keys=_supplier_relation_identity_keys,
        normalize_name_key=_normalize_supplier_name_key,
    )

def supplier_group_scope_ids(cur, supplier_ids) -> list:
    ids = []
    seen = set()
    relation_metadata = _load_supplier_relation_metadata(cur)
    for supplier_id in _normalize_supplier_ids(supplier_ids):
        related_ids = relation_metadata.get(supplier_id, {}).get("relatedSupplierIds") or [supplier_id]
        for related_id in related_ids:
            try:
                related_id = int(related_id or 0)
            except (TypeError, ValueError):
                continue
            if related_id > 0 and related_id not in seen:
                seen.add(related_id)
                ids.append(related_id)
    return ids

def supplier_offer_targets_for_groups(cur, supplier_ids, ai_ids=None) -> list:
    ai_ids = {int(x) for x in (ai_ids or []) if int(x) > 0}
    targets = []
    seen = set()
    relation_metadata = _load_supplier_relation_metadata(cur)
    for supplier_id in _normalize_supplier_ids(supplier_ids):
        scope_ids = relation_metadata.get(supplier_id, {}).get("relatedSupplierIds") or [supplier_id]
        scope_ids = [int(x) for x in scope_ids if int(x or 0) > 0]
        if not scope_ids or any(sid in seen for sid in scope_ids):
            continue
        seen.update(scope_ids)
        target_id = int(
            relation_metadata.get(supplier_id, {}).get("canonicalSupplierId")
            or supplier_id
        )
        targets.append({
            "requested_id": supplier_id,
            "target_id": target_id,
            "scope_ids": scope_ids,
            "ai_recommended": bool(ai_ids.intersection(scope_ids) or target_id in ai_ids),
        })
    return targets

