def _supply_request_notification_context(cur, request_id: int) -> dict:
    cur.execute("""
        SELECT id, material_name, quantity, unit, project, work_package, notes, items_json, company_id
          FROM supply_requests
         WHERE id=%s
         LIMIT 1
    """, (request_id,))
    row = cur.fetchone()
    if not row:
        return {}
    items = _json_list_or_empty(_row_get(row, "items_json", 7, None))
    item_lines = []
    for item in items[:5]:
        if not isinstance(item, dict):
            continue
        name = (item.get("materialName") or item.get("material_name") or item.get("name") or "").strip()
        qty = item.get("quantity") or item.get("qty") or ""
        unit = (item.get("unit") or "").strip()
        if name:
            item_lines.append(f"- {name}: {qty} {unit}".strip())
    if len(items) > 5:
        item_lines.append("- и ещё " + str(len(items) - 5) + " поз.")
    material = _row_get(row, "material_name", 1, "") or ""
    quantity = _row_get(row, "quantity", 2, "") or ""
    unit = _row_get(row, "unit", 3, "") or ""
    project = _row_get(row, "project", 4, "") or ""
    company_id = _row_get(row, "company_id", 8, None)
    project_id = None
    if company_id and project and project != "Основной склад":
        cur.execute(
            "SELECT id FROM projects WHERE company_id=%s AND name=%s "
            "AND COALESCE(archived,FALSE)=FALSE ORDER BY id",
            (company_id, project),
        )
        projects = list(cur.fetchall() or [])
        if len(projects) != 1:
            raise HTTPException(status_code=409, detail="Объект заявки КП определяется неоднозначно")
        project_id = _row_get(projects[0], "id", 0, None)
    if not item_lines and material:
        item_lines.append(f"- {material}: {quantity} {unit}".strip())
    return {
        "id": int(_row_get(row, "id", 0, request_id) or request_id),
        "companyId": company_id,
        "projectId": project_id,
        "project": project,
        "workPackage": _row_get(row, "work_package", 5, "") or "",
        "materialName": material,
        "quantity": quantity,
        "unit": unit,
        "notes": _row_get(row, "notes", 6, "") or "",
        "itemLines": item_lines,
    }

def _supply_request_notification_text(request_context: dict, supplier_name: str = "") -> tuple:
    request_id = int((request_context or {}).get("id") or 0)
    project = (request_context or {}).get("project") or "объект не указан"
    package = (request_context or {}).get("workPackage") or "Основная"
    title = "Запрос КП №" + str(request_id)
    greeting = "Здравствуйте."
    if supplier_name:
        greeting = "Здравствуйте, " + supplier_name + "."
    lines = [
        greeting,
        "",
        "Вам отправлен запрос коммерческого предложения в СтройКа.",
        "Объект: " + project,
        "Раздел: " + package,
    ]
    item_lines = (request_context or {}).get("itemLines") or []
    if item_lines:
        lines.append("")
        lines.append("Позиции:")
        lines.extend(item_lines)
    notes = ((request_context or {}).get("notes") or "").strip()
    if notes:
        lines.extend(["", "Комментарий: " + notes])
    lines.extend(["", "Открыть запрос: " + _supply_kp_public_url(request_id)])
    return title, "\n".join(lines)

def _queue_supply_request_max_notification(cur, recipient: dict, request_context: dict, offer_id=None) -> tuple:
    supplier_user_id = recipient.get("supplier_user_id") or recipient.get("supplierUserId")
    if not supplier_user_id:
        return None, "MAX не привязан"
    _ensure_supply_notification_messenger_tables(cur)
    cur.execute("""
        SELECT id, external_user_id, chat_id
          FROM messenger_accounts
         WHERE provider='max'
           AND user_id=%s
           AND COALESCE(enabled, TRUE)=TRUE
         ORDER BY id DESC
         LIMIT 1
    """, (supplier_user_id,))
    account = cur.fetchone()
    if not account:
        return None, "MAX не привязан"
    account_id = int(_row_get(account, "id", 0, 0) or 0)
    request_id = int((request_context or {}).get("id") or 0)
    owner = resolve_supply_outbox_owner(request_context, recipient)
    cur.execute("""
        SELECT id, status
          FROM messenger_outbox
         WHERE provider='max'
           AND company_id=%s
           AND messenger_account_id=%s
           AND event_type='supplier_kp_requested'
           AND entity_type='supply_request'
           AND entity_id=%s
           AND COALESCE(status,'') NOT IN ('cancelled','failed')
         ORDER BY id DESC
         LIMIT 1
    """, (owner["companyId"], account_id, request_id))
    existing = cur.fetchone()
    if existing:
        return int(_row_get(existing, "id", 0, 0) or 0), "В очереди MAX"
    title, body = _supply_request_notification_text(request_context, recipient.get("supplier_name") or "")
    payload = {
        "requestId": request_id,
        "offerId": offer_id,
        "supplierId": recipient.get("target_supplier_id") or recipient.get("supplier_id"),
        "projectName": (request_context or {}).get("project") or "",
        "workPackage": (request_context or {}).get("workPackage") or "",
    }
    actions = [{
        "id": "openSupplyRequest",
        "label": "Открыть КП",
        "kind": "open_app",
        "path": "/app?from=max&page=supply",
        "entityType": "supply_request",
        "entityId": request_id,
    }]
    cur.execute("""
        INSERT INTO messenger_outbox
            (owner_scope, company_id, project_id, provider, messenger_account_id, user_id, external_user_id, chat_id, event_type,
             entity_type, entity_id, title, body, payload_json, actions_json, status, priority,
             created_at, updated_at)
        VALUES ('company',%s,%s,'max',%s,%s,%s,%s,'supplier_kp_requested',
                'supply_request',%s,%s,%s,%s::jsonb,%s::jsonb,'queued',4,NOW(),NOW())
        RETURNING id
    """, (
        owner["companyId"],
        owner["projectId"],
        account_id,
        supplier_user_id,
        _row_get(account, "external_user_id", 1, "") or "",
        _row_get(account, "chat_id", 2, "") or "",
        request_id,
        title,
        body,
        json.dumps(payload, ensure_ascii=False),
        json.dumps(actions, ensure_ascii=False),
    ))
    row = cur.fetchone()
    return int(_row_get(row, "id", 0, 0) or 0), "В очереди MAX"

def _notify_supply_request_recipients(cur, request_id: int, company_id: int = None) -> list:
    _ensure_supply_request_recipients_table(cur)
    request_context = _supply_request_notification_context(cur, request_id)
    if not request_context:
        return []
    request_company_id = _positive_int_or_none(request_context.get("companyId"))
    requested_company_id = _positive_int_or_none(company_id)
    if not request_company_id:
        raise HTTPException(status_code=409, detail="Заявка снабжения не привязана к компании")
    if requested_company_id and requested_company_id != request_company_id:
        raise HTTPException(status_code=409, detail="Компания уведомления не совпадает с компанией заявки")
    company_id = request_company_id
    recipient_company_sql = " AND r.company_id=%s"
    recipient_params = [request_id, company_id]
    cur.execute("""
        SELECT r.id, r.request_id, r.target_supplier_id, r.supplier_id, r.supplier_user_id,
               r.email_notification_status, r.max_notification_status, r.max_outbox_id, r.company_id,
               COALESCE(s.name,'') AS supplier_name,
               COALESCE(NULLIF(s.email,''), NULLIF(u.email,''), '') AS email
          FROM supply_request_recipients r
          LEFT JOIN suppliers s ON s.id=r.target_supplier_id
          LEFT JOIN users u ON u.id=r.supplier_user_id
         WHERE r.request_id=%s
           AND COALESCE(r.visible_to_supplier,FALSE)=TRUE
    """ + recipient_company_sql + """
         ORDER BY r.id
    """, recipient_params)
    recipients = [dict(row) for row in (cur.fetchall() or [])]
    if not recipients:
        return []
    scope_ids = _normalize_supplier_ids([row.get("target_supplier_id") or row.get("supplier_id") for row in recipients])
    offer_by_supplier = {}
    if scope_ids:
        offer_company_sql = " AND company_id=%s"
        offer_params = [request_id, scope_ids, company_id]
        cur.execute("""
            SELECT id, supplier_id
              FROM supplier_offers
             WHERE request_id=%s
               AND supplier_id = ANY(%s)
               AND COALESCE(status,'') NOT IN ('Отклонено','Отозвано')
        """ + offer_company_sql + """
             ORDER BY id DESC
        """, offer_params)
        for offer in cur.fetchall() or []:
            supplier_id = int(_row_get(offer, "supplier_id", 1, 0) or 0)
            offer_by_supplier.setdefault(supplier_id, int(_row_get(offer, "id", 0, 0) or 0))
    notifications = []
    for recipient in recipients:
        recipient_id = int(recipient.get("id") or 0)
        supplier_id = int(recipient.get("target_supplier_id") or recipient.get("supplier_id") or 0)
        email = (recipient.get("email") or "").strip()
        current_email_status = (recipient.get("email_notification_status") or "").strip()
        email_sent = False
        if current_email_status == "Отправлено":
            email_status = current_email_status
        elif not email:
            email_status = "Нет email"
        elif _should_skip_supplier_notification_email(email):
            email_status = "Пропущено: тестовый email"
        elif not _smtp_configured():
            email_status = "SMTP не настроен"
        else:
            subject, body = _supply_request_notification_text(request_context, recipient.get("supplier_name") or "")
            email_sent = _send_email(email, subject, body)
            email_status = "Отправлено" if email_sent else "Ошибка отправки"

        offer_id = offer_by_supplier.get(supplier_id)
        current_max_status = (recipient.get("max_notification_status") or "").strip()
        current_outbox_id = recipient.get("max_outbox_id")
        if current_outbox_id and current_max_status in ("В очереди MAX", "Отправлено MAX"):
            max_outbox_id = int(current_outbox_id)
            max_status = current_max_status
            max_queued = False
        else:
            max_outbox_id, max_status = _queue_supply_request_max_notification(cur, recipient, request_context, offer_id)
            max_queued = bool(max_outbox_id and max_status == "В очереди MAX")
        cur.execute("""
            UPDATE supply_request_recipients
               SET email_notification_status=%s,
                   email_sent_at=CASE WHEN %s THEN COALESCE(email_sent_at,NOW()) ELSE email_sent_at END,
                   max_notification_status=%s,
                   max_outbox_id=COALESCE(%s, max_outbox_id),
                   max_queued_at=CASE WHEN %s THEN COALESCE(max_queued_at,NOW()) ELSE max_queued_at END
             WHERE id=%s
        """, (email_status, email_sent, max_status, max_outbox_id, max_queued, recipient_id))
        notifications.append({
            "recipientId": recipient_id,
            "supplierId": supplier_id,
            "offerId": offer_id,
            "email": email,
            "emailStatus": email_status,
            "maxStatus": max_status,
            "maxOutboxId": max_outbox_id,
        })
    return notifications

def _resolve_work_company_context(
    cur,
    user: dict,
    requested_company_id=None,
    action_mode: str = "write",
    *,
    x_company_id=None,
    x_company_mode=None,
) -> dict:
    try:
        from backend.features.company_context.service import resolve_request_company_context
    except ModuleNotFoundError:
        from features.company_context.service import resolve_request_company_context
    return resolve_request_company_context(
        cur,
        user,
        requested_company_id,
        action_mode,
        x_company_id=x_company_id,
        x_company_mode=x_company_mode,
        platform_staff_roles=PLATFORM_STAFF_ROLES,
        client_account_roles=CLIENT_ACCOUNT_ROLES,
    )

def _resolve_crm_create_owner(cur, user, x_company_id=None, x_company_mode=None):
    context = _resolve_work_company_context(
        cur,
        user,
        None,
        "create",
        x_company_id=x_company_id,
        x_company_mode=x_company_mode,
    )
    return resolve_authenticated_lead_owner(
        context,
        effective_company_actors(user, context),
        allowed_roles=(*LEADERSHIP_ROLES, "менеджер_crm"),
    )

def _project_company_id(cur, project_name: str):
    project_name = (project_name or "").strip()
    if not project_name or project_name == "Основной склад":
        return None
    cur.execute("SELECT company_id FROM projects WHERE name=%s ORDER BY id DESC LIMIT 1", (project_name,))
    row = cur.fetchone()
    return _row_get(row, "company_id", 0, None) if row else None

def _positive_int_or_none(value):
    try:
        result = int(value)
    except Exception:
        return None
    return result if result > 0 else None

def _company_id_for_project_or_user(cur, project_name: str = "", user: dict = None, explicit=None) -> int:
    explicit_id = _positive_int_or_none(explicit)
    if explicit_id:
        return explicit_id
    project_id = _positive_int_or_none(_project_company_id(cur, project_name or ""))
    if project_id:
        return project_id
    if user:
        user_company_id = _positive_int_or_none(user.get("companyId") or user.get("company_id"))
        if user_company_id:
            return user_company_id
    return 1

def _resolve_project_payment_actor(
    cur,
    user: dict,
    project_name: str,
    work_package: str = "",
    *,
    claimed_company_id=None,
    x_company_id=None,
    x_company_mode=None,
    require_unambiguous_project: bool = False,
):
    project_name = str(project_name or "").strip()
    if not project_name:
        raise HTTPException(status_code=400, detail="Не указан объект платежа")
    requested_company_id = None
    if claimed_company_id not in (None, ""):
        requested_company_id = _positive_int_or_none(claimed_company_id)
        if not requested_company_id:
            raise HTTPException(status_code=400, detail="companyId должен быть положительным целым числом")
    company_context = _resolve_work_company_context(
        cur,
        user,
        requested_company_id,
        "write",
        x_company_id=x_company_id,
        x_company_mode=x_company_mode,
    )
    actors = effective_company_actors(user, company_context)
    actor = actors[0] if len(actors) == 1 else {}
    company_id = _positive_int_or_none(company_context.get("companyId"))
    if not company_id or not actor:
        raise HTTPException(status_code=409, detail="Компания платежа не определена")
    if (actor.get("role") or "") not in FINANCE_ROLES:
        raise HTTPException(status_code=403, detail="Роль в выбранной компании не позволяет менять платежи")
    try:
        from backend.features.project_access.service import resolve_project_parent
    except ModuleNotFoundError:
        from features.project_access.service import resolve_project_parent
    parent = resolve_project_parent(cur, actor, project_name=project_name)
    project_name = parent.get("name") or project_name
    if require_unambiguous_project:
        cur.execute("SELECT COUNT(DISTINCT COALESCE(company_id,1)) FROM projects WHERE name=%s", (project_name,))
        company_count = int(_row_get(cur.fetchone(), "count", 0, 0) or 0)
        if company_count > 1:
            raise HTTPException(
                status_code=409,
                detail="Источник платежа не привязан к компании, а название объекта встречается в нескольких компаниях",
            )
    require_project_access(actor, project_name)
    if not has_package_access(actor, work_package or "Основная"):
        raise HTTPException(status_code=403, detail="Нет доступа к пакету платежа")
    return company_id, actor

def _brigade_contract_read_scope(
    conn,
    user: dict,
    allowed_roles,
    *,
    x_company_id=None,
    x_company_mode=None,
    item_alias="",
):
    scope_cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    try:
        company_context = _resolve_work_company_context(
            scope_cur,
            user,
            None,
            "read",
            x_company_id=x_company_id,
            x_company_mode=x_company_mode,
        )
        actors = effective_company_actors(user, company_context)
        visibility_sql, visibility_params = brigade_contract_visibility_filter(
            actors,
            allowed_roles=allowed_roles,
            full_view_roles=BRIGADE_FULL_VIEW_ROLES,
            worker_roles=WORKER_EXECUTION_ROLES,
            package_limit_roles=PACKAGE_LIMIT_ROLES,
            package_optional_roles=("прораб",),
            item_alias=item_alias,
        )
        return visibility_sql, visibility_params, actors
    finally:
        scope_cur.close()

def _resolve_brigade_contract_actor(
    cur,
    user: dict,
    contract_id,
    allowed_roles,
    *,
    claimed_company_id=None,
    x_company_id=None,
    x_company_mode=None,
    for_update: bool = False,
):
    normalized_contract_id = _positive_int_or_none(contract_id)
    if not normalized_contract_id:
        raise HTTPException(status_code=400, detail="contractId должен быть положительным целым числом")
    lock_sql = " FOR UPDATE" if for_update else ""
    cur.execute(
        """SELECT id,company_id,project_id,project_name,
                  COALESCE(NULLIF(work_package,''),'Основная') AS work_package,
                  brigade_name,COALESCE(act_scan_url,'') AS act_scan_url,
                  total_amount,status,contractor_id
             FROM brigade_contracts
            WHERE id=%s""" + lock_sql,
        (normalized_contract_id,),
    )
    row = cur.fetchone()
    if not row:
        raise HTTPException(status_code=404, detail="Договор бригады не найден")
    contract = {
        "id": _row_get(row, "id", 0),
        "companyId": _row_get(row, "company_id", 1),
        "projectId": _row_get(row, "project_id", 2),
        "projectName": _row_get(row, "project_name", 3, "") or "",
        "workPackage": _row_get(row, "work_package", 4, "Основная") or "Основная",
        "brigadeName": _row_get(row, "brigade_name", 5, "") or "",
        "actScanUrl": _row_get(row, "act_scan_url", 6, "") or "",
        "totalAmount": _row_get(row, "total_amount", 7, 0) or 0,
        "status": _row_get(row, "status", 8, "") or "",
        "contractorId": _row_get(row, "contractor_id", 9),
    }
    if not _positive_int_or_none(contract["projectId"]):
        cur.execute(
            "SELECT id,company_id FROM projects WHERE name=%s AND company_id IS NOT NULL ORDER BY id",
            (contract["projectName"],),
        )
        legacy_projects = cur.fetchall() or []
        if len(legacy_projects) != 1:
            raise HTTPException(
                status_code=409,
                detail="Название объекта договора неоднозначно. Сначала назначьте точный projectId.",
            )
        legacy_company_id = _row_get(legacy_projects[0], "company_id", 1)
        if _positive_int_or_none(legacy_company_id) != _positive_int_or_none(contract["companyId"]):
            raise HTTPException(
                status_code=409,
                detail="Компания договора не совпадает с компанией объекта",
            )
    access_cur = cur.connection.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    try:
        _context, actor = resolve_resource_company_actor(
            access_cur,
            user,
            contract["companyId"],
            "update",
            claimed_company_id=claimed_company_id,
            x_company_id=x_company_id,
            x_company_mode=x_company_mode,
            allowed_roles=allowed_roles,
            forbidden_detail="Роль в выбранной компании не позволяет изменять договоры бригад",
            platform_staff_roles=PLATFORM_STAFF_ROLES,
            client_account_roles=CLIENT_ACCOUNT_ROLES,
        )
    finally:
        access_cur.close()
    try:
        from backend.features.project_access.service import (
            require_child_project_identity,
            resolve_project_parent,
        )
    except ModuleNotFoundError:
        from features.project_access.service import (
            require_child_project_identity,
            resolve_project_parent,
        )
    project_id, legacy_project_name = brigade_contract_project_reference(
        contract["projectId"],
        contract["projectName"],
    )
    project = resolve_project_parent(
        cur,
        actor,
        project_id=project_id,
        project_name=legacy_project_name,
        for_update=for_update,
    )
    contract_identity = {
        **contract,
        "projectId": project_id,
        "projectName": legacy_project_name,
    }
    require_child_project_identity(contract_identity, project, child_label="Договор бригады")
    require_project_access(actor, project["name"])
    contract["companyId"] = project["companyId"]
    contract["projectId"] = project["id"]
    contract["projectName"] = project["name"]
    return contract, actor, project

def supplier_is_selected(selected_suppliers, supplier_id: int) -> bool:
    if not supplier_id:
        return False
    if isinstance(selected_suppliers, (list, tuple, set)):
        return any(str(x) == str(supplier_id) for x in selected_suppliers)
    return str(supplier_id) in re.findall(r"\d+", str(selected_suppliers or ""))

def can_see_all_company_data(user: dict) -> bool:
    return user.get("role") in ("директор", "зам_директора", "бухгалтер", "главный_инженер", "сметчик")

def can_see_warehouse_data(user: dict) -> bool:
    return user.get("role") in WAREHOUSE_ROLES or user.get("role") in FINANCE_ROLES or user.get("role") == "главный_инженер"

def visible_project_names(user: dict) -> Optional[List[str]]:
    if can_see_all_company_data(user):
        return None
    return user_project_names(user)

def scoped_project_filter(user: dict, column: str):
    allowed = visible_project_names(user)
    if allowed is None:
        return "", []
    if not allowed:
        return " AND FALSE", []
    return f" AND {column} = ANY(%s)", [allowed]

def scoped_project_where(user: dict, column: str):
    sql, params = scoped_project_filter(user, column)
    if sql.startswith(" AND "):
        return " WHERE " + sql[5:], params
    return sql, params

def can_see_system_tasks(user: dict) -> bool:
    return user.get("role") in LEADERSHIP_ROLES or user.get("role") == "system_owner"

def has_project_access(user: dict, project_name: str) -> bool:
    if project_name == SYSTEM_PROJECT_NAME:
        return can_see_system_tasks(user)
    allowed = visible_project_names(user)
    return allowed is None or bool(project_name and project_name in allowed)

def require_project_access(user: dict, project_name: str):
    if not has_project_access(user, project_name):
        raise HTTPException(status_code=403, detail="Нет доступа к объекту")

def require_estimate_access(cur, estimate_id: int, user: dict):
    cur.execute("SELECT project_name, COALESCE(work_package,'Основная') AS work_package FROM estimates WHERE id=%s", (estimate_id,))
    row = cur.fetchone()
    if not row:
        raise HTTPException(status_code=404, detail="Смета не найдена")
    project_name = row.get("project_name") if isinstance(row, dict) else row[0]
    work_package = row.get("work_package") if isinstance(row, dict) else row[1]
    require_project_access(user, project_name or "")
    if user.get("role") in PACKAGE_LIMIT_ROLES and not has_package_access(user, work_package or "Основная"):
        raise HTTPException(status_code=403, detail="Нет доступа к пакету сметы")
    return project_name or "", work_package or "Основная"

def _estimate_item_key_candidates(item: dict, estimate_id=None, section_idx=None, item_idx=None) -> list[str]:
    keys = []
    for field in ("estimateItemKey", "estimate_item_key", "itemKey", "workKey", "work_key", "key", "id", "code", "sourceCode", "obosn"):
        value = str((item or {}).get(field) or "").strip()
        if value and value not in keys:
            keys.append(value)
    if estimate_id is not None and section_idx is not None and item_idx is not None:
        generated = str(estimate_id) + ":" + str(section_idx) + ":" + str(item_idx)
        if generated not in keys:
            keys.append(generated)
    return keys

def _estimate_item_unit_price_backend(item: dict) -> float:
    for field in (
        "executionPricePerUnit", "priceBrigade", "masterPricePerUnit", "contractorPricePerUnit",
        "executorPricePerUnit", "internalPricePerUnit", "priceWork", "priceSmeta", "price",
        "baseUnitPrice",
    ):
        value = _safe_float((item or {}).get(field))
        if value > 0:
            return value
    qty = _safe_float((item or {}).get("quantity"))
    total = 0
    for field in ("totalWork", "lineTotal", "currentTotal", "total", "baseTotal", "estimatedCost"):
        total = _safe_float((item or {}).get(field))
        if abs(total) > 0:
            break
    if qty > 0 and total > 0:
        return round(total / qty, 6)
    return 0

def _load_estimate_work_item(cur, estimate_id: int, *, project_name: str = "", work_package: str = "",
                             estimate_item_key: str = "", section_name: str = "", item_name: str = ""):
    cur.execute("""SELECT project_name, COALESCE(NULLIF(work_package,''),'Основная') AS work_package, sections_json
                   FROM estimates WHERE id=%s""", (estimate_id,))
    row = cur.fetchone()
    if not row:
        raise HTTPException(status_code=404, detail="Смета не найдена")
    est_project = row.get("project_name") if isinstance(row, dict) else row[0]
    est_package = row.get("work_package") if isinstance(row, dict) else row[1]
    raw_sections = row.get("sections_json") if isinstance(row, dict) else row[2]
    if project_name and est_project and est_project != project_name:
        raise HTTPException(status_code=400, detail="Смета относится к другому объекту")
    normalized_package = (work_package or est_package or "Основная").strip() or "Основная"
    if est_package and normalized_package != est_package:
        raise HTTPException(status_code=400, detail="Пакет работы не совпадает с пакетом сметы")
    try:
        sections = json.loads(raw_sections) if isinstance(raw_sections, str) else (raw_sections or [])
    except Exception:
        sections = []
    target_key = str(estimate_item_key or "").strip()
    target_section = str(section_name or "").strip().lower()
    target_name = str(item_name or "").strip().lower()
    fallback_match = None
    for section_idx, section in enumerate(sections or []):
        if not isinstance(section, dict):
            continue
        current_section = str(section.get("name") or "").strip()
        for item_idx, item in enumerate(section.get("items") or []):
            if not isinstance(item, dict):
                continue
            if _estimate_item_type_backend(item, current_section) != "work":
                continue
            keys = _estimate_item_key_candidates(item, estimate_id, section_idx, item_idx)
            item_name_value = str(item.get("name") or item.get("description") or "").strip()
            key_match = target_key and target_key in keys
            name_match = target_name and item_name_value.strip().lower() == target_name
            section_match = (not target_section) or current_section.lower() == target_section
            if key_match or (name_match and section_match):
                canonical_key = target_key if key_match else (keys[0] if keys else "")
                return {
                    "sectionName": current_section,
                    "name": item_name_value,
                    "unit": item.get("unit") or "шт",
                    "quantity": _safe_float(item.get("quantity")),
                    "pricePerUnit": _estimate_item_unit_price_backend(item),
                    "workPackage": est_package or "Основная",
                    "estimateItemKey": canonical_key,
                    "item": item,
                }
            if name_match and not fallback_match:
                fallback_match = {
                    "sectionName": current_section,
                    "name": item_name_value,
                    "unit": item.get("unit") or "шт",
                    "quantity": _safe_float(item.get("quantity")),
                    "pricePerUnit": _estimate_item_unit_price_backend(item),
                    "workPackage": est_package or "Основная",
                    "estimateItemKey": keys[0] if keys else "",
                    "item": item,
                }
    if fallback_match:
        return fallback_match
    raise HTTPException(status_code=400, detail="Строка ЖПР не найдена в указанной смете")

