def _clip_api_error_text(value: str, limit: int = 700) -> str:
    text = str(value or "").replace("\x00", "").strip()
    if len(text) <= limit:
        return text
    return text[:limit - 1] + "…"

def _request_user_snapshot(request: Request, cur=None) -> dict:
    auth = request.headers.get("authorization") or ""
    if auth.lower().startswith("bearer "):
        try:
            payload = verify_auth_token(auth.split(" ", 1)[1].strip())
            return {
                "id": payload.get("id"),
                "name": payload.get("name") or "",
                "role": payload.get("role") or "",
                "user_id": payload.get("id"),
                "user_name": payload.get("name") or "",
                "user_role": payload.get("role") or "",
            }
        except Exception:
            return {}
    session_token = request.cookies.get(AUTH_SESSION_COOKIE_NAME) if request else ""
    if not session_token or cur is None:
        return {}
    try:
        cur.execute(
            """SELECT u.id, u.name, u.role
               FROM user_sessions s
               JOIN users u ON u.id=s.user_id
               WHERE s.session_hash=%s
                 AND s.revoked_at IS NULL
                 AND s.expires_at>NOW()
                 AND COALESCE(u.active, TRUE)=TRUE
               LIMIT 1""",
            (_session_token_hash(session_token),),
        )
        row = cur.fetchone()
        if not row:
            return {}
        actor = dict(row)
        return {
            "id": actor.get("id"),
            "name": actor.get("name") or "",
            "role": actor.get("role") or "",
            "user_id": actor.get("id"),
            "user_name": actor.get("name") or "",
            "user_role": actor.get("role") or "",
        }
    except Exception:
        return {}

def _log_api_error(request: Request, exc: Optional[Exception] = None, status_code: int = 500):
    """Логирует только технический минимум: без тела запроса, паролей и токенов."""
    conn = None
    cur = None
    try:
        conn = get_db()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        user = _request_user_snapshot(request, cur)
        owner = resolve_api_error_write_owner(
            cur,
            user,
            _resolve_work_company_context,
            x_company_id=request.headers.get("x-company-id"),
            x_company_mode=request.headers.get("x-company-mode"),
        )
        insert_api_error(
            cur,
            method=request.method,
            path=request.url.path,
            status_code=status_code,
            error_type=exc.__class__.__name__ if exc else "HTTP_" + str(status_code),
            error_message=_clip_api_error_text(str(exc or "")),
            user_id=user.get("user_id"),
            user_name=user.get("user_name") or "",
            user_role=user.get("user_role") or "",
            owner=owner,
        )
        conn.commit()
    except Exception as log_exc:
        print("API ERROR LOG ERROR:", str(log_exc))
    finally:
        try:
            if cur:
                cur.close()
        except Exception:
            pass
        try:
            if conn:
                conn.close()
        except Exception:
            pass


def _api_error_logging_enabled_for_path(path):
    return path not in (
        "/warehouse-anomaly-previews",
        "/assignment-daily-draft-previews",
        "/accounting-exception-checks",
        "/accounting-exception-link-repairs",
    )


@app.middleware("http")
async def api_error_logging_middleware(request: Request, call_next):
    if (
        request.url.path.startswith("/uploads/")
        and "/public-site-lead-quarantine/" in request.url.path
    ):
        return Response(status_code=404)
    log_api_error = _api_error_logging_enabled_for_path(request.url.path)
    try:
        response = await call_next(request)
        if response.status_code >= 500 and log_api_error:
            _log_api_error(request, None, response.status_code)
        return response
    except Exception as exc:
        if log_api_error:
            _log_api_error(request, exc, 500)
        raise

