def _limited_dir_stats(path: str, max_entries: int = 5000) -> dict:
    stats = {"exists": os.path.isdir(path), "files": 0, "bytes": 0, "truncated": False}
    if not stats["exists"]:
        return stats
    try:
        for root, _dirs, files in os.walk(path):
            for name in files:
                stats["files"] += 1
                try:
                    stats["bytes"] += os.path.getsize(os.path.join(root, name))
                except OSError:
                    pass
                if stats["files"] >= max_entries:
                    stats["truncated"] = True
                    return stats
    except Exception as exc:
        stats["error"] = exc.__class__.__name__
    return stats

def _latest_backup_status() -> dict:
    status = {"dir": BACKUP_DIR, "exists": os.path.isdir(BACKUP_DIR), "latestFile": "", "latestSizeBytes": 0, "latestMtime": ""}
    if not status["exists"]:
        return status
    latest = None
    try:
        for name in os.listdir(BACKUP_DIR):
            path = os.path.join(BACKUP_DIR, name)
            if not os.path.isfile(path):
                continue
            if latest is None or os.path.getmtime(path) > os.path.getmtime(latest):
                latest = path
        if latest:
            status["latestFile"] = os.path.basename(latest)
            status["latestSizeBytes"] = os.path.getsize(latest)
            status["latestMtime"] = dt.datetime.utcfromtimestamp(os.path.getmtime(latest)).replace(microsecond=0).isoformat() + "Z"
    except Exception as exc:
        status["error"] = exc.__class__.__name__
    return status

def _git_dir_path() -> str:
    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    dot_git = os.path.join(root, ".git")
    if os.path.isdir(dot_git):
        return dot_git
    if os.path.isfile(dot_git):
        try:
            with open(dot_git, "r", encoding="utf-8") as f:
                raw = f.read().strip()
            if raw.startswith("gitdir:"):
                gitdir = raw.split(":", 1)[1].strip()
                return gitdir if os.path.isabs(gitdir) else os.path.abspath(os.path.join(root, gitdir))
        except Exception:
            return ""
    return ""

def _app_version() -> str:
    env_version = (os.getenv("APP_VERSION") or os.getenv("GIT_COMMIT") or "").strip()
    if env_version:
        return env_version[:12]
    git_dir = _git_dir_path()
    if not git_dir:
        return "unknown"
    try:
        head_path = os.path.join(git_dir, "HEAD")
        with open(head_path, "r", encoding="utf-8") as f:
            head = f.read().strip()
        if head.startswith("ref:"):
            ref_path = os.path.join(git_dir, head.split(" ", 1)[1].strip())
            with open(ref_path, "r", encoding="utf-8") as f:
                return f.read().strip()[:12]
        return head[:12]
    except Exception:
        return "unknown"

def _utc_now_iso() -> str:
    return dt.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

def _date_or_none(value):
    raw = str(value or "").strip()
    if not raw:
        return None
    if re.match(r"^\d{4}-\d{2}-\d{2}$", raw):
        return raw
    if re.match(r"^\d{4}-\d{2}-\d{2}T", raw):
        return raw[:10]
    return None

def _count_table(cur, table: str, where: str = "", params: tuple = ()) -> Optional[int]:
    allowed = {
        "projects", "users", "estimates", "work_journal", "materials",
        "warehouse_main", "supply_requests", "ai_tasks", "audit_log", "api_errors"
    }
    if table not in allowed:
        return None
    cur.execute("SELECT to_regclass(%s)", (table,))
    if not cur.fetchone()[0]:
        return None
    sql = f"SELECT COUNT(*) FROM {table}"
    if where:
        sql += " WHERE " + where
    cur.execute(sql, params)
    return int(cur.fetchone()[0] or 0)

@app.get("/health")
def health():
    started = time.time()
    db = {"ok": False}
    try:
        conn = get_db()
        cur = conn.cursor()
        cur.execute("SELECT 1")
        cur.fetchone()
        cur.close(); conn.close()
        db = {"ok": True, "latencyMs": round((time.time() - started) * 1000, 1)}
    except Exception as e:
        db = {"ok": False, "error": e.__class__.__name__}
    return {
        "ok": db["ok"],
        "status": "ok" if db["ok"] else "degraded",
        "service": "stroyka-backend",
        "time": _utc_now_iso(),
        "version": _app_version(),
        "db": db,
    }

DIRECTOR_AGENT_ROLES = ("директор", "system_owner")
DIRECTOR_AGENT_MAX_STEPS = 4
DIRECTOR_AGENT_URL = "https://llm.api.cloud.yandex.net/foundationModels/v1/completion"

# Keep the HTTP assistant and the background runner on one immutable read path.
DIRECTOR_AGENT_TOOLS = SHARED_DIRECTOR_AGENT_TOOLS

def _director_agent_extract_json(text: str):
    t = (text or "").strip()
    if "```" in t:
        parts = t.split("```")
        if len(parts) >= 3:
            t = parts[1].replace("json", "", 1).strip()
    start = t.find("{")
    end = t.rfind("}")
    if start >= 0 and end > start:
        t = t[start:end + 1]
    return json.loads(t)

def _director_agent_call_yandex(messages: list[dict], temperature: float = 0.2, max_tokens: int = 1600):
    if not YANDEX_API_KEY or not YANDEX_FOLDER_ID:
        raise HTTPException(status_code=503, detail="YANDEX_API_KEY / YANDEX_FOLDER_ID не настроены")
    payload = {
        "modelUri": f"gpt://{YANDEX_FOLDER_ID}/yandexgpt-lite/latest",
        "completionOptions": {"stream": False, "temperature": temperature, "maxTokens": max_tokens},
        "messages": messages,
    }
    req = urllib.request.Request(
        DIRECTOR_AGENT_URL,
        data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
        method="POST",
    )
    req.add_header("Authorization", "Api-Key " + YANDEX_API_KEY)
    req.add_header("Content-Type", "application/json")
    try:
        with urllib.request.urlopen(req, timeout=40) as resp:
            body = json.loads(resp.read().decode("utf-8"))
        return body["result"]["alternatives"][0]["message"]["text"]
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=502, detail="YandexGPT не ответил: " + str(e))

