    seed_users = [
        ('Директор', 'admin@stroyka.ru', 'admin123', 'директор'),
        ('Бухгалтер', 'buh@stroyka.ru', 'buh123', 'бухгалтер'),
        ('Прораб', 'prorab@stroyka.ru', 'prorab123', 'прораб'),
        ('Мастер', 'master@stroyka.ru', 'master123', 'мастер'),
    ]
    for seed_name, seed_email, seed_password, seed_role in seed_users:
        cur.execute("""
            INSERT INTO users (name, email, password, role)
            VALUES (%s,%s,%s,%s)
            ON CONFLICT (email) DO NOTHING
        """, (seed_name, seed_email, hash_password(seed_password), seed_role))
    cur.execute("UPDATE users SET two_factor_required=TRUE WHERE role IN ('директор','зам_директора','бухгалтер')")
    for group_key, item_key, label, value, value_type, unit, sort_order in SITE_PRICE_RULE_DEFAULTS:
        cur.execute("""
            INSERT INTO site_price_rules (group_key, item_key, label, value, value_type, unit, enabled, sort_order)
            VALUES (%s,%s,%s,%s,%s,%s,TRUE,%s)
            ON CONFLICT (group_key, item_key) DO NOTHING
        """, (group_key, item_key, label, value, value_type, unit, sort_order))
    for rule in DEFAULT_MATERIAL_NORMS:
        cur.execute("""
            INSERT INTO material_norms (
                rule_key, name, work_keywords, block_work_keywords, material_keywords,
                work_unit, material_unit, qty_per_unit, thickness_base_mm,
                default_thickness_mm, label, active
            )
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,TRUE)
            ON CONFLICT (rule_key) DO NOTHING
        """, (
            rule.get("ruleKey", ""),
            rule.get("name", ""),
            json.dumps(rule.get("work", []), ensure_ascii=False),
            json.dumps(rule.get("blockWork", []), ensure_ascii=False),
            json.dumps(rule.get("material", []), ensure_ascii=False),
            rule.get("workUnit", ""),
            rule.get("materialUnit", ""),
            rule.get("qtyPerUnit", 0),
            rule.get("thicknessBaseMm"),
            rule.get("defaultThicknessMm"),
            rule.get("label", ""),
        ))
    _startup_repair_saved_estimate_adjustments(cur)
    try:
        cur.execute(
            """
            INSERT INTO expenses (project, category, amount, note, date, added_by, own_expense_id, source, photo_url)
            SELECT
                COALESCE(NULLIF(oe.project_name,''),'') AS project,
                CASE WHEN COALESCE(NULLIF(oe.project_name,''),'')<>'' THEN 'other' ELSE %s END AS category,
                COALESCE(oe.amount,0) AS amount,
                CONCAT('Моя трата: ', COALESCE(oe.description,''), CASE WHEN COALESCE(oe.employee_name,'')<>'' THEN CONCAT(' · сотрудник: ', oe.employee_name) ELSE '' END) AS note,
                oe.date,
                COALESCE(oe.employee_name,'') AS added_by,
                oe.id AS own_expense_id,
                'own_expense' AS source,
                COALESCE(oe.photo_url,'') AS photo_url
            FROM own_expenses oe
            WHERE NOT EXISTS (
                SELECT 1 FROM expenses e WHERE e.own_expense_id=oe.id
            )
            """,
            (OWN_EXPENSE_NO_PROJECT_CATEGORY,),
        )
        cur.execute(
            """
            UPDATE own_expenses oe
               SET expense_id=e.id
              FROM expenses e
            WHERE e.own_expense_id=oe.id
               AND (oe.expense_id IS NULL OR oe.expense_id<>e.id)
            """
        )
        cur.execute(
            """
            UPDATE expenses e
               SET photo_url=oe.photo_url
              FROM own_expenses oe
             WHERE e.own_expense_id=oe.id
               AND COALESCE(e.photo_url,'')=''
               AND COALESCE(oe.photo_url,'')<>''
            """
        )
    except Exception as e:
        print("OWN EXPENSE BACKFILL ERROR:", e)
    conn.close()

