@app.get("/warehouse-movements")
def get_warehouse_movements(
    x_company_id: Optional[str] = Header(default=None, alias="X-Company-Id"),
    x_company_mode: Optional[str] = Header(default=None, alias="X-Company-Mode"),
    current_user: dict = Depends(get_current_user),
):
    conn = get_db()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    try:
        company_context = _resolve_work_company_context(
            cur,
            current_user,
            None,
            "read",
            x_company_id=x_company_id,
            x_company_mode=x_company_mode,
        )
        company_filter_sql, company_filter_params = company_id_scope_filter(company_context, "wm.company_id")
    except Exception:
        cur.close(); conn.close()
        raise
    select_sql = "SELECT wm.id,wm.material_name as \"materialName\",wm.from_location as \"fromLocation\",wm.to_location as \"toLocation\",wm.quantity,wm.unit,wm.work_package as \"workPackage\",wm.date,wm.created_by as \"createdBy\",wm.notes,wm.source_invoice_id as \"sourceInvoiceId\",wm.source_invoice_line_index as \"sourceInvoiceLineIndex\",wm.estimate_control_status as \"estimateControlStatus\",wm.estimate_control as \"estimateControl\",wm.estimate_review_task_id as \"estimateReviewTaskId\" FROM warehouse_movements wm WHERE TRUE"
    if current_user.get("role") == "прораб":
        projects = user_project_names(current_user)
        if not projects:
            cur.close(); conn.close()
            return []
        package_names = user_package_names(current_user)
        query = select_sql + company_filter_sql + " AND (wm.from_location = ANY(%s) OR wm.to_location = ANY(%s))"
        params = company_filter_params + [projects, projects]
        if package_names:
            query += " AND COALESCE(NULLIF(wm.work_package,''),'Основная') = ANY(%s)"
            params.append(package_names)
        cur.execute(query + " ORDER BY id DESC", tuple(params))
    elif current_user.get("role") in ("снабженец", "кладовщик"):
        projects = user_project_names(current_user)
        if not projects:
            cur.close(); conn.close()
            return []
        cur.execute(select_sql + company_filter_sql + " AND (wm.from_location = ANY(%s) OR wm.to_location = ANY(%s)) ORDER BY wm.id DESC", tuple(company_filter_params + [projects, projects]))
    elif current_user.get("role") in WAREHOUSE_ROLES or current_user.get("role") in FINANCE_ROLES:
        cur.execute(select_sql + company_filter_sql + " ORDER BY wm.id DESC", company_filter_params)
    else:
        cur.close(); conn.close()
        return []
    rows = cur.fetchall()
    conn.close()
    return [dict(r) for r in rows]

@app.post("/warehouse-movements")
def create_warehouse_movement(
    m: WarehouseMovementModel,
    x_company_id: Optional[str] = Header(default=None, alias="X-Company-Id"),
    x_company_mode: Optional[str] = Header(default=None, alias="X-Company-Mode"),
    _current_user: dict = Depends(require_roles(*WAREHOUSE_ROLES)),
):
    material_name = (m.materialName or "").strip()
    from_location = (m.fromLocation or "").strip()
    to_location = (m.toLocation or "").strip()
    work_package = (m.workPackage or "Основная").strip() or "Основная"
    qty = float(m.quantity or 0)
    if not material_name:
        raise HTTPException(status_code=400, detail="Укажите материал")
    if not from_location or not to_location:
        raise HTTPException(status_code=400, detail="Укажите откуда и куда переместить материал")
    if from_location == to_location:
        raise HTTPException(status_code=400, detail="Источник и получатель перемещения совпадают")
    if qty <= 0:
        raise HTTPException(status_code=400, detail="Количество должно быть больше нуля")
    if from_location != "Основной склад":
        require_project_or_warehouse_access(_current_user, from_location)
    if to_location != "Основной склад":
        require_project_or_warehouse_access(_current_user, to_location)
    if _current_user.get("role") in PACKAGE_LIMIT_ROLES and not has_package_access(_current_user, work_package or "Основная"):
        raise HTTPException(status_code=403, detail="Нет доступа к пакету материалов")
    if from_location == "Основной склад" and _current_user.get("role") not in MAIN_WAREHOUSE_WRITE_ROLES:
        raise HTTPException(status_code=403, detail="Перемещать материал с основного склада на объект может директор, замдиректора, снабженец или кладовщик")

    conn = get_db()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    requested_company_ids = {
        company_id for company_id in (
            _project_company_id(cur, from_location),
            _project_company_id(cur, to_location),
        ) if _positive_int_or_none(company_id)
    }
    if len(requested_company_ids) > 1:
        cur.close(); conn.close()
        raise HTTPException(status_code=409, detail="Источник и получатель относятся к разным компаниям")
    company_context = _resolve_work_company_context(
        cur,
        _current_user,
        next(iter(requested_company_ids), None),
        "write",
        x_company_id=x_company_id,
        x_company_mode=x_company_mode,
    )
    company_id = int(company_context.get("companyId") or 0)
    if company_id <= 0:
        cur.close(); conn.close()
        raise HTTPException(status_code=409, detail="Компания перемещения не определена")
    conn.autocommit = False
    try:
        movement_estimate_control = build_movement_estimate_control([])
        source_invoice_id = m.invoiceId
        source_invoice_line_index = m.invoiceLineIndex
        selected_receipt_lot = None
        if source_invoice_id is not None or source_invoice_line_index is not None:
            cur.execute("""SELECT id,number,project,location,items
                           FROM warehouse_invoices
                           WHERE id=%s AND company_id=%s
                             AND COALESCE(status,'Принята') <> 'Аннулирована'""", (source_invoice_id, company_id))
            invoice_row = cur.fetchone()
            try:
                from backend.features.material_traceability.service import ensure_source_quantity_available, resolve_invoice_line_source
            except ModuleNotFoundError:
                from features.material_traceability.service import ensure_source_quantity_available, resolve_invoice_line_source
            try:
                source_reference = resolve_invoice_line_source(source_invoice_id, source_invoice_line_index, invoice_row)
            except ValueError as exc:
                raise HTTPException(status_code=400, detail=str(exc))
            invoice_location = (invoice_row.get("project") or "").strip() or (invoice_row.get("location") or "").strip()
            if invoice_location != from_location:
                raise HTTPException(status_code=400, detail="Выбранная строка накладной относится к другому складу или объекту")
            invoice_items = _json_list_or_empty(invoice_row.get("items"))
            source_item = invoice_items[source_reference["invoiceLineIndex"]]
            source_item_name = str(
                (source_item or {}).get("name")
                or (source_item or {}).get("materialName")
                or (source_item or {}).get("title")
                or ""
            ).strip().lower()
            source_item_unit = _norm_base_unit((source_item or {}).get("unit") or "шт") or "шт"
            requested_unit = _norm_base_unit(m.unit or "") if (m.unit or "").strip() else source_item_unit
            if source_item_name != material_name.lower() or source_item_unit != requested_unit:
                raise HTTPException(status_code=400, detail="Выбранная строка накладной не совпадает с перемещаемым материалом")
            cur.execute("""SELECT COALESCE(SUM(quantity),0) AS allocated_quantity
                           FROM warehouse_movements
                           WHERE company_id=%s AND source_invoice_id=%s AND source_invoice_line_index=%s""",
                        (company_id, source_reference["invoiceId"], source_reference["invoiceLineIndex"]))
            allocated_quantity = float((cur.fetchone() or {}).get("allocated_quantity") or 0)
            try:
                ensure_source_quantity_available(source_item, allocated_quantity, qty)
            except ValueError as exc:
                raise HTTPException(
                    status_code=400,
                    detail="По выбранной строке накладной доступно " + str(exc) + " " + source_item_unit,
                )
            source_invoice_id = source_reference["invoiceId"]
            source_invoice_line_index = source_reference["invoiceLineIndex"]
            try:
                from backend.features.material_traceability.receipt_lots import (
                    ensure_receipt_lot_schema,
                    lock_receipt_lot_for_movement,
                )
            except ModuleNotFoundError:
                from features.material_traceability.receipt_lots import (
                    ensure_receipt_lot_schema,
                    lock_receipt_lot_for_movement,
                )
            ensure_receipt_lot_schema(cur)
            try:
                selected_receipt_lot = lock_receipt_lot_for_movement(
                    cur,
                    company_id=company_id,
                    warehouse_invoice_id=source_invoice_id,
                    invoice_line_index=source_invoice_line_index,
                    warehouse_location=from_location,
                    material_name=material_name,
                    unit=requested_unit,
                    requested_quantity=qty,
                )
            except ValueError as exc:
                raise HTTPException(status_code=400, detail=str(exc))
        source_price = 0
        source_category = ""
        source_unit = _norm_base_unit(m.unit or "") if (m.unit or "").strip() else ""
        if from_location == "Основной склад":
            cur.execute(f"""SELECT id,quantity,unit,price,category FROM warehouse_main
                           WHERE LOWER(name)=LOWER(%s)
                             AND company_id=%s
                             AND (%s='' OR {_sql_norm_unit('unit')}=%s)
                           ORDER BY id LIMIT 1 FOR UPDATE""", (material_name, company_id, source_unit, source_unit))
            source = cur.fetchone()
            if not source:
                raise HTTPException(status_code=400, detail="Материал «"+material_name+"» не найден на основном складе")
            if float(source.get("quantity") or 0) < qty:
                raise HTTPException(status_code=400, detail="На основном складе недостаточно материала «"+material_name+"»")
            source_unit = source_unit or _norm_base_unit(source.get("unit") or "шт") or "шт"
            source_price = float(source.get("price") or 0)
            source_category = source.get("category") or ""
            cur.execute("UPDATE warehouse_main SET quantity=COALESCE(quantity,0)-%s WHERE id=%s", (qty, source["id"]))
        else:
            cur.execute(f"""SELECT id,quantity,unit,price,category FROM materials
                           WHERE LOWER(name)=LOWER(%s)
                             AND project=%s
                             AND company_id=%s
                             AND COALESCE(NULLIF(work_package,''),'Основная')=%s
                             AND (%s='' OR {_sql_norm_unit('unit')}=%s)
                           ORDER BY id LIMIT 1 FOR UPDATE""", (material_name, from_location, company_id, work_package, source_unit, source_unit))
            source = cur.fetchone()
            if not source:
                raise HTTPException(status_code=400, detail="Материал «"+material_name+"» не найден на складе объекта «"+from_location+"»" + (" по пакету «"+work_package+"»" if work_package else ""))
            if float(source.get("quantity") or 0) < qty:
                raise HTTPException(status_code=400, detail="На складе объекта недостаточно материала «"+material_name+"»")
            source_unit = source_unit or _norm_base_unit(source.get("unit") or "шт") or "шт"
            source_price = float(source.get("price") or 0)
            source_category = source.get("category") or ""
            cur.execute("UPDATE materials SET quantity=COALESCE(quantity,0)-%s WHERE id=%s", (qty, source["id"]))

        if to_location != "Основной склад":
            movement_control_items = [{
                "materialName": material_name,
                "quantity": qty,
                "unit": source_unit,
                "workPackage": work_package,
            }]
            _attach_supply_estimate_control(
                cur,
                to_location,
                movement_control_items,
                company_id=company_id,
            )
            movement_estimate_control = build_movement_estimate_control(movement_control_items)
            work_package = _supply_work_package(movement_control_items[0].get("workPackage") or work_package)

        if to_location == "Основной склад":
            cur.execute(f"""SELECT id FROM warehouse_main
                           WHERE LOWER(name)=LOWER(%s)
                             AND company_id=%s
                             AND {_sql_norm_unit('unit')}=%s
                           ORDER BY id LIMIT 1 FOR UPDATE""", (material_name, company_id, source_unit))
            target = cur.fetchone()
            if target:
                cur.execute("""UPDATE warehouse_main
                               SET quantity=COALESCE(quantity,0)+%s,
                                   unit=COALESCE(NULLIF(%s,''), unit),
                                   price=CASE WHEN %s > 0 THEN %s ELSE price END,
                                   category=COALESCE(NULLIF(%s,''), category)
                               WHERE id=%s""", (qty, source_unit, source_price, source_price, source_category, target["id"]))
            else:
                cur.execute("""INSERT INTO warehouse_main (name,unit,quantity,price,min_quantity,category,company_id)
                               VALUES (%s,%s,%s,%s,%s,%s,%s)""",
                            (material_name, source_unit, qty, source_price, 0, source_category, company_id))
        else:
            cur.execute(f"""SELECT id FROM materials
                           WHERE LOWER(name)=LOWER(%s)
                             AND project=%s
                             AND company_id=%s
                             AND COALESCE(NULLIF(work_package,''),'Основная')=%s
                             AND {_sql_norm_unit('unit')}=%s
                           ORDER BY id LIMIT 1 FOR UPDATE""", (material_name, to_location, company_id, work_package, source_unit))
            target = cur.fetchone()
            if target:
                cur.execute("""UPDATE materials
                               SET quantity=COALESCE(quantity,0)+%s,
                                   unit=COALESCE(NULLIF(%s,''), unit),
                                   price=CASE WHEN %s > 0 THEN %s ELSE price END,
                                   category=COALESCE(NULLIF(%s,''), category)
                               WHERE id=%s""", (qty, source_unit, source_price, source_price, source_category, target["id"]))
            else:
                cur.execute("""INSERT INTO materials (name,unit,quantity,price,min_quantity,project,category,work_package,company_id)
                               VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                            (material_name, source_unit, qty, source_price, 0, to_location, source_category, work_package, company_id))

        cur.execute("""INSERT INTO warehouse_movements
                          (material_name,from_location,to_location,quantity,unit,work_package,date,created_by,notes,company_id,
                           source_invoice_id,source_invoice_line_index,estimate_control_status,estimate_control)
                       VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s) RETURNING
                          id,material_name as "materialName",from_location as "fromLocation",
                          to_location as "toLocation",quantity,unit,work_package as "workPackage",
                          date,created_by as "createdBy",notes,source_invoice_id as "sourceInvoiceId",
                          source_invoice_line_index""",
                    (material_name, from_location, to_location, qty, source_unit, work_package, m.date, m.createdBy or _current_user.get("name",""), m.notes, company_id,
                     source_invoice_id, source_invoice_line_index, movement_estimate_control["status"], psycopg2.extras.Json(movement_estimate_control)))
        row = cur.fetchone()
        row["sourceInvoiceLineIndex"] = row.pop("source_invoice_line_index", None)
        row["estimateControlStatus"] = movement_estimate_control["status"]
        row["estimateControl"] = movement_estimate_control
        actor_name = m.createdBy or _current_user.get("name","")
        if selected_receipt_lot:
            try:
                from backend.features.material_traceability.receipt_lots import consume_receipt_lot
            except ModuleNotFoundError:
                from features.material_traceability.receipt_lots import consume_receipt_lot
            try:
                consume_receipt_lot(
                    cur,
                    lot=selected_receipt_lot,
                    warehouse_movement_id=row["id"],
                    quantity=qty,
                    from_location=from_location,
                    to_location=to_location,
                    created_by=actor_name,
                )
            except ValueError as exc:
                raise HTTPException(status_code=409, detail=str(exc))
        date_time = dt.datetime.now().strftime("%d.%m.%Y, %H:%M")
        cur.execute("""INSERT INTO warehouse_history
                          (company_id,material,type,quantity,unit,date,project,issued_to,issued_by,work_package,date_time,
                           source_type,source_id,source_invoice_id,source_invoice_line_index)
                       VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                    (company_id, material_name, "перемещение: списание", qty, source_unit, m.date or None, from_location, to_location, actor_name, work_package, date_time,
                     "warehouse_movement", row["id"], source_invoice_id, source_invoice_line_index))
        cur.execute("""INSERT INTO warehouse_history
                          (company_id,material,type,quantity,unit,date,project,issued_to,issued_by,work_package,date_time,
                           source_type,source_id,source_invoice_id,source_invoice_line_index)
                       VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                    (company_id, material_name, "перемещение: приход", qty, source_unit, m.date or None, to_location, from_location, actor_name, work_package, date_time,
                     "warehouse_movement", row["id"], source_invoice_id, source_invoice_line_index))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        cur.close(); conn.close()
    movement_result = dict(row)
    review_task = _create_warehouse_movement_review_task_safely(
        movement_result,
        to_location,
        company_id,
        _current_user,
    )
    if review_task.get("taskId"):
        movement_result["estimateReviewTaskId"] = review_task["taskId"]
        movement_result["estimateReviewTaskCreated"] = bool(review_task.get("created"))
    _run_project_ai_control_safely(to_location if to_location != "Основной склад" else from_location, "warehouse_movement:create")
    return movement_result

@app.get("/warehouse-history")
def get_warehouse_history(
    x_company_id: Optional[str] = Header(default=None, alias="X-Company-Id"),
    x_company_mode: Optional[str] = Header(default=None, alias="X-Company-Mode"),
    current_user: dict = Depends(get_current_user),
):
    conn = get_db()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    try:
        company_context = _resolve_work_company_context(
            cur,
            current_user,
            None,
            "read",
            x_company_id=x_company_id,
            x_company_mode=x_company_mode,
        )
        company_filter_sql, company_filter_params = company_id_scope_filter(company_context, "wh.company_id")
    except Exception:
        cur.close(); conn.close()
        raise
    select_sql = "SELECT wh.id,wh.material,wh.type,wh.quantity,wh.date,wh.project,wh.issued_to as \"issuedTo\",wh.issued_by as \"issuedBy\",wh.work_package as \"workPackage\",wh.date_time as \"dateTime\",wh.source_type as \"sourceType\",wh.source_id as \"sourceId\",wh.source_invoice_id as \"sourceInvoiceId\",wh.source_invoice_line_index as \"sourceInvoiceLineIndex\" FROM warehouse_history wh WHERE TRUE"
    role = current_user.get("role")
    if role == "прораб":
        projects = user_project_names(current_user)
        if not projects:
            cur.close(); conn.close()
            return []
        package_names = user_package_names(current_user)
        query = select_sql + company_filter_sql + " AND wh.project = ANY(%s)"
        params = company_filter_params + [projects]
        if package_names:
            query += " AND COALESCE(NULLIF(wh.work_package,''),'Основная') = ANY(%s)"
            params.append(package_names)
        cur.execute(query + " ORDER BY id DESC", tuple(params))
    elif role in WORKER_EXECUTION_ROLES:
        package_names = user_package_names(current_user)
        if not package_names:
            cur.close(); conn.close()
            return []
        query = select_sql + company_filter_sql + " AND (wh.issued_by=%s OR wh.issued_to=%s)"
        params = company_filter_params + [current_user.get("name",""), current_user.get("name","")]
        query += " AND COALESCE(NULLIF(wh.work_package,''),'Основная') = ANY(%s)"
        params.append(package_names)
        cur.execute(query + " ORDER BY id DESC", tuple(params))
    elif role in WAREHOUSE_ROLES or role in FINANCE_ROLES:
        cur.execute(select_sql + company_filter_sql + " ORDER BY wh.id DESC", company_filter_params)
    else:
        cur.close(); conn.close()
        return []
    rows = cur.fetchall()
    conn.close()
    return [dict(r) for r in rows]

@app.post("/warehouse-history")
def create_warehouse_history(
    h: WarehouseHistoryModel,
    x_company_id: Optional[str] = Header(default=None, alias="X-Company-Id"),
    x_company_mode: Optional[str] = Header(default=None, alias="X-Company-Mode"),
    _current_user: dict = Depends(get_current_user),
):
    movement_type = (h.type or "").strip()
    if not movement_type.startswith("ручная корректировка"):
        raise HTTPException(
            status_code=400,
            detail="Прямое создание складских приходов, списаний и перемещений запрещено. Используйте накладную, перемещение или ЖПР.",
        )
    if not h.material or float(h.quantity or 0) <= 0:
        raise HTTPException(status_code=400, detail="Укажите материал и положительное количество")
    work_package = (h.workPackage or "").strip()
    conn = get_db()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    try:
        project_company_id = _project_company_id(cur, h.project)
        company_context = _resolve_work_company_context(
            cur,
            _current_user,
            project_company_id,
            "write",
            x_company_id=x_company_id,
            x_company_mode=x_company_mode,
        )
        company_id = int(company_context.get("companyId") or 0)
        actors = effective_company_actors(_current_user, company_context)
        actor = actors[0] if len(actors) == 1 else {}
        if company_id <= 0 or not actor:
            raise HTTPException(status_code=409, detail="Компания складской корректировки не определена")
        if (actor.get("role") or "") not in LEADERSHIP_ROLES:
            raise HTTPException(status_code=403, detail="Ручную запись истории склада может добавить только директор или замдиректора выбранной компании")
        if h.project:
            require_project_or_warehouse_access(actor, h.project)
        if not has_package_access(actor, work_package or "Основная"):
            raise HTTPException(status_code=403, detail="Нет доступа к разделу сметы движения: " + (work_package or "Основная"))
        unit = (h.unit or "шт").strip() or "шт"
        cur.execute("INSERT INTO warehouse_history (material,type,quantity,unit,date,project,issued_to,issued_by,work_package,date_time,company_id) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s) RETURNING *",
            (h.material,movement_type,h.quantity,unit,h.date,h.project,h.issuedTo,h.issuedBy,work_package,h.dateTime,company_id))
        row = cur.fetchone()
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        cur.close(); conn.close()
    return dict(row)

@app.delete("/warehouse-history/{id}")
def delete_warehouse_history(
    id: int,
    x_company_id: Optional[str] = Header(default=None, alias="X-Company-Id"),
    x_company_mode: Optional[str] = Header(default=None, alias="X-Company-Mode"),
    _current_user: dict = Depends(get_current_user),
):
    conn = get_db()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    try:
        cur.execute("SELECT project,company_id FROM warehouse_history WHERE id=%s", (id,))
        row = cur.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Запись движения склада не найдена")
        _context, actor = resolve_resource_company_actor(
            cur,
            _current_user,
            row.get("company_id"),
            "delete",
            x_company_id=x_company_id,
            x_company_mode=x_company_mode,
            allowed_roles=WAREHOUSE_ROLES,
            forbidden_detail="Роль в выбранной компании не позволяет работать с историей склада",
            platform_staff_roles=PLATFORM_STAFF_ROLES,
            client_account_roles=CLIENT_ACCOUNT_ROLES,
        )
        project_name = row.get("project") or ""
        if project_name:
            require_project_or_warehouse_access(actor, project_name)
    finally:
        cur.close(); conn.close()
    raise HTTPException(
        status_code=409,
        detail="Удаление записей движения склада запрещено: в warehouse_history нет полей статуса/сторно, физическое удаление нарушает аудит склада",
    )

PROJECT_SCOPED_ACCESS_ROLES = ("прораб", "главный_инженер", "технадзор", "стройконтроль", "мастер", "субподрядчик", "бригадир")
WORK_PACKAGE_REQUIRED_ACCESS_ROLES = ("мастер", "субподрядчик", "бригадир")

def _validate_user_access_scope(role: str, project_name: str = "", assigned_projects=None, assigned_packages=None):
    projects = _safe_project_list(assigned_projects or [])
    packages = _safe_project_list(assigned_packages or [])
    project = (project_name or "").strip()
    if role in PROJECT_SCOPED_ACCESS_ROLES and not project and not projects:
        raise HTTPException(status_code=400, detail="Для роли «"+role+"» нужно назначить хотя бы один объект")
    if role in WORK_PACKAGE_REQUIRED_ACCESS_ROLES and not packages:
        raise HTTPException(status_code=400, detail="Для роли «"+role+"» нужно назначить разделы сметы/виды работ")
    return projects, packages

def _prepare_user_access_scope(cur, role: str, project_name: str = "", assigned_projects=None, assigned_packages=None):
    projects = _safe_project_list(assigned_projects or [])
    packages = _safe_project_list(assigned_packages or [])
    project = (project_name or "").strip()
    if project and project not in projects and role in PROJECT_SCOPED_ACCESS_ROLES:
        projects.append(project)
    if role == "прораб" and projects and not packages:
        cur.execute("""SELECT DISTINCT COALESCE(NULLIF(work_package,''),'Основная') AS work_package
                       FROM estimates
                       WHERE project_name = ANY(%s)
                         AND COALESCE(status,'Активная')='Активная'
                       ORDER BY 1""", (projects,))
        packages = [r.get("work_package") if isinstance(r, dict) else r[0] for r in cur.fetchall()]
    return _validate_user_access_scope(role, project, projects, packages)


def _grant_user_project_package_access(cur, user_id, project_name: str = "", work_package: str = ""):
    try:
        uid = int(user_id or 0)
    except Exception:
        uid = 0
    project = (project_name or "").strip()
    package = (work_package or "Основная").strip() or "Основная"
    if uid <= 0 or not project:
        return None
    cur.execute("""SELECT id, role, project_name, assigned_projects, assigned_packages
                   FROM users WHERE id=%s FOR UPDATE""", (uid,))
    row = cur.fetchone()
    if not row:
        return None
    role = (row.get("role") if isinstance(row, dict) else row[1]) or ""
    if role not in PROJECT_SCOPED_ACCESS_ROLES:
        return None
    current_project = (row.get("project_name") if isinstance(row, dict) else row[2]) or ""
    raw_projects = row.get("assigned_projects") if isinstance(row, dict) else row[3]
    raw_packages = row.get("assigned_packages") if isinstance(row, dict) else row[4]
    projects = _safe_project_list(raw_projects or [])
    packages = _safe_project_list(raw_packages or [])
    if project not in projects:
        projects.append(project)
    if role in WORK_PACKAGE_REQUIRED_ACCESS_ROLES and package not in packages:
        packages.append(package)
    next_project = current_project or project
    cur.execute("""UPDATE users
                      SET project_name=%s,
                          assigned_projects=%s::jsonb,
                          assigned_packages=%s::jsonb,
                          active=TRUE
                    WHERE id=%s""",
                (next_project, json.dumps(projects, ensure_ascii=False), json.dumps(packages, ensure_ascii=False), uid))
    return {"id": uid, "project": next_project, "assignedProjects": projects, "assignedPackages": packages}

def _resolve_staff_or_user_id(cur, actor_id, actor_name: str = ""):
    try:
        raw_id = int(actor_id or 0)
    except Exception:
        raw_id = 0
    actor = (actor_name or "").strip()
    if raw_id > 0:
        cur.execute("SELECT id FROM users WHERE id=%s LIMIT 1", (raw_id,))
        row = cur.fetchone()
        if row:
            return raw_id
        cur.execute("""SELECT name, email_work, email_personal
                       FROM staff WHERE id=%s LIMIT 1""", (raw_id,))
        staff_row = cur.fetchone()
        if staff_row:
            staff_name = (staff_row.get("name") if isinstance(staff_row, dict) else staff_row[0]) or actor
            email_work = (staff_row.get("email_work") if isinstance(staff_row, dict) else staff_row[1]) or ""
            email_personal = (staff_row.get("email_personal") if isinstance(staff_row, dict) else staff_row[2]) or ""
            emails = [x.strip().lower() for x in (email_work, email_personal) if x and x.strip()]
            if emails:
                cur.execute("SELECT id FROM users WHERE LOWER(COALESCE(email,'')) = ANY(%s) ORDER BY id LIMIT 1", (emails,))
                row = cur.fetchone()
                if row:
                    return row.get("id") if isinstance(row, dict) else row[0]
            actor = staff_name or actor
    if actor:
        cur.execute("SELECT id FROM users WHERE LOWER(COALESCE(name,''))=LOWER(%s) ORDER BY id LIMIT 1", (actor,))
        row = cur.fetchone()
        if row:
            return row.get("id") if isinstance(row, dict) else row[0]
    return raw_id or None


@app.get("/piecework")
def get_piecework(current_user: dict = Depends(get_current_user)):
    conn = get_db()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    allowed_projects = visible_project_names(current_user)
    cols = "id,staff_id as \"staffId\",description,unit,quantity,price_per_unit as \"pricePerUnit\",total,project,date,comment,photo_url as \"photoUrl\",work_journal_id as \"workJournalId\""
    active_clause = """NOT EXISTS (
        SELECT 1 FROM work_journal wj
        WHERE wj.id = piecework.work_journal_id
          AND COALESCE(wj.status,'') = 'Отклонено'
    )"""
    if current_user.get("role") in WORKER_EXECUTION_ROLES:
        cur.execute(f"""SELECT {cols} FROM piecework
                        WHERE {active_clause}
                          AND (staff_id=%s OR EXISTS (
                              SELECT 1 FROM work_journal wj
                              WHERE wj.id = piecework.work_journal_id
                                AND (COALESCE(wj.master_id,0)=%s OR (COALESCE(wj.master_id,0)=0 AND LOWER(TRIM(COALESCE(wj.master_name,'')))=LOWER(TRIM(%s))))
                          ))
                        ORDER BY id DESC""",
                    (str(current_user.get("id")), current_user.get("id"), current_user.get("name") or ""))
    elif allowed_projects is None:
        cur.execute(f"SELECT {cols} FROM piecework WHERE {active_clause} ORDER BY id DESC")
    elif not allowed_projects:
        cur.execute(f"SELECT {cols} FROM piecework WHERE {active_clause} AND staff_id=%s ORDER BY id DESC", (str(current_user.get("id")),))
    else:
        cur.execute(f"SELECT {cols} FROM piecework WHERE {active_clause} AND (project = ANY(%s) OR staff_id=%s) ORDER BY id DESC", (allowed_projects, str(current_user.get("id"))))
    rows = cur.fetchall()
    conn.close()
    return [dict(r) for r in rows]

@app.post("/piecework")
def create_piecework(p: PieceworkModel, _current_user: dict = Depends(require_roles(*JOURNAL_WRITE_ROLES))):
    require_project_access(_current_user, p.project)
    if _current_user.get("role") in WORKER_EXECUTION_ROLES:
        raise HTTPException(status_code=403, detail="Сдельное начисление создаётся только после проверки ЖПР прорабом/руководителем")
    conn = get_db()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    if p.workJournalId:
        work = require_work_journal_actor_access(cur, p.workJournalId, _current_user)
        cur.execute("SELECT id FROM piecework WHERE work_journal_id=%s LIMIT 1", (p.workJournalId,))
        existing = cur.fetchone()
        if existing:
            conn.close()
            return dict(existing)
        cur.execute("""SELECT master_id, master_name, project, description, unit, quantity,
                              execution_price_per_unit, execution_total, date
                       FROM work_journal
                       WHERE id=%s AND COALESCE(status,'')='Подтверждено'""", (p.workJournalId,))
        work_row = cur.fetchone()
        if not work_row:
            conn.close()
            raise HTTPException(status_code=400, detail="Сдельное начисление можно создать только по подтверждённой записи ЖПР")
        p.staffId = str(work_row.get("master_id") or p.staffId or "")
        p.project = work_row.get("project") or work.get("project") or p.project
        p.description = work_row.get("description") or p.description
        p.unit = work_row.get("unit") or p.unit
        p.quantity = float(work_row.get("quantity") or 0)
        p.pricePerUnit = float(work_row.get("execution_price_per_unit") or 0)
        p.total = float(work_row.get("execution_total") or (p.quantity * p.pricePerUnit))
        p.date = str(work_row.get("date") or p.date or "")
    else:
        conn.close()
        raise HTTPException(status_code=400, detail="Ручные сдельные начисления отключены. Закрывайте работу через ЖПР: подтверждённая запись сама формирует сумму исполнителя и акт бухгалтерии.")
    cur.execute("INSERT INTO piecework (staff_id,description,unit,quantity,price_per_unit,total,project,date,comment,photo_url,work_journal_id) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s) RETURNING *",
                (p.staffId,p.description,p.unit,p.quantity,p.pricePerUnit,p.total,p.project,p.date,p.comment,p.photoUrl,p.workJournalId))
    row = cur.fetchone()
    conn.close()
    return dict(row)

@app.delete("/piecework/{id}")
def delete_piecework(id: int, _current_user: dict = Depends(require_roles("директор"))):
    conn = get_db()
    cur = conn.cursor()
    require_row_project_access(cur, "piecework", id, _current_user, "project")
