def _material_family_tags(tokens: set[str]) -> set[str]:
    t = set(tokens or [])
    families: set[str] = set()
    if t.intersection({"клей"}):
        families.add("adhesive")
    if t.intersection({"штукатурка", "ротбанд"}) or ("смесь" in t and t.intersection({"хабез", "старт"})):
        families.add("plaster")
    if t.intersection({"шпатлевка"}) and "штукатурка" not in t:
        families.add("putty")
    if t.intersection({"грунтовка"}):
        families.add("primer")
    if t.intersection({"цемент"}) and not families.intersection({"plaster", "putty", "adhesive"}):
        families.add("cement")
    if t.intersection({"бетон"}):
        families.add("concrete")
    if t.intersection({"песок"}):
        families.add("sand")
    if not t.intersection({"клей"}) and t.intersection({"керамогранит", "плитка", "гранит", "керамическ"}):
        families.add("tile")
    if t.intersection({"гкл", "гипсокартон"}):
        families.add("gkl")
    if t.intersection({"гвл", "гипсоволокно"}):
        families.add("gvl")
    if t.intersection({"профиль", "уголок", "подвес", "маяк", "рейка", "направляющая", "пн", "пп", "пс", "псу", "cd", "ud", "cw", "uw"}):
        families.add("metal_profile")
    if t.intersection({"саморез", "анкер", "болт", "гайка", "шайба", "дюбель", "крепеж", "гвоздь", "шпилька", "скрепа", "прессшайба", "скоба", "хомут", "клин", "кронштейн"}):
        families.add("fastener")
    if t.intersection({"кабель", "провод"}):
        families.add("cable")
    if t.intersection({"труба", "фитинг", "муфта", "клапан", "американка", "кран", "полипропилен", "канализация", "тройник", "отвод", "ниппель", "переход", "заглушка", "коллектор", "инженерия"}):
        families.add("pipe")
    if t.intersection({"светильник", "лампа", "свет", "светодиод", "прожектор"}):
        families.add("light")
    if t.intersection({"розетка", "выключатель", "автомат", "щит", "электрика"}):
        families.add("electrical_device")
    if t.intersection({"радиатор", "биметалл", "воздухоотводчик"}):
        families.add("heating")
    if t.intersection({"металлочерепица", "черепица", "кровля", "монтеррей"}):
        families.add("roofing")
    if t.intersection({"доска", "брус", "фанера", "осп"}):
        families.add("wood_sheet")
    if t.intersection({"арматура"}):
        families.add("rebar")
    if t.intersection({"краска", "эмаль", "лак"}):
        families.add("paint")
    if t.intersection({"герметик", "силикон", "пена"}):
        families.add("sealant")
    if t.intersection({"раствор", "алебастр", "гипс", "известь"}) and not families.intersection({"plaster", "putty"}):
        families.add("binder_mix")
    return families

def _material_family_match_score(left_tokens: set[str], right_tokens: set[str]) -> float:
    common_families = _material_family_tags(left_tokens).intersection(_material_family_tags(right_tokens))
    if not common_families:
        return 0.0
    high_confidence = {
        "plaster", "putty", "primer", "cement", "tile", "gkl", "gvl",
        "metal_profile", "fastener", "cable", "pipe", "roofing",
        "paint", "sealant", "adhesive", "light", "heating", "electrical_device",
    }
    if common_families.intersection(high_confidence):
        return 0.82
    return 0.76

def _material_name_match_score(left: str, right: str) -> float:
    left_key = _norm_key_text(left or "")
    right_key = _norm_key_text(right or "")
    if not left_key or not right_key:
        return 0.0
    if left_key == right_key:
        return 1.0
    if len(left_key) >= 10 and len(right_key) >= 10 and (left_key in right_key or right_key in left_key):
        return 0.92
    left_tokens = _material_match_tokens(left_key)
    right_tokens = _material_match_tokens(right_key)
    if not left_tokens or not right_tokens:
        return 0.0
    common = left_tokens.intersection(right_tokens)
    family_score = _material_family_match_score(left_tokens, right_tokens)
    if not common:
        safe_family_only = {
            "tile", "plaster", "putty", "primer", "cement", "concrete",
            "gkl", "gvl", "metal_profile", "fastener", "cable", "pipe",
            "roofing", "paint", "sealant", "adhesive", "light", "heating",
            "electrical_device",
        }
        common_families = _material_family_tags(left_tokens).intersection(_material_family_tags(right_tokens))
        return family_score if common_families.intersection(safe_family_only) else 0.0
    # Типовые накладные часто называют один и тот же материал иначе, чем ГРАНД:
    # "керамогранит" против "гранит керамический", "ГКЛ" против "лист гипсокартонный".
    strong_families = {
        "керамогранит", "гранит", "керамическ", "гкл", "гипсокартон", "гвл",
        "гипсоволокно", "грунтовка", "штукатурка", "шпатлевка", "профиль",
        "кабель", "провод", "труба", "радиатор", "скрепа", "дюбель",
        "кронштейн", "направляющая", "цемент", "бетон", "песок",
        "саморез", "анкер", "болт", "гайка", "шайба", "прессшайба", "светильник",
        "свет", "светодиод", "прожектор", "розетка", "выключатель", "автомат",
        "щит", "электрика", "втулка", "хомут", "скоба", "крепеж",
        "кран", "клей", "плитка", "металлочерепица", "черепица", "кровля",
        "монтеррей", "livorno", "axima", "смесь", "ротбанд", "кнауф",
        "пескобетон", "наливной", "ровнитель", "затирка", "уголок", "подвес",
        "маяк", "рейка", "лента", "серпянка", "пн", "пп", "пс", "псу",
        "cd", "ud", "cw", "uw", "лампа", "фитинг", "муфта", "тройник",
        "отвод", "ниппель", "переход", "заглушка", "коллектор", "клапан",
        "американка", "воздухоотводчик", "полипропилен", "канализация",
        "доска", "брус", "фанера", "осп", "арматура", "гвоздь", "шпилька",
        "перфолента", "краска", "эмаль", "лак", "герметик", "силикон",
        "пена", "раствор", "алебастр", "гипс", "известь",
    }
    if {"металлочерепица", "черепица"}.intersection(left_tokens) and {"металлочерепица", "черепица"}.intersection(right_tokens):
        return 0.84
    if {"керамогранит", "плитка"}.intersection(left_tokens) and {"керамогранит", "плитка"}.intersection(right_tokens) and {"livorno", "axima", "гранит", "керамическ", "матов", "глазур"}.intersection(common):
        return 0.86
    if {"ротбанд", "кнауф", "смесь", "хабез", "старт"}.intersection(left_tokens) and {"ротбанд", "кнауф", "смесь", "хабез", "старт"}.intersection(right_tokens) and {"штукатурка", "шпатлевка", "смесь", "ротбанд", "кнауф"}.intersection(common):
        return 0.84
    if {"гранит", "керамическ"}.issubset(common):
        return 0.86
    if {"гкл", "гипсокартон"}.intersection(left_tokens) and {"гкл", "гипсокартон"}.intersection(right_tokens):
        return 0.84
    if {"гвл", "гипсоволокно"}.intersection(left_tokens) and {"гвл", "гипсоволокно"}.intersection(right_tokens):
        return 0.84
    if family_score:
        return max(family_score, 0.78)
    strong_common = common.intersection(strong_families)
    score = len(common) / max(1, min(len(left_tokens), len(right_tokens)))
    long_common = [t for t in common if len(t) >= 6]
    if strong_common and len(common) >= 2:
        return min(0.82, max(score + 0.2, 0.62))
    if len(common) >= 3 and score >= 0.45:
        return min(0.9, score + 0.15)
    if len(common) >= 2 and long_common and score >= 0.4:
        return min(0.82, score + 0.1)
    if len(long_common) >= 1 and score >= 0.65:
        return min(0.72, score)
    return score if score >= 0.7 else 0.0

def _material_units_compatible(unit_a: str = "", unit_b: str = "") -> bool:
    base_a = _norm_base_unit(unit_a or "")
    base_b = _norm_base_unit(unit_b or "")
    return not base_a or not base_b or base_a == base_b

def _supply_material_estimate_control(cur, project_owner: dict, material_name: str, unit: str = "", work_package: str = "", exclude_request_id=None, exclude_stock_qty: float = 0.0):
    try:
        from backend.features.estimate_material_plan.service import is_resource_adjustment, material_plan_contribution
    except ModuleNotFoundError:
        from features.estimate_material_plan.service import is_resource_adjustment, material_plan_contribution
    project = str((project_owner or {}).get("name") or "").strip()
    company_id = _positive_int_or_none((project_owner or {}).get("companyId"))
    project_id = _positive_int_or_none((project_owner or {}).get("id"))
    material_name = (material_name or "").strip()
    if not project or not company_id or not project_id or not material_name:
        return None
    package = _supply_work_package(work_package)
    target_key = _material_control_key_resolved(cur, project, material_name, unit)
    planned_qty = planned_sum = 0.0
    matched_rows = 0
    fuzzy_matched_rows = 0
    unit_mismatch_matched_rows = 0
    matched_package = package
    best_match = None
    params = [company_id, project_id]
    package_clause = ""
    # Если пользователь принял накладную/перемещение без явного пакета, не блокируем
    # сразу по "Основная": сначала пробуем найти материал во всех активных пакетах.
    if package and package != "Основная":
        package_clause = " AND COALESCE(NULLIF(work_package,''),'Основная')=%s"
        params.append(package)
    cur.execute("""SELECT id, name, sections_json, COALESCE(work_package,'Основная') AS work_package
                   FROM estimates
                   WHERE company_id=%s
                     AND project_id=%s
                     AND status='Активная'
                     AND COALESCE(smeta_type,'Заказчик') IN ('Заказчик','Материалы')""" + package_clause, tuple(params))
    estimates = _cursor_rows_as_dicts(cur, cur.fetchall())
    estimate_count = len(estimates)
    for est in estimates:
        for section in _estimate_sections(est.get("sections_json")):
            section_name = section.get("name") or ""
            for item in section.get("items") or []:
                is_material = _estimate_item_type_backend(item, section_name) == "material"
                imported_qty = _estimate_imported_quantity(item)
                is_adjustment = is_resource_adjustment(
                    item,
                    imported_quantity=imported_qty,
                    line_total=_estimate_import_line_total_backend(item),
                )
                material_sum = _estimate_material_sum_backend(item)
                contribution = material_plan_contribution(
                    is_material=is_material,
                    is_adjustment=is_adjustment,
                    imported_quantity=imported_qty,
                    material_sum=material_sum,
                    item_sum=_estimate_item_sum_backend(item),
                    plan_issue=_estimate_material_plan_issue_backend(item, section_name),
                )
                if contribution is None:
                    continue
                qty, plan_sum, _ = contribution
                item_name = (item.get("name") or "").strip()
                item_unit = item.get("unit") or ""
                item_key = _material_control_key_resolved(cur, project, item_name, item_unit)
                exact_match = item_key == target_key
                fuzzy_score = 0.0 if exact_match else _material_name_match_score(material_name, item_name)
                units_compatible = _material_units_compatible(unit, item_unit)
                fuzzy_match = (not exact_match) and fuzzy_score >= 0.55 and (units_compatible or fuzzy_score >= 0.78)
                if not exact_match and not fuzzy_match:
                    continue
                match_score = 1.0 if exact_match else fuzzy_score
                planned_qty += qty
                planned_sum += plan_sum
                matched_rows += 1
                if fuzzy_match:
                    fuzzy_matched_rows += 1
                    if not units_compatible:
                        unit_mismatch_matched_rows += 1
                matched_package = est.get("work_package") or package
                candidate = {
                    "name": item_name,
                    "unit": _norm_base_unit(item_unit or "") or item_unit or "",
                    "workPackage": matched_package,
                    "score": match_score,
                    "exact": exact_match,
                    "unitsCompatible": units_compatible,
                }
                candidate_rank = (
                    1 if candidate["unitsCompatible"] else 0,
                    1 if candidate["exact"] else 0,
                    candidate["score"],
                    len(_material_match_tokens(item_name)),
                )
                best_rank = best_match.get("rank") if best_match else None
                if best_rank is None or candidate_rank > best_rank:
                    candidate["rank"] = candidate_rank
                    best_match = candidate

    stock_qty = 0.0
    stock_packages = [matched_package]
    if matched_package != "Основная":
        stock_packages.append("Основная")
    cur.execute("""SELECT name, unit, quantity FROM materials
                   WHERE project=%s AND COALESCE(NULLIF(work_package,''),'Основная') = ANY(%s)""",
                (project, stock_packages))
    for row in _cursor_rows_as_dicts(cur, cur.fetchall()):
        if _material_control_key_resolved(cur, project, row.get("name"), row.get("unit")) == target_key or (
            _material_units_compatible(unit, row.get("unit")) and _material_name_match_score(material_name, row.get("name")) >= 0.55
        ):
            stock_qty += _float_or_zero(row.get("quantity"))

    transferred_qty = 0.0
    transferred_signed_qty = 0.0
    transferred_pending_qty = 0.0
    cur.execute("""SELECT material_name, unit, quantity, COALESCE(signed,FALSE) AS signed
                   FROM material_transfers
                   WHERE company_id=%s
                     AND project_id=%s
                     AND COALESCE(NULLIF(work_package,''),'Основная')=%s
                     AND COALESCE(status,'Активна') <> 'Аннулирована'""",
                (company_id, project_id, matched_package))
    for row in _cursor_rows_as_dicts(cur, cur.fetchall()):
        if _material_control_key_resolved(cur, project, row.get("material_name"), row.get("unit")) == target_key or (
            _material_units_compatible(unit, row.get("unit")) and _material_name_match_score(material_name, row.get("material_name")) >= 0.55
        ):
            qty = _float_or_zero(row.get("quantity"))
            transferred_qty += qty
            if row.get("signed"):
                transferred_signed_qty += qty
            else:
                transferred_pending_qty += qty

    returned_qty = 0.0
    cur.execute("""SELECT material, unit, quantity
                   FROM warehouse_history
                   WHERE project=%s
                     AND COALESCE(NULLIF(work_package,''),'Основная')=%s
                     AND LOWER(COALESCE(type,'')) LIKE %s""", (project, matched_package, "возврат от мастера%"))
    for row in _cursor_rows_as_dicts(cur, cur.fetchall()):
        if _material_control_key_resolved(cur, project, row.get("material"), row.get("unit")) == target_key or (
            _material_units_compatible(unit, row.get("unit")) and _material_name_match_score(material_name, row.get("material")) >= 0.55
        ):
            returned_qty += _float_or_zero(row.get("quantity"))

    written_off_qty = 0.0
    cur.execute("""SELECT materials_used
                   FROM work_journal
                   WHERE project=%s
                     AND COALESCE(NULLIF(work_package,''),'Основная')=%s
                     AND COALESCE(status,'') NOT IN ('Аннулировано','Отклонено')
                     AND COALESCE(materials_used,'') <> ''""", (project, matched_package))
    for row in _cursor_rows_as_dicts(cur, cur.fetchall()):
        for item in _json_list_or_empty(row.get("materials_used")):
            if not isinstance(item, dict):
                continue
            item_name = item.get("name") or item.get("materialName") or ""
            item_unit = item.get("unit") or unit
            if _material_control_key_resolved(cur, project, item_name, item_unit) == target_key or (
                _material_units_compatible(unit, item_unit) and _material_name_match_score(material_name, item_name) >= 0.55
            ):
                written_off_qty += _float_or_zero(item.get("quantity"))

    requested_qty = 0.0
    request_params = [project, matched_package]
    request_exclude_clause = ""
    if exclude_request_id:
        request_exclude_clause = " AND id<>%s"
        request_params.append(int(exclude_request_id))
    cur.execute("""SELECT id, status, items_json, material_name, quantity, unit, COALESCE(work_package,'Основная') AS work_package
                   FROM supply_requests
                   WHERE project=%s
                     AND COALESCE(status,'') NOT IN ('Отклонена','Отменена','Отменена с откатом','Поставлено')
                     AND COALESCE(NULLIF(work_package,''),'Основная')=%s""" + request_exclude_clause,
                tuple(request_params))
    for row in _cursor_rows_as_dicts(cur, cur.fetchall()):
        raw_items = _json_list_or_empty(row.get("items_json"))
        if not raw_items:
            raw_items = [{
                "materialName": row.get("material_name") or "",
                "quantity": row.get("quantity") or 0,
                "unit": row.get("unit") or "",
                "workPackage": row.get("work_package") or matched_package,
            }]
        for item in raw_items:
            if not isinstance(item, dict):
                continue
            item_name = item.get("materialName") or item.get("name") or ""
            item_unit = item.get("unit") or row.get("unit") or unit
            item_package = _supply_work_package(item.get("workPackage") or item.get("work_package") or row.get("work_package"))
            if item_package != matched_package:
                continue
            if _material_control_key_resolved(cur, project, item_name, item_unit) == target_key or (
                _material_units_compatible(unit, item_unit) and _material_name_match_score(material_name, item_name) >= 0.55
            ):
                item_qty = _float_or_zero(item.get("quantity"))
                delivered_qty = 0.0
                cur.execute("""SELECT material_name, unit, received_quantity, COALESCE(work_package,'Основная') AS work_package
                               FROM supply_deliveries
                               WHERE request_id=%s
                                 AND COALESCE(status,'') NOT IN ('Отменена','Отклонена')""", (row.get("id"),))
                for delivery_row in _cursor_rows_as_dicts(cur, cur.fetchall()):
                    delivery_package = _supply_work_package(delivery_row.get("work_package"))
                    if delivery_package != item_package:
                        continue
                    if _material_control_key_resolved(cur, project, delivery_row.get("material_name"), delivery_row.get("unit")) == target_key or (
                        _material_units_compatible(unit, delivery_row.get("unit")) and _material_name_match_score(material_name, delivery_row.get("material_name")) >= 0.55
                    ):
                        delivered_qty += _float_or_zero(delivery_row.get("received_quantity"))
                requested_qty += max(0.0, item_qty - delivered_qty)

    stock_qty = max(0.0, stock_qty - max(0.0, _float_or_zero(exclude_stock_qty)))
    issued_or_consumed_qty = max(written_off_qty, max(0.0, transferred_qty - returned_qty))
    covered_qty = stock_qty + issued_or_consumed_qty
    remaining = planned_qty - covered_qty - requested_qty
    return {
        "status": "no_active_estimate" if estimate_count == 0 else ("no_estimate_material" if matched_rows == 0 else ("shortage_open" if remaining > 0 else "covered")),
        "estimateCount": estimate_count,
        "matchedRows": matched_rows,
        "plannedQty": round(planned_qty, 6),
        "plannedSum": round(planned_sum, 2),
        "stockQty": round(stock_qty, 6),
        "transferredQty": round(transferred_qty, 6),
        "transferredSignedQty": round(transferred_signed_qty, 6),
        "transferredPendingQty": round(transferred_pending_qty, 6),
        "returnedQty": round(returned_qty, 6),
        "writtenOffQty": round(written_off_qty, 6),
        "coveredQty": round(covered_qty, 6),
        "requestedQty": round(requested_qty, 6),
        "remainingQty": round(remaining, 6),
        "workPackage": matched_package,
        "requestedWorkPackage": package,
        "matchedByFuzzy": fuzzy_matched_rows,
        "matchedWithDifferentUnit": unit_mismatch_matched_rows,
        "canonicalName": (best_match or {}).get("name") or "",
        "canonicalUnit": (best_match or {}).get("unit") or "",
        "canonicalWorkPackage": (best_match or {}).get("workPackage") or matched_package,
        "canonicalMatchScore": round(_float_or_zero((best_match or {}).get("score")), 4),
        "canonicalMatchType": "exact" if (best_match or {}).get("exact") else ("fuzzy" if best_match else ""),
    }

def _canonicalize_invoice_items_from_estimate_control(items: list):
    for item in items or []:
        if not isinstance(item, dict):
            continue
        control = item.get("estimateControl") or {}
        if not isinstance(control, dict):
            continue
        if _float_or_zero(control.get("matchedRows")) <= 0:
            continue
        if _float_or_zero(control.get("matchedWithDifferentUnit")) > 0:
            continue
        canonical_name = str(control.get("canonicalName") or "").strip()
        if not canonical_name:
            continue
        raw_name = str(item.get("name") or item.get("materialName") or "").strip()
        if raw_name and _norm_key_text(raw_name) != _norm_key_text(canonical_name):
            item.setdefault("invoiceOriginalName", raw_name)
            item.setdefault("originalName", raw_name)
            control["invoiceOriginalName"] = raw_name
            control["canonicalizedForStock"] = True
        item["name"] = canonical_name
        item["materialName"] = canonical_name
        canonical_unit = _norm_base_unit(control.get("canonicalUnit") or item.get("unit") or "") or item.get("unit") or ""
        if canonical_unit:
            item["unit"] = canonical_unit
        canonical_package = _supply_work_package(control.get("canonicalWorkPackage") or control.get("workPackage") or item.get("workPackage") or item.get("work_package"))
        item["workPackage"] = canonical_package
        control["workPackage"] = canonical_package
        item["estimateControl"] = control
    return items

def _supply_linked_work_estimate_control(cur, project_owner: dict, item: dict, work_package: str = ""):
    project = str((project_owner or {}).get("name") or "").strip()
    company_id = _positive_int_or_none((project_owner or {}).get("companyId"))
    project_id = _positive_int_or_none((project_owner or {}).get("id"))
    if not project or not company_id or not project_id or not isinstance(item, dict):
        return None
    package = _supply_work_package(work_package or item.get("workPackage") or item.get("work_package"))
    target_keys = {
        str(item.get("estimateItemKey") or item.get("estimate_item_key") or "").strip(),
        str(item.get("parentWorkKey") or item.get("parent_work_key") or "").strip(),
        str(item.get("workKey") or item.get("work_key") or "").strip(),
    }
    target_keys.discard("")
    target_name = _norm_key_text(
        item.get("parentWorkName")
        or item.get("parent_work_name")
        or item.get("estimateWorkName")
        or item.get("estimate_work_name")
        or item.get("workName")
        or item.get("work_name")
        or ""
    )
    if not target_keys and not target_name:
        return None

    params = [company_id, project_id]
    package_clause = ""
    if package:
        package_clause = " AND COALESCE(NULLIF(work_package,''),'Основная')=%s"
        params.append(package)
    cur.execute("""SELECT id, name, sections_json, COALESCE(NULLIF(work_package,''),'Основная') AS work_package
                   FROM estimates
                   WHERE company_id=%s
                     AND project_id=%s
                     AND status='Активная'
                     AND COALESCE(smeta_type,'Заказчик')='Заказчик'""" + package_clause, tuple(params))
    for est in _cursor_rows_as_dicts(cur, cur.fetchall()):
        est_id = est.get("id")
        for section_idx, section in enumerate(_estimate_sections(est.get("sections_json"))):
            section_name = section.get("name") or ""
            for item_idx, work in enumerate(section.get("items") or []):
                if not isinstance(work, dict) or _estimate_item_type_backend(work, section_name) != "work":
                    continue
                keys = set(_estimate_item_key_candidates(work, est_id, section_idx, item_idx))
                work_name = work.get("workName") or work.get("name") or ""
                work_name_key = _norm_key_text(work_name)
                if (target_keys and target_keys.intersection(keys)) or (target_name and work_name_key and (target_name == work_name_key or target_name in work_name_key or work_name_key in target_name)):
                    work_qty = _estimate_imported_quantity(work)
                    if work_qty <= 0:
                        work_qty = _float_or_zero(work.get("quantity"))
                    message = "Материал не найден отдельной ресурсной строкой сметы, но привязан к укрупненной работе"
                    if work_name:
                        message += f" «{work_name}»"
                    if section_name:
                        message += f" в разделе «{section_name}»"
                    return {
                        "status": "composite_work_material",
                        "controlLabel": "Комплектация укрупненной работы",
                        "controlMessage": message + ". Учитывать как фактическую комплектацию работы, не как отдельную сметную потребность.",
                        "isCompositeWorkMaterial": True,
                        "estimateId": est_id,
                        "estimateName": est.get("name") or "",
                        "estimateItemKey": next(iter(keys), ""),
                        "workName": work_name,
                        "workPackage": est.get("work_package") or package,
                        "sectionName": section_name,
                        "plannedWorkQty": round(work_qty, 6),
                        "plannedWorkSum": round(_estimate_item_sum_backend(work), 2),
                    }
    return None

def _attach_supply_estimate_control(
    cur,
    project: str,
    items: list,
    exclude_request_id=None,
    exclude_stock_by_key=None,
    *,
    company_id=None,
    project_id=None,
):
    from datetime import datetime, timezone
    if not project:
        return items
    if project == "Основной склад":
        return items
    if not _positive_int_or_none(company_id):
        raise HTTPException(status_code=409, detail="Компания сметного контроля не определена")
    try:
        from backend.features.ai_findings.service import resolve_project_owner
    except ModuleNotFoundError:
        from features.ai_findings.service import resolve_project_owner
    project_owner = resolve_project_owner(
        cur,
        project,
        company_id=company_id,
        project_id=project_id,
        for_update=not getattr(getattr(cur, "connection", None), "autocommit", True),
    )
    project = project_owner["name"]
    exclude_stock_by_key = exclude_stock_by_key or {}
    calculated_at = datetime.now(timezone.utc).isoformat()
    for item in items or []:
        if not isinstance(item, dict):
            continue
        control = _supply_material_estimate_control(
            cur,
            project_owner,
            item.get("materialName") or item.get("name") or "",
            item.get("unit") or "",
            item.get("workPackage") or item.get("work_package") or "",
            exclude_request_id=exclude_request_id,
            exclude_stock_qty=exclude_stock_by_key.get(_material_control_key_resolved(cur, project, item.get("materialName") or item.get("name") or "", item.get("unit") or ""), 0),
        )
        if not control:
            continue
        if control.get("status") == "no_estimate_material":
            linked_work = _supply_linked_work_estimate_control(
                cur,
                project_owner,
                item,
                item.get("workPackage") or item.get("work_package") or "",
            )
            if linked_work:
                control.update(linked_work)
                control["matchedRows"] = control.get("matchedRows") or 0
            elif _is_invoice_consumable_material(item.get("materialName") or item.get("name") or ""):
                control["status"] = "consumable_outside_estimate"
                control["controlLabel"] = "Расходник вне сметы"
                control["controlMessage"] = "Позиция похожа на расходный инструмент/расходник. Приход разрешен, но она остается видимой в контроле как закупка вне сметной ресурсной строки."
                control["isConsumableOutsideEstimate"] = True
        control_package = _supply_work_package(control.get("workPackage") or item.get("workPackage") or item.get("work_package"))
        item_package = _supply_work_package(item.get("workPackage") or item.get("work_package"))
        if control_package and item_package == "Основная" and control_package != item_package:
            item["workPackage"] = control_package
        qty = _float_or_zero(item.get("quantity"))
        remaining_after = control["remainingQty"] - qty
        control["requestQty"] = round(qty, 6)
        control["remainingAfterRequest"] = round(remaining_after, 6)
        if control["matchedRows"] > 0 and remaining_after < -max(0.01, control["plannedQty"] * 0.05):
            control["status"] = "over_estimate_need"
        control["calculatedAt"] = calculated_at
        item["estimateControl"] = control
    return items

def _refresh_open_supply_controls_for_estimate(
    cur,
    project_name: str,
    company_id,
    project_id=None,
):
    try:
        from backend.features.supply_estimate_refresh.service import refresh_open_supply_request_controls
    except ModuleNotFoundError:
        from features.supply_estimate_refresh.service import refresh_open_supply_request_controls
    return refresh_open_supply_request_controls(
        cur,
        project_name=project_name,
        company_id=company_id,
        project_id=project_id,
        attach_control=_attach_supply_estimate_control,
    )

def _refresh_open_supply_controls_after_estimate_change(
    project_name: str,
    company_id,
    project_id=None,
):
    conn = None
    cur = None
    try:
        conn = get_db()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        result = _refresh_open_supply_controls_for_estimate(
            cur,
            project_name,
            company_id,
            project_id,
        )
        conn.commit()
        return result
    except Exception as exc:
        if conn:
            try:
                conn.rollback()
            except Exception:
                pass
        print("SUPPLY CONTROL BACKGROUND REFRESH ERROR:", project_name, str(exc))
        return {"scanned": 0, "updated": 0, "error": str(exc)}
    finally:
        if cur:
            cur.close()
        if conn:
            conn.close()

def _enforce_supply_estimate_control(
    items: list,
    *,
    source: str = "заявка",
    allow_manual_project_override: bool = False,
    override_by: str = "",
):
    blockers = []
    for item in items or []:
        if not isinstance(item, dict):
            continue
        control = item.get("estimateControl") or {}
        status = control.get("status")
        if status not in ("no_active_estimate", "no_estimate_material", "over_estimate_need"):
            continue
        name = item.get("materialName") or item.get("name") or ""
        unit = item.get("unit") or ""
        qty = _float_or_zero(item.get("quantity"))
        package = control.get("workPackage") or item.get("workPackage") or item.get("work_package") or "Основная"
        if status == "no_active_estimate":
            blockers.append(f"{name} ({package}) — по объекту нет активной заказной или нормативной сметы материалов")
        elif status == "no_estimate_material":
            blockers.append(f"{name} ({package}) — материала нет в активной смете")
        else:
            remaining = _float_or_zero(control.get("remainingQty"))
            blockers.append(f"{name} ({package}) — запрошено {qty:g} {unit}, по смете осталось {remaining:g} {unit}")
    if blockers:
        if allow_manual_project_override:
            for item in items or []:
                if not isinstance(item, dict):
                    continue
                control = item.get("estimateControl") or {}
                if control.get("status") in ("no_active_estimate", "no_estimate_material", "over_estimate_need"):
                    control["manualProjectInvoiceOverride"] = True
                    control["manualProjectInvoiceOverrideBy"] = override_by or "Система"
                    control["manualProjectInvoiceWarning"] = "Ручной приход на объект принят как прямой заказ/вне цепочки снабжения. Позиция остается под контролем сметы."
                    item["estimateControl"] = control
            return
        prefix = "Заявка" if source == "заявка" else ("Перемещение" if source == "перемещение" else ("Выдача исполнителю" if source == "выдача исполнителю" else "Накладная"))
        raise HTTPException(
            status_code=400,
            detail=prefix + " не проходит сметный контроль. " + "; ".join(blockers[:5]) + ". Сначала добавьте материал в активную/доп. смету или исправьте раздел сметы."
        )

def _copy_approved_supply_request_control(cur, request_id, project: str, items: list) -> bool:
    if not request_id or not items:
        return False
    cur.execute("SELECT status, items_json FROM supply_requests WHERE id=%s", (request_id,))
    req = cur.fetchone()
    if not req:
        return False
    status = (req.get("status") if isinstance(req, dict) else req[0]) or ""
    if status not in ("Утверждена", "В пути", "Поставлено", "Частично поставлено", "Проблема поставки"):
        return False
    request_items = _json_list_or_empty(req.get("items_json") if isinstance(req, dict) else req[1])
    if not request_items:
        return True
    for item in items or []:
        if not isinstance(item, dict):
            continue
        item_package = _supply_work_package(item.get("workPackage") or item.get("work_package"))
        item_key = _material_control_key_resolved(
            cur,
            project,
            item.get("materialName") or item.get("name") or "",
            item.get("unit") or "",
        )
        for req_item in request_items:
            if not isinstance(req_item, dict):
                continue
            req_package = _supply_work_package(req_item.get("workPackage") or req_item.get("work_package"))
            if req_package != item_package:
                continue
            req_key = _material_control_key_resolved(
                cur,
                project,
                req_item.get("materialName") or req_item.get("name") or "",
                req_item.get("unit") or "",
            )
            if req_key != item_key:
                continue
            if isinstance(req_item.get("estimateControl"), dict):
                item["estimateControl"] = dict(req_item["estimateControl"])
                item["estimateControl"]["receiptLockedByRequest"] = request_id
            break
    return True

@app.get("/supply-requests")
def get_supply_requests(
    limit: Optional[int] = None,
    offset: int = 0,
    x_company_id: Optional[str] = Header(default=None, alias="X-Company-Id"),
    x_company_mode: Optional[str] = Header(default=None, alias="X-Company-Mode"),
    current_user: dict = Depends(get_current_user),
):
    conn = get_db()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    role = current_user.get("role")
    page_sql, page_params = limit_offset_sql(limit, offset)
    company_filter_sql = ""
    company_filter_params = []
    is_internal_supply_reader = (
        can_see_all_company_data(current_user)
        or role in ("снабженец", "кладовщик", "прораб")
        or role in WORKER_EXECUTION_ROLES
    )
    if is_internal_supply_reader:
        try:
            company_context = _resolve_work_company_context(
                cur,
                current_user,
                None,
                "read",
                x_company_id=x_company_id,
                x_company_mode=x_company_mode,
            )
            company_filter_sql, company_filter_params = company_id_scope_filter(company_context)
        except Exception:
            cur.close()
            conn.close()
            raise
    if can_see_all_company_data(current_user):
        cur.execute(
            SUPPLY_SELECT + " WHERE TRUE" + company_filter_sql + " ORDER BY id DESC" + page_sql,
            company_filter_params + page_params,
        )
    elif role in ("снабженец", "кладовщик"):
        project_filter_sql, project_params = scoped_project_filter(current_user, "project")
        cur.execute(
            SUPPLY_SELECT + " WHERE TRUE" + project_filter_sql + company_filter_sql + " ORDER BY id DESC" + page_sql,
            project_params + company_filter_params + page_params,
        )
    elif role == "поставщик":
        supplier_ids = current_supplier_ids(cur, current_user)
        if not supplier_ids:
            cur.close(); conn.close()
            return []
        _ensure_supply_request_recipients_table(cur)
        cur.execute(SUPPLY_SELECT + """
            WHERE COALESCE(selected_suppliers, '{}'::int[]) && %s::int[]
               OR id IN (
                    SELECT request_id
                      FROM supply_request_recipients
                     WHERE visible_to_supplier=TRUE
                       AND (
                            target_supplier_id = ANY(%s)
                         OR supplier_id = ANY(%s)
                         OR COALESCE(supplier_group_ids, '{}'::int[]) && %s::int[]
                       )
               )
            ORDER BY id DESC
        """ + page_sql, [supplier_ids, supplier_ids, supplier_ids, supplier_ids] + page_params)
    elif role == "прораб":
        projects = user_project_names(current_user)
        clauses = ["requested_by_id=%s", "created_by=%s"]
        params = [current_user.get("id"), current_user.get("name") or ""]
        if projects:
            clauses.append("project = ANY(%s)")
            params.append(projects)
        package_sql, package_params = package_access_filter(current_user)
        cur.execute(
            SUPPLY_SELECT + " WHERE (" + " OR ".join(clauses) + ")" + package_sql + company_filter_sql + " ORDER BY id DESC" + page_sql,
            params + package_params + company_filter_params + page_params,
        )
    elif role in WORKER_EXECUTION_ROLES:
        package_sql, package_params = package_access_filter(current_user)
        cur.execute(
            SUPPLY_SELECT + " WHERE (requested_by_id=%s OR created_by=%s)" + package_sql + company_filter_sql + " ORDER BY id DESC" + page_sql,
            [current_user.get("id"), current_user.get("name") or ""] + package_params + company_filter_params + page_params,
        )
    else:
        cur.close(); conn.close()
        return []
    rows = cur.fetchall()
    if is_internal_supply_reader:
        rows = attach_supply_allocation_projection(cur, rows)
    conn.close()
    return [_supply_response_for_role(r, current_user) for r in rows]

@app.post("/supply-requests")
def create_supply_request(
    r: SupplyRequestModel,
    x_company_id: Optional[str] = Header(default=None, alias="X-Company-Id"),
    x_company_mode: Optional[str] = Header(default=None, alias="X-Company-Mode"),
    _current_user: dict = Depends(require_roles(*SUPPLY_ROLES)),
):
    import json as _json
    from datetime import datetime
    role = (_current_user.get("role") or "").strip()
    project_name = (r.project or "").strip()
    if not project_name:
        raise HTTPException(status_code=400, detail="Заявка снабжения должна быть привязана к объекту или складу")
    created_by = _current_user.get("name") or r.createdBy or ""
    requested_by_id = _current_user.get("id")
    if role in ("директор", "зам_директора"):
        initial_status = "Утверждена"
    elif role == "прораб":
        initial_status = "Подтверждена прорабом"
    else:
        initial_status = "Новая"
    now = datetime.now()
    prorab_id = requested_by_id if role == "прораб" else None
    prorab_name = created_by if role == "прораб" else None
    prorab_at = now if role == "прораб" else None
    director_id = requested_by_id if role in ("директор", "зам_директора") else None
    director_name = created_by if role in ("директор", "зам_директора") else None
    director_at = now if role in ("директор", "зам_директора") else None
    # Нормализация items: если items пустой, но есть materialName, упаковываем как single-item.
    request_package = _supply_work_package(r.workPackage)
    items = _normalize_supply_request_items(r.items, r.materialName, r.quantity, r.unit, request_package)
    if not items:
        raise HTTPException(status_code=400, detail="Заявка должна содержать хотя бы одну позицию")
    require_project_or_warehouse_access(_current_user, project_name)
    request_package = _resolve_supply_request_package(_current_user, items, request_package)
    # material_name / quantity / unit заполняем агрегатом для совместимости со старым UI
    # Если позиций больше одной — пишем «N позиций» в material_name; quantity = сумма всех
    if len(items) == 1:
        agg_name = items[0]["materialName"]
        agg_qty = float(items[0].get("quantity") or 0)
        agg_unit = items[0].get("unit") or r.unit
    else:
        agg_name = items[0]["materialName"] + " и ещё " + str(len(items)-1) + " поз."
        agg_qty = float(len(items))  # количество позиций
        agg_unit = "поз."
    selected_suppliers = _normalize_supplier_ids(r.selectedSuppliers)
    is_material_control_request = material_control_request_intent(
        r.requestSource, r.notes
    )
    conn = get_db()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    _ensure_supply_runtime_columns(cur)
    conn.commit()
    if is_material_control_request:
        # The advisory lineage lock and duplicate scan must share one
        # transaction with the request insert.
        conn.autocommit = False
    project_company_id = None
    requested_company_id = r.companyId
    if is_material_control_request:
        if not _positive_int_or_none(r.companyId) or not _positive_int_or_none(r.projectId):
            cur.close()
            conn.close()
            raise HTTPException(
                status_code=400,
                detail="Заявка из контроля материалов должна содержать точные companyId и projectId",
            )
    else:
        project_company_id = _project_company_id(cur, project_name)
        requested_company_id = requested_company_id or project_company_id
    try:
        company_context = _resolve_work_company_context(
            cur,
            _current_user,
            requested_company_id,
            "create",
            x_company_id=x_company_id,
            x_company_mode=x_company_mode,
        )
    except Exception:
        cur.close()
        conn.close()
        raise
    company_id = int(company_context.get("companyId") or requested_company_id or 1)
    project_id = _positive_int_or_none(r.projectId)
    if is_material_control_request:
        try:
            project_owner = resolve_material_control_project(
                cur,
                company_id=company_id,
                project_id=project_id,
                project_name=project_name,
            )
            project_id = int(project_owner["projectId"])
            project_name = project_owner["projectName"]
        except MaterialControlLineageError as exc:
            cur.close()
            conn.close()
            raise HTTPException(status_code=400, detail=str(exc)) from exc
    elif project_company_id and int(project_company_id) != company_id:
        cur.close(); conn.close()
        raise HTTPException(status_code=400, detail="Выбранная компания не совпадает с компанией объекта. Переключите компанию в шапке или выберите другой объект.")
    selected_suppliers = supplier_group_scope_ids(cur, selected_suppliers)
    if is_material_control_request:
        lineage_material_keys = {}

        def resolve_lineage_material_key(project, name, unit):
            cache_key = (project or "", name or "", unit or "")
            if cache_key not in lineage_material_keys:
                lineage_material_keys[cache_key] = _material_control_key_resolved(
                    cur, project, name, unit
                )
            return lineage_material_keys[cache_key]

        try:
            items = validate_material_control_request_lineage(
                request_source=r.requestSource,
                request_notes=r.notes,
                project_name=project_name,
                company_id=company_id,
                project_id=project_id,
                work_package=request_package,
                items=items,
                estimates_by_id=load_material_control_estimates(
                    cur,
                    material_control_estimate_ids(items),
                ),
                parse_sections=_estimate_sections,
                item_type=_estimate_item_type_backend,
                item_plan_issue=_estimate_material_plan_issue_backend,
                material_key=resolve_lineage_material_key,
                normalize_unit=_norm_base_unit,
                item_quantity=_estimate_imported_quantity,
            )
        except MaterialControlLineageError as exc:
            cur.close()
            conn.close()
            raise HTTPException(
                status_code=400,
                detail="Заявка из контроля материалов отклонена: " + str(exc),
            ) from exc
        lineage_keys = material_control_lineage_keys(items)
        # The source estimate row is the idempotency key. Advisory transaction locks
        # make two simultaneous clicks serialize before either request is inserted.
        for estimate_id, section_index, item_index in sorted(lineage_keys):
            cur.execute(
                "SELECT pg_advisory_xact_lock(hashtext(%s))",
                (f"material-control-lineage:{company_id}:{project_id}:{estimate_id}:{section_index}:{item_index}",),
            )
        cur.execute(
            """
            SELECT id, items_json
              FROM supply_requests
             WHERE company_id=%s
               AND project=%s
               AND COALESCE(status,'') IN (
                   'Новая', 'Подтверждена прорабом', 'Утверждена', 'КП запрошены',
                   'В пути', 'Частично поставлено', 'Проблема поставки', 'Утверждено'
               )
             FOR UPDATE
            """,
            (company_id, project_name),
        )
        conflicts = material_control_lineage_conflicts(
            items,
            [dict(row) for row in cur.fetchall()],
            _json_list_or_empty,
        )
        if conflicts:
            request_ids = sorted({row["requestId"] for row in conflicts if row.get("requestId")})
            cur.close()
            conn.close()
            raise HTTPException(
                status_code=409,
                detail=(
                    "По этой строке активной сметы уже создана заявка"
                    + (" #" + ", #".join(str(request_id) for request_id in request_ids) if request_ids else "")
                    + ". Отмените её или дождитесь поставки, затем обновите контроль материалов."
                ),
            )
    items = _attach_supply_estimate_control(
        cur,
        project_name,
        items,
        company_id=company_id,
        project_id=project_id,
    )
    if project_name != "Основной склад":
        _enforce_supply_estimate_control(items, source="заявка")
    items_json = _json.dumps(items, ensure_ascii=False)
    cur.execute(
        "INSERT INTO supply_requests "
        "(material_name,quantity,unit,project,company_id,work_package,created_by,date,notes,selected_suppliers,"
        "status,requested_by_role,requested_by_id,urgency,category,"
        "prorab_id,prorab_name,prorab_confirmed_at,"
        "director_id,director_name,director_approved_at,items_json) "
        "VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s) RETURNING id",
        (agg_name, agg_qty, agg_unit, project_name, company_id, request_package, created_by, r.date, r.notes,
         selected_suppliers, initial_status, role, requested_by_id, r.urgency, r.category,
         prorab_id, prorab_name, prorab_at,
         director_id, director_name, director_at, items_json))
    new_id = cur.fetchone()['id']
    notification_rows = []
    if selected_suppliers and initial_status == "Утверждена":
        recipient_rows = _upsert_supply_request_recipients(cur, new_id, company_id, selected_suppliers)
        visibility_error = _recipient_visibility_error(recipient_rows)
        if visibility_error:
            cur.close(); conn.close()
            raise HTTPException(status_code=400, detail=visibility_error)
        _create_supplier_offer_requests(cur, new_id, selected_suppliers, company_id=company_id)
        notification_rows = _notify_supply_request_recipients(cur, new_id)
        cur.execute("UPDATE supply_requests SET status=%s WHERE id=%s", ('КП запрошены', new_id))
    cur.execute(SUPPLY_SELECT + " WHERE id=%s", (new_id,))
    row = cur.fetchone()
    conn.commit()
    conn.close()
    log_audit(
        _current_user.get("name", ""),
        _current_user.get("role", ""),
        "create",
        "supply_request",
        new_id,
        ("Заявка снабжения: " + str(agg_name or "") + ", " + str(agg_qty) + " " + str(agg_unit or "") + ", статус " + str(initial_status or ""))[:250],
        project_name,
    )
    response = _supply_response_for_role(row, _current_user)
    if notification_rows:
        response["notifications"] = notification_rows
    return response

@app.put("/supply-requests/{id}")
def update_supply_request(
    id: int,
    data: dict,
    x_company_id: Optional[str] = Header(default=None, alias="X-Company-Id"),
    x_company_mode: Optional[str] = Header(default=None, alias="X-Company-Mode"),
    _current_user: dict = Depends(get_current_user),
):
    from datetime import datetime
    conn = get_db()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    action = data.get('action')
    now = datetime.now()
    cur.execute("""SELECT project, COALESCE(work_package,'') as work_package, items_json,
                          requested_by_id, created_by, status, company_id
                   FROM supply_requests WHERE id=%s""", (id,))
    req = cur.fetchone()
    if not req:
        conn.close()
        raise HTTPException(status_code=404, detail="Заявка не найдена")
    claimed_company_id = data.get("companyId") if "companyId" in data else data.get("company_id")
    try:
        _company_context, effective_user = resolve_resource_company_actor(
            cur,
            _current_user,
            req.get("company_id"),
            "update",
            claimed_company_id=claimed_company_id,
            x_company_id=x_company_id,
            x_company_mode=x_company_mode,
            platform_staff_roles=PLATFORM_STAFF_ROLES,
            client_account_roles=CLIENT_ACCOUNT_ROLES,
        )
    except Exception:
        cur.close()
        conn.close()
        raise
    role = effective_user.get("role") or ""
    if role not in SUPPLY_ROLES:
        cur.close()
        conn.close()
        raise HTTPException(status_code=403, detail="Роль в выбранной компании не позволяет менять заявки снабжения")
    user_id = effective_user.get("id")
    user_name = effective_user.get("name") or ""
    if req.get("project"):
        require_project_or_warehouse_access(effective_user, req.get("project"))
    request_items = _json_list_or_empty(req.get("items_json"))
    request_packages = sorted(set([
        _supply_work_package(item.get("workPackage") or item.get("work_package") or req.get("work_package"))
        for item in request_items
    ] or [_supply_work_package(req.get("work_package"))]))
    for package_name in request_packages:
        if not has_package_access(effective_user, package_name or "Основная"):
            conn.close()
            raise HTTPException(status_code=403, detail="Нет доступа к разделу сметы заявки: " + (package_name or "Основная"))
    if role in WORKER_EXECUTION_ROLES:
        owns_request = (
            str(req.get("requested_by_id") or "") == str(user_id or "")
            or (req.get("created_by") or "").strip().lower() == user_name.strip().lower()
        )
        if not owns_request:
            conn.close()
            raise HTTPException(status_code=403, detail="Исполнитель может менять только свою заявку")
        if action != "cancel":
            conn.close()
            raise HTTPException(status_code=403, detail="Исполнитель может только отменить свою заявку до обработки")
        if (req.get("status") or "Новая") not in ("Новая", "Подтверждена прорабом"):
            conn.close()
            raise HTTPException(status_code=400, detail="Заявка уже в обработке, отмену делает снабжение или руководитель")
    if action == 'confirm_prorab':
        if role not in (*LEADERSHIP_ROLES, "прораб", "главный_инженер"):
            conn.close()
            raise HTTPException(status_code=403, detail="Подтвердить заявку может прораб, главный инженер или руководство")
        cur.execute(
            "UPDATE supply_requests SET status=%s, prorab_id=%s, prorab_name=%s, prorab_confirmed_at=%s WHERE id=%s",
            ('Подтверждена прорабом', user_id, user_name, now, id))
    elif action == 'approve_director':
        if role not in LEADERSHIP_ROLES:
            conn.close()
            raise HTTPException(status_code=403, detail="Утвердить заявку может только директор или замдиректора")
        refreshed_items = _attach_supply_estimate_control(
            cur,
            req.get("project") or "",
            request_items,
            exclude_request_id=id,
            company_id=req.get("company_id"),
        )
        if req.get("project") and req.get("project") != "Основной склад":
            _enforce_supply_estimate_control(refreshed_items, source="заявка")
            cur.execute("UPDATE supply_requests SET items_json=%s WHERE id=%s", (json.dumps(refreshed_items, ensure_ascii=False), id))
        cur.execute(
            "UPDATE supply_requests SET status=%s, director_id=%s, director_name=%s, director_approved_at=%s WHERE id=%s",
            ('Утверждена', user_id, user_name, now, id))
    elif action == 'reject':
        if role not in (*LEADERSHIP_ROLES, "прораб", "главный_инженер", "снабженец", "кладовщик"):
            conn.close()
            raise HTTPException(status_code=403, detail="Отклонить заявку может прораб, снабжение или руководство")
        cur.execute(
            "UPDATE supply_requests SET status=%s, reject_reason=%s WHERE id=%s",
            ('Отклонена', data.get('rejectReason') or data.get('reason') or '', id))
    elif action == 'cancel':
        current_status = req.get("status") or "Новая"
        if role in WORKER_EXECUTION_ROLES:
            pass
        elif role in LEADERSHIP_ROLES:
            pass
        elif role in ("прораб", "главный_инженер"):
            if current_status not in ("Новая", "Подтверждена прорабом"):
                conn.close()
                raise HTTPException(status_code=400, detail="Заявка уже в снабжении: отменить может директор или замдиректора")
        elif role in ("снабженец", "кладовщик"):
            if current_status not in ("Новая", "Подтверждена прорабом", "Утверждена"):
                conn.close()
                raise HTTPException(status_code=400, detail="Поставка уже началась: отменить может директор или замдиректора")
        else:
            conn.close()
            raise HTTPException(status_code=403, detail="Нет прав на отмену заявки")
        cur.execute("UPDATE supply_requests SET status=%s WHERE id=%s", ('Отменена', id))
    elif 'status' in data:
        conn.close()
        raise HTTPException(status_code=400, detail="Статус заявки меняется только через действия confirm_prorab / approve_director / reject / cancel")
    cur.execute(SUPPLY_SELECT + " WHERE id=%s", (id,))
    row = cur.fetchone()
    conn.commit()
    conn.close()
    audit_action = str(action or data.get("status") or "update")
    log_audit(
        effective_user.get("name", ""),
        effective_user.get("role", ""),
        audit_action,
        "supply_request",
        id,
        ("Заявка снабжения обновлена: " + str((row or {}).get("materialName") or (row or {}).get("material_name") or "") + ", статус " + str((row or {}).get("status") or ""))[:250],
        ((row or {}).get("project") or req.get("project") or ""),
    )
    return _supply_response_for_role(row, effective_user) if row else {"ok": True}

@app.delete("/supply-requests/{id}")
def delete_supply_request(
    id: int,
    rollback_received: bool = False,
    x_company_id: Optional[str] = Header(default=None, alias="X-Company-Id"),
    x_company_mode: Optional[str] = Header(default=None, alias="X-Company-Mode"),
    _current_user: dict = Depends(get_current_user),
):
    from datetime import datetime
    conn = get_db()
    conn.autocommit = False
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    try:
        cur.execute("SELECT id, project, material_name, status, COALESCE(work_package,'') as work_package, items_json, company_id FROM supply_requests WHERE id=%s FOR UPDATE", (id,))
        req = cur.fetchone()
        if not req:
            conn.rollback()
            raise HTTPException(status_code=404, detail="Заявка не найдена")
        company_context, effective_user = resolve_resource_company_actor(
            cur,
            _current_user,
            req.get("company_id"),
            "delete",
            x_company_id=x_company_id,
            x_company_mode=x_company_mode,
            platform_staff_roles=PLATFORM_STAFF_ROLES,
            client_account_roles=CLIENT_ACCOUNT_ROLES,
        )
        company_id = int(company_context.get("companyId"))
        allowed_roles = (*LEADERSHIP_ROLES, "снабженец", "кладовщик", "прораб")
        if effective_user.get("role") not in allowed_roles:
            raise HTTPException(status_code=403, detail="Роль в выбранной компании не позволяет отменять заявки снабжения")
        if req.get("project"):
            require_project_access(effective_user, req.get("project"))
        request_items = _json_list_or_empty(req.get("items_json"))
        request_packages = sorted(set([
            _supply_work_package(item.get("workPackage") or item.get("work_package") or req.get("work_package"))
            for item in request_items
        ] or [_supply_work_package(req.get("work_package"))]))
        for package_name in request_packages:
            if not has_package_access(effective_user, package_name or "Основная"):
                conn.rollback()
                raise HTTPException(status_code=403, detail="Нет доступа к разделу сметы заявки: " + (package_name or "Основная"))
        current_status = req.get("status") or ""
        if current_status == "Отменена с откатом":
            conn.rollback()
            return {"ok": True, "cancelled": True, "alreadyRolledBack": True}
        if current_status == "Отменена" and not rollback_received:
            conn.rollback()
            return {"ok": True, "cancelled": True, "alreadyCancelled": True}

        cur.execute("SELECT * FROM supply_deliveries WHERE request_id=%s FOR UPDATE", (id,))
        deliveries = cur.fetchall()
        assert_rows_company_scope(deliveries, company_id, "Поставки заявки")
        received_deliveries = [d for d in deliveries if float(d.get("received_quantity") or 0) > 0]
        if rollback_received and (effective_user.get("role") not in LEADERSHIP_ROLES):
            conn.rollback()
            raise HTTPException(status_code=403, detail="Откат принятой поставки доступен только директору или замдиректора")
        if received_deliveries and not rollback_received:
            conn.rollback()
            raise HTTPException(status_code=400, detail="По заявке уже есть принятая поставка. Можно только отменить без удаления истории или выполнить откат руководителем.")
        if rollback_received and received_deliveries:
            delivery_ids = [int(d.get("id") or 0) for d in received_deliveries if int(d.get("id") or 0) > 0]
            cur.execute("""SELECT
                              company_id, 'warehouse_invoice' AS link_type
                              FROM warehouse_invoices
                              WHERE supply_request_id=%s OR (supply_delivery_id = ANY(%s))
                            UNION ALL
                            SELECT company_id, 'supply_history' AS link_type
                              FROM supply_history
                              WHERE request_id=%s OR (delivery_id = ANY(%s))""",
                        (id, delivery_ids, id, delivery_ids))
            linked_docs = cur.fetchall()
            assert_rows_company_scope(linked_docs, company_id, "Документы поставки")
            if linked_docs:
                conn.rollback()
                raise HTTPException(
                    status_code=400,
                    detail="Откат принятой поставки запрещён после формирования накладной или истории. Оформите сторно отдельным документом, чтобы не потерять связь складского учёта."
                )

        if not rollback_received:
            cur.execute("UPDATE supply_requests SET status=%s WHERE id=%s", ("Отменена", id))
            conn.commit()
            log_audit(
                effective_user.get("name", ""),
                effective_user.get("role", ""),
                "cancel",
                "supply_request",
                id,
                ("Заявка снабжения отменена: " + str(req.get("material_name") or "") + ", статус " + str(req.get("status") or ""))[:250],
                req.get("project") or "",
            )
            return {"ok": True, "cancelled": True, "deliveriesKept": len(deliveries)}

        restored = 0
        if rollback_received:
            for d in received_deliveries:
                qty = float(d.get("received_quantity") or 0)
                name = d.get("material_name") or ""
                project = d.get("project") or ""
                unit = _norm_base_unit(d.get("unit") or "шт") or "шт"
                work_package = _supply_work_package(d.get("work_package") or d.get("workPackage") or req.get("work_package"))
                if not name or not project or qty <= 0:
                    continue
                cur.execute("""SELECT id, quantity FROM materials
                               WHERE company_id=%s AND name=%s AND project=%s AND COALESCE(NULLIF(work_package,''),'Основная')=%s
                                 AND """ + _sql_norm_unit("unit") + """=%s
                               ORDER BY id LIMIT 1 FOR UPDATE""", (company_id, name, project, work_package, unit))
                mat = cur.fetchone()
                if not mat:
                    conn.rollback()
                    raise HTTPException(status_code=400, detail="Нельзя откатить поставку: материал «"+name+"» не найден на складе объекта" + (" по пакету «"+work_package+"»" if work_package else "") + ".")
                stock_qty = float(mat.get("quantity") or 0)
                if stock_qty + 0.000001 < qty:
                    conn.rollback()
                    raise HTTPException(status_code=400, detail="Нельзя откатить поставку «"+name+"»: на складе осталось "+str(stock_qty)+" "+unit+", а принять было "+str(qty)+" "+unit+". Материал уже списывали.")
                remaining_qty = stock_qty - qty
                if remaining_qty <= 0.000001:
                    cur.execute("DELETE FROM materials WHERE id=%s", (mat.get("id"),))
                else:
                    cur.execute("UPDATE materials SET quantity=%s WHERE id=%s", (remaining_qty, mat.get("id")))
                cur.execute("INSERT INTO warehouse_history (company_id,material,type,quantity,unit,date,project,issued_by,work_package,date_time) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)",
                            (company_id, name, "откат поставки (удаление заявки)", qty, unit, datetime.now().date().isoformat(), project, effective_user.get("name") or "", work_package, datetime.now().strftime("%d.%m.%Y, %H:%M")))
                restored += 1

        cur.execute("UPDATE supply_requests SET status=%s WHERE id=%s", ("Отменена с откатом", id))
        conn.commit()
        log_audit(
            effective_user.get("name", ""),
            effective_user.get("role", ""),
            "rollback",
            "supply_request",
            id,
            ("Заявка снабжения отменена с откатом: " + str(req.get("material_name") or "") + ", восстановлено " + str(restored))[:250],
            req.get("project") or "",
        )
        return {"ok": True, "cancelled": True, "deliveriesKept": len(deliveries), "materialsRolledBack": restored}
    except HTTPException:
        conn.rollback()
        raise
    except Exception as e:
        conn.rollback()
        raise HTTPException(status_code=500, detail=str(e))
    finally:
        cur.close()
        conn.close()

@app.get("/supply-requests/{id}/stock-check")
def supply_request_stock_check(id: int, current_user: dict = Depends(require_roles(*SUPPLY_ROLES))):
    """Возвращает остатки похожих материалов на складе и бюджет проекта.
       Используется UI чтобы показать «есть X из Y, закупить Z»."""
    conn = None
    try:
        conn = get_db()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        is_worker = current_user.get("role") in WORKER_EXECUTION_ROLES
        cur.execute("""SELECT material_name, quantity, unit, project, COALESCE(work_package,'') AS work_package,
                              items_json, requested_by_id, created_by
                       FROM supply_requests WHERE id=%s""", (id,))
        req = cur.fetchone()
        if not req:
            return {"error": "Заявка не найдена"}
        if is_worker:
            current_user_id = str(current_user.get("id") or "")
            current_user_name = (current_user.get("name") or "").strip().lower()
            request_user_id = str(req.get("requested_by_id") or "")
            request_author = (req.get("created_by") or "").strip().lower()
            if request_user_id != current_user_id and request_author != current_user_name:
                raise HTTPException(status_code=403, detail="Исполнитель может проверять склад только по своей заявке")
        request_items = _json_list_or_empty(req.get("items_json"))
        if not request_items:
            request_items = [{"materialName": req.get("material_name") or "", "quantity": req.get("quantity") or 0, "unit": req.get("unit") or "шт", "workPackage": req.get("work_package") or ""}]
        request_items = [
            {
                "materialName": (it.get("materialName") or it.get("name") or "").strip(),
                "quantity": _float_or_zero(it.get("quantity")),
                "unit": it.get("unit") or req.get("unit") or "шт",
                "workPackage": _supply_work_package(it.get("workPackage") or it.get("work_package") or req.get("work_package")),
            }
            for it in request_items if isinstance(it, dict)
        ]
        request_items = [it for it in request_items if it["materialName"] and it["quantity"] > 0]
        for req_item in request_items:
            if not has_package_access(current_user, req_item["workPackage"]):
                raise HTTPException(status_code=403, detail="Нет доступа к разделу сметы заявки: " + req_item["workPackage"])
        display_name = (request_items[0]["materialName"] if len(request_items) == 1 else (req['material_name'] or '')).strip()
        project = (req['project'] or '').strip()
        if project:
            require_project_access(current_user, project)
        needed = sum(_float_or_zero(it.get("quantity")) for it in request_items) if request_items else float(req['quantity'] or 0)
        # Поиск похожих материалов на основном складе (ILIKE по части имени)
        stock_matches = []
        total_available = 0.0
        item_checks = []
        for req_item in request_items:
            name = req_item["materialName"]
            item_package = _supply_work_package(req_item.get("workPackage"))
            item_available = 0.0
            # Берём первое значащее слово (>=4 символа) для гибкого поиска
            tokens = [t for t in name.split() if len(t) >= 4]
            search = tokens[0] if tokens else name
            cur.execute(
                "SELECT id, name, quantity, unit, price, category FROM warehouse_main WHERE name ILIKE %s ORDER BY quantity DESC LIMIT 10",
                ('%' + search + '%',))
            for row in cur.fetchall():
                stock_matches.append({
                    "id": row['id'], "name": row['name'],
                    "quantity": float(row['quantity'] or 0),
                    "unit": row['unit'], "price": 0 if is_worker else float(row['price'] or 0),
                    "category": row['category'],
                    "workPackage": "",
                    "requestItem": name,
                })
                item_available += float(row['quantity'] or 0)
            # Также ищем на складе объекта (materials)
            if project:
                try:
                    cur.execute(
                        """SELECT id, name, quantity, unit, price, category, COALESCE(work_package,'') AS work_package
                           FROM materials
                           WHERE project=%s AND name ILIKE %s AND COALESCE(NULLIF(work_package,''),'Основная')=%s
                           LIMIT 10""",
                        (project, '%' + search + '%', item_package))
                    for row in cur.fetchall():
                        stock_matches.append({
                            "id": row['id'], "name": '[На объекте] ' + (row['name'] or ''),
                            "quantity": float(row['quantity'] or 0),
                            "unit": row['unit'], "price": 0 if is_worker else float(row['price'] or 0),
                            "category": row['category'],
                            "workPackage": _supply_work_package(row.get("work_package")),
                            "requestItem": name,
                        })
                        item_available += float(row['quantity'] or 0)
                except Exception:
                    pass
            item_checks.append({
                "materialName": name,
                "needed": req_item["quantity"],
                "unit": req_item["unit"],
                "workPackage": item_package,
                "available": item_available,
                "shortage": max(0.0, req_item["quantity"] - item_available),
            })
            total_available += item_available
        # Бюджет проекта
        project_budget = 0.0
        project_approved_cost = 0.0
        project_pending_cost = 0.0
        if project:
            try:
                cur.execute("SELECT budget FROM projects WHERE name=%s", (project,))
                pr = cur.fetchone()
                project_budget = float(pr['budget'] or 0) if pr else 0.0
            except Exception:
                project_budget = 0.0
            # Считаем оценочную стоимость уже утверждённых/ожидающих заявок по реальным строкам items_json.
            # Старые агрегаты вида «N позиций» нельзя умножать как материал: это ломает бюджет и пакеты работ.
            try:
                cur.execute(
                    "SELECT material_name, quantity, unit, status, COALESCE(work_package,'') AS work_package, items_json FROM supply_requests WHERE project=%s",
                    (project,))
                requests_rows = cur.fetchall()
                for row in requests_rows:
                    raw_items = _json_list_or_empty(row.get("items_json"))
                    if not raw_items:
                        raw_items = [{
                            "materialName": row.get("material_name") or "",
                            "quantity": row.get("quantity") or 0,
                            "unit": row.get("unit") or "шт",
                            "workPackage": _supply_work_package(row.get("work_package")),
                        }]
                    for item in raw_items:
                        if not isinstance(item, dict):
                            continue
                        mname = (item.get("materialName") or item.get("name") or "").strip()
                        qty = _float_or_zero(item.get("quantity"))
                        if not mname or qty <= 0:
                            continue
                        first_word = mname.split()[0]
                        try:
                            cur.execute(
                                "SELECT AVG(price) AS avg_price FROM warehouse_main WHERE name ILIKE %s",
                                ('%' + first_word + '%',))
                            avg_row = cur.fetchone()
                            avg_price = float(avg_row['avg_price'] or 0) if avg_row else 0.0
                        except Exception:
                            avg_price = 0.0
                        est_cost = qty * avg_price
                        if row['status'] == 'Утверждена':
                            project_approved_cost += est_cost
                        elif row['status'] in ('Новая', 'Подтверждена прорабом'):
                            project_pending_cost += est_cost
            except Exception:
                pass
        shortage = sum(item["shortage"] for item in item_checks) if item_checks else max(0.0, needed - total_available)
        budget_risk = 0.0
        if project_budget > 0:
            budget_risk = (project_approved_cost + project_pending_cost) / project_budget * 100
        return {
            "requestId": id,
            "materialName": display_name,
            "needed": needed,
            "unit": req['unit'],
            "workPackage": req.get("work_package") or "",
            "items": request_items,
            "itemChecks": item_checks,
            "totalAvailable": total_available,
            "shortage": shortage,
            "stockMatches": stock_matches,
            "project": project,
            "projectBudget": 0 if is_worker else project_budget,
            "projectApprovedCost": 0 if is_worker else project_approved_cost,
            "projectPendingCost": 0 if is_worker else project_pending_cost,
            "budgetRiskPercent": 0 if is_worker else budget_risk,
        }
    except Exception as e:
        import traceback
        print("STOCK-CHECK ERROR id=" + str(id) + ": " + str(e))
        print(traceback.format_exc())
        return {"error": "Ошибка сервера: " + str(e)[:200]}
    finally:
        if conn:
            try: conn.close()
            except Exception: pass

OFFERS_SELECT = ("SELECT id, request_id as \"requestId\", supplier_id as \"supplierId\","
                 "company_id as \"companyId\","
                 "price_per_unit as \"pricePerUnit\", total_price as \"totalPrice\","
                 "delivery_days as \"deliveryDays\", notes, status,"
                 "delivery_status as \"deliveryStatus\","
                 "payment_terms as \"paymentTerms\", vat_included as \"vatIncluded\","
                 "pdf_url as \"pdfUrl\", valid_until as \"validUntil\","
                 "supplier_message as \"supplierMessage\","
                 "requested_at as \"requestedAt\", responded_at as \"respondedAt\","
                 "ai_recommended as \"aiRecommended\","
                 "items_kp_json as \"itemsKpJson\" "
                 "FROM supplier_offers")

def _require_supplier_offer_visibility(cur, offer_id: int, user: dict, detail: str = "Нет доступа к КП"):
    _ensure_supply_request_recipients_table(cur)
    supplier_ids = current_supplier_ids(cur, user)
    visibility_sql, visibility_params = supplier_offer_visibility_filter(
        supplier_ids,
        user.get("id"),
    )
    cur.execute(
        "SELECT id FROM supplier_offers WHERE id=%s" + visibility_sql,
        [offer_id] + visibility_params,
    )
    if not cur.fetchone():
        raise HTTPException(status_code=403, detail=detail)

def _find_supply_request_recipient(cur, request_id: int, company_id: int, supplier_ids, supplier_user_id=None):
    identity_sql, identity_params = supplier_recipient_identity_filter(
        supplier_ids,
        supplier_user_id,
    )
    cur.execute(
        """
        SELECT recipient.id, recipient.supplier_id, recipient.target_supplier_id,
               recipient.supplier_user_id, recipient.supplier_group_ids
          FROM supply_request_recipients recipient
         WHERE recipient.request_id=%s
           AND recipient.company_id=%s
           AND """ + identity_sql + """
         ORDER BY
           CASE WHEN recipient.supplier_user_id=%s THEN 0 ELSE 1 END,
           recipient.id
         LIMIT 1
        """,
        [request_id, company_id] + identity_params + [int(supplier_user_id or 0)],
    )
    return cur.fetchone()

def _ensure_supplier_offer_events_table(cur):
    cur.execute("""
        CREATE TABLE IF NOT EXISTS supplier_offer_events (
            id SERIAL PRIMARY KEY,
            offer_id INT,
            event_type VARCHAR(100),
            status_from VARCHAR(100),
            status_to VARCHAR(100),
            actor_name VARCHAR(255),
            actor_role VARCHAR(100),
            payload_json TEXT,
            created_at TIMESTAMP DEFAULT NOW()
        )
    """)

def _supplier_offer_event_payload(data: dict) -> str:
    if not isinstance(data, dict):
        return "{}"
    allowed = {
        "action", "pricePerUnit", "totalPrice", "deliveryDays", "paymentTerms",
        "vatIncluded", "validUntil", "supplierMessage", "pdfUrl", "itemsKp",
        "status", "deliveryStatus", "invoiceId", "invoiceNumber", "amount",
        "vatAmount", "duplicateDocument",
    }
    payload = {k: data.get(k) for k in allowed if k in data}
    return json.dumps(payload, ensure_ascii=False, default=str)

def _log_supplier_offer_event(cur, offer_id: int, event_type: str, status_from: str, status_to: str, actor: dict, data: dict = None):
    _ensure_supplier_offer_events_table(cur)
    cur.execute(
        """
        INSERT INTO supplier_offer_events
            (offer_id, event_type, status_from, status_to, actor_name, actor_role, payload_json)
        VALUES (%s,%s,%s,%s,%s,%s,%s)
        """,
        (
            offer_id,
            event_type,
            status_from or "",
            status_to or "",
            actor.get("name") or actor.get("email") or "",
            actor.get("role") or "",
            _supplier_offer_event_payload(data or {}),
        ),
    )


@app.post("/supply-requests/{id}/request-kp")
def request_kp_from_suppliers(
    id: int,
    data: dict,
    x_company_id: Optional[str] = Header(default=None, alias="X-Company-Id"),
    x_company_mode: Optional[str] = Header(default=None, alias="X-Company-Mode"),
    _current_user: dict = Depends(get_current_user),
):
    """Директор отправляет запрос КП нескольким поставщикам.
       data: {supplierIds: [1,2,3], aiRecommendedIds: [1,2]}"""
    try:
        supplier_ids = sorted({int(x) for x in (data.get('supplierIds') or []) if int(x) > 0})
        ai_ids = {int(x) for x in (data.get('aiRecommendedIds') or []) if int(x) > 0}
    except Exception:
        raise HTTPException(status_code=400, detail="Некорректный список поставщиков")
    if not supplier_ids:
        return {"error": "Не выбраны поставщики"}
    conn = get_db()
    conn.autocommit = False
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    try:
        _ensure_supply_runtime_columns(cur)
        # Получаем количество из заявки для preview total
        cur.execute("SELECT quantity, project, status, company_id FROM supply_requests WHERE id=%s FOR UPDATE", (id,))
        req = cur.fetchone()
        if not req:
            raise HTTPException(status_code=404, detail="Заявка не найдена")
        claimed_company_id = data.get("companyId") if "companyId" in data else data.get("company_id")
        company_context, effective_user = resolve_resource_company_actor(
            cur,
            _current_user,
            req.get("company_id"),
            "update",
            claimed_company_id=claimed_company_id,
            x_company_id=x_company_id,
            x_company_mode=x_company_mode,
            allowed_roles=SUPPLY_INTERNAL_ROLES,
            forbidden_detail="Роль в выбранной компании не позволяет запрашивать КП",
            platform_staff_roles=PLATFORM_STAFF_ROLES,
            client_account_roles=CLIENT_ACCOUNT_ROLES,
        )
        company_id = int(company_context.get("companyId"))
        if req.get('project'):
            require_project_or_warehouse_access(effective_user, req.get('project') or "")
            project_company_id = _project_company_id(cur, req.get('project') or "")
            if project_company_id and int(project_company_id) != company_id:
                raise HTTPException(status_code=400, detail="Выбранная компания не совпадает с компанией объекта. Переключите компанию в шапке или выберите другой объект.")
        if (req.get("status") or "Новая") not in ("Утверждена", "КП запрошены"):
            raise HTTPException(status_code=400, detail="Запрашивать КП можно только после утверждения заявки директором")
        selected_scope_ids = supplier_group_scope_ids(cur, supplier_ids)
        recipient_rows = _upsert_supply_request_recipients(cur, id, company_id, selected_scope_ids)
        assert_rows_company_scope(recipient_rows, company_id, "Получатели КП")
        visibility_error = _recipient_visibility_error(recipient_rows)
        if visibility_error:
            raise HTTPException(status_code=400, detail=visibility_error)
        created = _create_supplier_offer_requests(cur, id, selected_scope_ids, ai_ids, company_id=company_id)
        cur.execute(
            "SELECT company_id FROM supply_request_recipients WHERE request_id=%s FOR UPDATE",
            (id,),
        )
        assert_rows_company_scope(cur.fetchall(), company_id, "Получатели КП")
        cur.execute(
            "SELECT company_id FROM supplier_offers WHERE request_id=%s FOR UPDATE",
            (id,),
        )
        assert_rows_company_scope(cur.fetchall(), company_id, "Коммерческие предложения")
        # Обновляем статус заявки
        cur.execute("""UPDATE supply_requests
                       SET status=CASE WHEN status='Утверждена' THEN %s ELSE status END,
                           selected_suppliers=(
                               SELECT ARRAY(
                                   SELECT DISTINCT unnest(COALESCE(selected_suppliers, '{}'::int[]) || %s::int[])
                               )
                           )
                       WHERE id=%s AND company_id=%s""",
            ('КП запрошены', selected_scope_ids, id, company_id))
        if cur.rowcount != 1:
            raise HTTPException(status_code=409, detail="Компания заявки изменилась во время запроса КП")
        notification_rows = _notify_supply_request_recipients(cur, id, company_id=company_id)
        conn.commit()
        return {
            "ok": True,
            "created": len(created),
            "ids": created,
            "supplierIds": selected_scope_ids,
            "companyId": company_id,
            "recipients": recipient_rows,
            "notifications": notification_rows,
        }
    except HTTPException:
        conn.rollback()
        raise
    except Exception:
        conn.rollback()
        raise
    finally:
        cur.close()
        conn.close()

@app.get("/supply-requests/{id}/recipients")
def get_supply_request_recipients(
    id: int,
    x_company_id: Optional[str] = Header(default=None, alias="X-Company-Id"),
    x_company_mode: Optional[str] = Header(default=None, alias="X-Company-Mode"),
    _current_user: dict = Depends(get_current_user),
):
    conn = get_db()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    _ensure_supply_request_recipients_table(cur)
    cur.execute("SELECT id, project, company_id FROM supply_requests WHERE id=%s", (id,))
    req = cur.fetchone()
    if not req:
        cur.close(); conn.close()
        raise HTTPException(status_code=404, detail="Заявка не найдена")
    try:
        company_context, effective_user = resolve_resource_company_actor(
            cur,
            _current_user,
            req.get("company_id"),
            "read",
            x_company_id=x_company_id,
            x_company_mode=x_company_mode,
            allowed_roles=SUPPLY_INTERNAL_ROLES,
            forbidden_detail="Роль в выбранной компании не позволяет смотреть получателей КП",
            platform_staff_roles=PLATFORM_STAFF_ROLES,
            client_account_roles=CLIENT_ACCOUNT_ROLES,
        )
        company_id = int(company_context.get("companyId"))
    except Exception:
        cur.close(); conn.close()
        raise
    if req.get("project"):
        require_project_or_warehouse_access(effective_user, req.get("project") or "")
    cur.execute("SELECT company_id FROM supply_request_recipients WHERE request_id=%s", (id,))
    try:
        assert_rows_company_scope(cur.fetchall(), company_id, "Получатели КП")
    except Exception:
        cur.close(); conn.close()
        raise
    cur.execute("""
        SELECT r.id, r.company_id AS "companyId", r.request_id AS "requestId",
               r.supplier_id AS "supplierId", s0.name AS "supplierName", s0.email AS "supplierEmail",
               r.target_supplier_id AS "targetSupplierId", s.name AS "targetSupplierName", s.email AS "targetSupplierEmail",
               r.supplier_user_id AS "supplierUserId",
               r.supplier_group_ids AS "supplierGroupIds",
               r.visible_to_supplier AS "visibleToSupplier",
               r.problem_reason AS "problemReason",
               r.email_notification_status AS "emailNotificationStatus",
               r.email_sent_at AS "emailSentAt",
               r.max_notification_status AS "maxNotificationStatus",
               r.max_outbox_id AS "maxOutboxId",
               r.max_queued_at AS "maxQueuedAt",
               r.status,
               r.requested_at AS "requestedAt",
               r.responded_at AS "respondedAt"
          FROM supply_request_recipients r
          LEFT JOIN suppliers s0 ON s0.id=r.supplier_id
          LEFT JOIN suppliers s ON s.id=r.target_supplier_id
         WHERE r.request_id=%s AND r.company_id=%s
         ORDER BY r.id
    """, (id, company_id))
    rows = [_add_supply_recipient_link_hint(dict(row)) for row in cur.fetchall()]
    if not rows:
        cur.execute("""
            SELECT o.id AS offer_id, o.request_id, o.company_id, o.supplier_id,
                   o.status, o.requested_at, o.responded_at, s.name AS supplier_name, s.email AS supplier_email
              FROM supplier_offers o
              LEFT JOIN suppliers s ON s.id=o.supplier_id
             WHERE o.request_id=%s
             ORDER BY o.id
        """, (id,))
        offer_rows = cur.fetchall() or []
        try:
            assert_rows_company_scope(offer_rows, company_id, "Коммерческие предложения")
        except Exception:
            cur.close(); conn.close()
            raise
        offer_supplier_ids = [
            int(_row_get(offer, "supplier_id", 3, 0) or 0)
            for offer in offer_rows
            if int(_row_get(offer, "supplier_id", 3, 0) or 0) > 0
        ]
        offer_targets = supplier_offer_targets_for_groups(cur, offer_supplier_ids)
        target_by_requested_id = {
            int(target.get("requested_id") or 0): target
            for target in offer_targets
        }
        target_ids = [int(target.get("target_id") or 0) for target in offer_targets if int(target.get("target_id") or 0) > 0]
        target_names = {}
        if target_ids:
            cur.execute("SELECT id,name FROM suppliers WHERE id = ANY(%s)", (target_ids,))
            target_names = {
                int(_row_get(row, "id", 0, 0) or 0): _row_get(row, "name", 1, "") or ""
                for row in (cur.fetchall() or [])
            }
        recipient_map = {}
        for offer in offer_rows:
            supplier_id = int(_row_get(offer, "supplier_id", 3, 0) or 0)
            if not supplier_id:
                continue
            target = target_by_requested_id.get(supplier_id) or {
                "requested_id": supplier_id,
                "target_id": supplier_id,
                "scope_ids": [supplier_id],
            }
            target_id = int(target.get("target_id") or supplier_id)
            scope_ids = _normalize_supplier_ids(target.get("scope_ids") or [supplier_id])
            visibility = _supplier_visibility_for_scope(cur, scope_ids)
            group_key = tuple(sorted(scope_ids)) or (target_id,)
            offer_status = _row_get(offer, "status", 4, "") or "Ожидает ответа"
            offer_status_row = {
                "offerId": _row_get(offer, "offer_id", 0, None),
                "supplierId": supplier_id,
                "supplierName": _row_get(offer, "supplier_name", 7, "") or ("Поставщик #" + str(supplier_id)),
                "status": offer_status,
            }
            if group_key in recipient_map:
                recipient_map[group_key]["offerStatuses"].append(offer_status_row)
                if recipient_map[group_key].get("status") in ("Отозвано", "Отклонено") and offer_status not in ("Отозвано", "Отклонено"):
                    recipient_map[group_key]["status"] = offer_status
                continue
            recipient_map[group_key] = {
                "id": -int(_row_get(offer, "offer_id", 0, 0) or 0),
                "companyId": company_id,
                "requestId": id,
                "supplierId": supplier_id,
                "supplierName": _row_get(offer, "supplier_name", 7, "") or ("Поставщик #" + str(supplier_id)),
                "targetSupplierId": target_id,
                "targetSupplierName": target_names.get(target_id) or _row_get(offer, "supplier_name", 7, "") or ("Поставщик #" + str(target_id)),
                "targetSupplierEmail": _row_get(offer, "supplier_email", 8, ""),
                "supplierEmail": _row_get(offer, "supplier_email", 8, ""),
                "supplierUserId": visibility.get("user_id"),
                "supplierGroupIds": scope_ids,
                "visibleToSupplier": bool(visibility.get("visible")),
                "problemReason": visibility.get("reason") or "",
                "emailNotificationStatus": "",
                "emailSentAt": None,
                "maxNotificationStatus": "",
                "maxOutboxId": None,
                "maxQueuedAt": None,
                "status": _row_get(offer, "status", 4, "") or "Ожидает ответа",
                "requestedAt": _row_get(offer, "requested_at", 5, None),
                "respondedAt": _row_get(offer, "responded_at", 6, None),
                "source": "supplier_offers",
                "offerStatuses": [offer_status_row],
            }
        rows = [_add_supply_recipient_link_hint(row) for row in recipient_map.values()]
    cur.close(); conn.close()
    return rows

@app.get("/supply-requests/{id}/suggest-suppliers")
def suggest_suppliers_for_request(id: int, current_user: dict = Depends(require_roles(*SUPPLY_INTERNAL_ROLES))):
    """Возвращает список поставщиков подходящих под категорию материала, ранжированных
       по рейтингу + истории успешных поставок. AI-комментарий опциональный."""
    conn = get_db()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    cur.execute("SELECT material_name, category, project FROM supply_requests WHERE id=%s", (id,))
    req = cur.fetchone()
    if not req:
        conn.close()
        return {"error": "not found"}
    if req.get('project'):
        require_project_access(current_user, req.get('project') or "")
    category = (req['category'] or '').strip()
    material_name = (req['material_name'] or '').lower()
    # Фильтр по категории если задана. Иначе берём всех активных
    if category:
        cur.execute(
            "SELECT id, name, category, specialization, rating, phone, email, status FROM suppliers "
            "WHERE (status IS NULL OR status='Активный' OR status='') AND category=%s ORDER BY rating DESC NULLS LAST",
            (category,))
    else:
        cur.execute(
            "SELECT id, name, category, specialization, rating, phone, email, status FROM suppliers "
            "WHERE (status IS NULL OR status='Активный' OR status='') ORDER BY rating DESC NULLS LAST")
    suppliers = [dict(r) for r in cur.fetchall()]
    # Считаем историю успешных поставок (status='Доставлено') по каждому поставщику
    cur.execute("SELECT supplier_id, COUNT(*) as deliveries FROM supply_history WHERE status='Доставлено' GROUP BY supplier_id")
    deliveries_map = {r['supplier_id']: r['deliveries'] for r in cur.fetchall()}
    # Считаем уже отправленные КП этой заявке
    cur.execute("SELECT supplier_id FROM supplier_offers WHERE request_id=%s AND COALESCE(status,'') NOT IN ('Отклонено','Отозвано')", (id,))
    already_requested = {r['supplier_id'] for r in cur.fetchall()}
    conn.close()
    for s in suppliers:
        s['deliveriesCount'] = int(deliveries_map.get(s['id'], 0))
        s['alreadyRequested'] = s['id'] in already_requested
        # Простая логика: AI рекомендует если category совпадает + (rating>=4 OR deliveries>=1)
        score = 0
        if s['rating']: score += float(s['rating'])
        if s['deliveriesCount']: score += min(s['deliveriesCount'], 5)
        if material_name and (s.get('specialization') or '').lower() and any(w in material_name for w in (s['specialization'] or '').lower().split()):
            score += 2
        s['_score'] = score
        s['aiRecommend'] = score >= 5  # порог рекомендации
    suppliers.sort(key=lambda x: -x['_score'])
    return {
        "requestId": id,
        "materialName": req['material_name'],
        "category": category,
        "suppliers": suppliers[:15],  # топ 15
        "aiRecommendedCount": sum(1 for s in suppliers if s.get('aiRecommend')),
    }

@app.get("/supply-requests/{id}/compare-kp")
def compare_kp_for_request(id: int, current_user: dict = Depends(require_roles(*SUPPLY_INTERNAL_ROLES))):
    """Сравнивает все полученные КП по заявке и возвращает AI-вердикт.
       Учитывает цену, срок поставки, условия оплаты, НДС, рейтинг поставщика."""
    conn = get_db()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    cur.execute("SELECT material_name, quantity, unit, project FROM supply_requests WHERE id=%s", (id,))
    req = cur.fetchone()
    if not req:
        conn.close()
        return {"error": "Заявка не найдена"}
    if req.get('project'):
        require_project_access(current_user, req.get('project') or "")
    cur.execute(
        "SELECT o.id, o.supplier_id, o.price_per_unit, o.total_price, o.delivery_days, "
        "o.payment_terms, o.vat_included, o.valid_until, o.supplier_message, o.status, "
        "s.name as supplier_name, s.rating "
        "FROM supplier_offers o LEFT JOIN suppliers s ON s.id=o.supplier_id "
        "WHERE o.request_id=%s AND o.status IN ('Получено','Утверждено')",
        (id,))
    offers = [dict(r) for r in cur.fetchall()]
    conn.close()
    if len(offers) < 2:
        return {
            "error": "Нужно минимум 2 полученных КП для сравнения",
            "offersCount": len(offers),
        }
    # Готовим короткую сводку для AI
    offers_summary = []
    for o in offers:
        offers_summary.append({
            "offerId": o['id'],
            "supplier": o['supplier_name'] or 'Поставщик #'+str(o['supplier_id']),
            "rating": float(o['rating'] or 0),
            "pricePerUnit": float(o['price_per_unit'] or 0),
            "totalPrice": float(o['total_price'] or 0),
            "deliveryDays": int(o['delivery_days'] or 0),
            "paymentTerms": o['payment_terms'] or '',
            "vatIncluded": bool(o['vat_included']),
            "validUntil": str(o['valid_until']) if o['valid_until'] else None,
            "message": o['supplier_message'] or '',
        })
    # Считаем простой score:
    # - ниже цена = лучше
    # - меньше срок = лучше
    # - предоплата = чуть хуже (риск)
    # - выше рейтинг = лучше
    prices = [o['pricePerUnit'] for o in offers_summary if o['pricePerUnit']>0] or [1]
    days = [o['deliveryDays'] for o in offers_summary if o['deliveryDays']>0] or [1]
    min_price = min(prices); max_price = max(prices)
    min_days = min(days); max_days = max(days)
    def _terms_risk(t):
        t = (t or '').lower()
        if 'предоплат' in t and '100' in t: return 0.0  # риск для покупателя
        if '50' in t: return 0.5
        if 'постоплат' in t or 'отсрочк' in t: return 1.0
        return 0.5
    for o in offers_summary:
        sc_price = 1.0 - (o['pricePerUnit']-min_price)/(max_price-min_price) if max_price>min_price else 1.0
        sc_days = 1.0 - (o['deliveryDays']-min_days)/(max_days-min_days) if max_days>min_days else 1.0
        sc_terms = _terms_risk(o['paymentTerms'])
        sc_rating = o['rating']/5.0 if o['rating'] else 0.5
        # веса: цена 40%, срок 20%, условия 20%, рейтинг 20%
        o['score'] = round((sc_price*0.4 + sc_days*0.2 + sc_terms*0.2 + sc_rating*0.2) * 100, 1)
    offers_summary.sort(key=lambda x: -x['score'])
    best = offers_summary[0]
    # AI вердикт текстом
    ai_text = None
    try:
        prompt = (
            f"Сравни {len(offers_summary)} коммерческих предложений на материал "
            f"«{req['material_name']}» (нужно {req['quantity']} {req['unit']}).\n"
            f"Предложения:\n"
        )
        for o in offers_summary:
            prompt += (
                f"- {o['supplier']} (рейтинг {o['rating']}/5): "
                f"{o['pricePerUnit']} ₽/ед, итого {o['totalPrice']} ₽, "
                f"срок {o['deliveryDays']} дн, оплата «{o['paymentTerms']}», "
                f"{'с НДС' if o['vatIncluded'] else 'без НДС'}"
                + (f", «{o['message']}»" if o['message'] else "")
                + "\n"
            )
        prompt += (
            "\nДай короткий вывод (2-3 предложения по-русски): кого выбрать и почему. "
            "Учитывай не только цену но и срок, условия оплаты, рейтинг поставщика. "
            "Не используй markdown, не используй ```."
        )
        ai_text = generate_supply_kp_comparison(
            prompt,
            "Ты помощник директора строительной компании. Сравниваешь коммерческие предложения и даёшь короткий вывод.",
            YANDEX_API_KEY,
            YANDEX_FOLDER_ID,
            model_gateway_enabled=os.getenv(
                "SUPPLY_KP_COMPARISON_MODEL_GATEWAY_ENABLED",
                "false",
            ).lower() == "true",
        )
    except Exception as e:
        print("compare-kp AI error:", e)
        ai_text = None
    return {
        "requestId": id,
        "materialName": req['material_name'],
        "quantity": float(req['quantity'] or 0),
        "unit": req['unit'],
        "offersCount": len(offers_summary),
        "bestOfferId": best['offerId'],
        "bestSupplier": best['supplier'],
        "ranking": offers_summary,
        "aiText": ai_text,
    }


def _float_or_zero(v):
    try:
        return float(str(v or 0).replace(" ", "").replace(",", "."))
    except Exception:
        return 0.0

def _invoice_number_value(value) -> float:
    """Parse money/quantity from invoice OCR without turning units like 'м2' into 2."""
    if value is None:
        return 0.0
    if isinstance(value, (int, float)):
        return float(value)
    text = str(value).strip()
    if not text:
        return 0.0
    text = (
        text.replace("\xa0", " ")
        .replace("₽", "")
        .replace("руб.", "")
        .replace("руб", "")
        .replace("Р", "")
    )
    match = re.search(r"-?\d[\d\s.,]*", text)
    if not match:
        return 0.0
    raw = match.group(0).replace(" ", "")
    if "," in raw and "." in raw:
        if raw.rfind(",") > raw.rfind("."):
            raw = raw.replace(".", "").replace(",", ".")
        else:
            raw = raw.replace(",", "")
    else:
        raw = raw.replace(",", ".")
    try:
        return float(raw)
    except Exception:
        return 0.0

def _invoice_vat_rate(payload: dict) -> float:
    document = payload.get("document") if isinstance(payload.get("document"), dict) else {}
    vat_label = str(
        payload.get("vat")
        or payload.get("vatType")
        or payload.get("tax")
        or document.get("vat")
        or ""
    ).lower()
    rate = _invoice_number_value(
        payload.get("vatRate")
        or payload.get("vat_rate")
        or payload.get("vatPercent")
        or payload.get("vat_percent")
        or document.get("vatRate")
        or document.get("vat_rate")
    )
    if rate:
        return rate
    if "22" in vat_label:
        return 22
    if "20" in vat_label:
        return 20
    if "10" in vat_label:
        return 10
    return 0

def _normalize_invoice_totals_payload(payload: dict) -> dict:
    payload = dict(payload or {})
    totals = payload.get("totals") if isinstance(payload.get("totals"), dict) else {}
    document = payload.get("document") if isinstance(payload.get("document"), dict) else {}

    normalized_items = []
    raw_items = payload.get("items") or payload.get("positions") or []
    if not isinstance(raw_items, list):
        raw_items = []
    for idx, raw_item in enumerate(raw_items[:500], start=1):
        if not isinstance(raw_item, dict):
            continue
        item = dict(raw_item)
        qty = _invoice_number_value(item.get("quantity") or item.get("qty"))
        price = _invoice_number_value(
            item.get("priceWithVat")
            or item.get("price_with_vat")
            or item.get("price")
            or item.get("unitPrice")
            or item.get("unit_price")
        )
        line_total = _invoice_number_value(
            item.get("lineTotalWithVat")
            or item.get("line_total_with_vat")
            or item.get("lineTotal")
            or item.get("line_total")
            or item.get("total")
            or item.get("amount")
            or item.get("sum")
        )
        if not line_total and qty and price:
            line_total = round(qty * price, 2)
        if not price and qty and line_total:
            price = round(line_total / qty, 4)
        item["row"] = item.get("row") or idx
        item["name"] = str(item.get("name") or item.get("title") or item.get("materialName") or "").strip()
        item["quantity"] = qty
        item["unit"] = _norm_base_unit(item.get("unit") or "шт") or "шт"
        item["price"] = price
        item["lineTotal"] = line_total
        normalized_items.append(item)

    items_total = round(sum(_invoice_number_value(item.get("lineTotal")) for item in normalized_items), 2)
    total_base = _invoice_number_value(
        payload.get("totalBase")
        or payload.get("total_base")
        or payload.get("totalWithoutVat")
        or payload.get("total_without_vat")
        or totals.get("totalBase")
        or totals.get("total_base")
        or totals.get("totalWithoutVat")
        or totals.get("total_without_vat")
    )
    total_vat = _invoice_number_value(
        payload.get("totalVat")
        or payload.get("total_vat")
        or payload.get("vatAmount")
        or payload.get("vat_amount")
        or totals.get("totalVat")
        or totals.get("total_vat")
        or totals.get("vatAmount")
        or totals.get("vat_amount")
    )
    total_with_vat = _invoice_number_value(
        payload.get("totalWithVat")
        or payload.get("total_with_vat")
        or payload.get("grandTotal")
        or payload.get("grand_total")
        or payload.get("total")
        or payload.get("amount")
        or totals.get("totalWithVat")
        or totals.get("total_with_vat")
        or totals.get("grandTotal")
        or totals.get("grand_total")
        or totals.get("total")
        or totals.get("amount")
    )
    if not total_with_vat and items_total:
        total_with_vat = items_total
    if not total_with_vat and total_base and total_vat:
        total_with_vat = round(total_base + total_vat, 2)

    vat_label = str(payload.get("vat") or payload.get("tax") or document.get("vat") or "").strip()
    vat_label_lower = vat_label.lower()
    vat_rate = _invoice_vat_rate(payload)
    no_vat = "без" in vat_label_lower and "ндс" in vat_label_lower
    if no_vat:
        total_vat = 0
        if total_with_vat and not total_base:
            total_base = total_with_vat
    elif total_with_vat and total_vat and not total_base:
        total_base = round(total_with_vat - total_vat, 2)
    elif total_with_vat and total_base and not total_vat:
        total_vat = round(max(0, total_with_vat - total_base), 2)
    elif total_with_vat and vat_rate and not total_base and not total_vat:
        total_base = round(total_with_vat / (1 + vat_rate / 100), 2)
        total_vat = round(total_with_vat - total_base, 2)
    elif total_base and vat_rate and not total_vat and not total_with_vat:
        total_vat = round(total_base * vat_rate / 100, 2)
        total_with_vat = round(total_base + total_vat, 2)

    if not vat_label:
        vat_label = "Без НДС" if not vat_rate and not total_vat else f"С НДС {int(vat_rate or 20)}%"
    payload["items"] = normalized_items
    payload["totalBase"] = round(total_base, 2)
    payload["totalVat"] = round(total_vat, 2)
    payload["totalWithVat"] = round(total_with_vat, 2)
    payload["vat"] = vat_label
    return payload

def _json_list_or_empty(value):
    import json as _json
    if isinstance(value, list):
        return value
    if isinstance(value, dict):
        return [value]
    if isinstance(value, (bytes, bytearray)):
        value = value.decode("utf-8", "replace")
    if not value:
        return []
    try:
        parsed = _json.loads(value)
    except Exception:
        return []
    if isinstance(parsed, list):
        return parsed
    if isinstance(parsed, dict):
        return [parsed]
    return []

def _warehouse_invoice_item_signature(item: dict) -> str:
    item = item or {}
    name = _norm_key_text(item.get("name") or item.get("materialName") or item.get("material_name") or "")
    unit = _norm_key_text(item.get("unit") or item.get("unitName") or item.get("unit_name") or "")
    qty = _float_or_zero(item.get("quantity"))
    price = _float_or_zero(item.get("price") or item.get("pricePerUnit") or item.get("price_per_unit"))
    line_total = _float_or_zero(item.get("lineTotal") or item.get("line_total") or item.get("total") or item.get("totalBase"))
    if line_total <= 0 and qty and price:
        line_total = qty * price
    return "|".join([name, unit, f"{qty:.4f}", f"{price:.2f}", f"{line_total:.2f}"])

def _warehouse_invoice_items_signature(items) -> str:
    signatures = [
        _warehouse_invoice_item_signature(item)
        for item in (items or [])
        if isinstance(item, dict)
    ]
    return "||".join(sorted(sig for sig in signatures if sig.strip("|")))

def _find_existing_warehouse_invoice_duplicate(cur, *, company_id, invoice_number, invoice_date, supplier_id, supplier_name, total_with_vat, items):
    company_id = _positive_int_or_none(company_id) or 1
    supplier_id = _positive_int_or_none(supplier_id)
    supplier_name_key = _normalize_supplier_name_key(supplier_name or "")
    input_total = _float_or_zero(total_with_vat)
    input_signature = _warehouse_invoice_items_signature(items)
    invoice_number_lookup_keys = list(build_invoice_number_lookup_keys(invoice_number))
    supplier_scope_ids = set(supplier_related_ids(cur, supplier_id)) if supplier_id else set()

    cur.execute(
        """
        SELECT id,supplier_id,supplier_name,total_with_vat,total_base,items,location,project,number,date
          FROM warehouse_invoices
         WHERE COALESCE(status,'Принята') <> 'Аннулирована'
           AND COALESCE(company_id,1)=%s
           AND (
                COALESCE(date::text,'')=COALESCE(%s::text,'')
                OR regexp_replace(upper(COALESCE(number,'')), '[^[:alnum:]]', '', 'g')=ANY(%s)
           )
         ORDER BY id DESC
        """,
        (company_id, invoice_date, invoice_number_lookup_keys),
    )
    candidates = cur.fetchall() or []
    for candidate in candidates:
        candidate_supplier_id = _positive_int_or_none(_row_get(candidate, "supplier_id", 1))
        candidate_supplier_key = _normalize_supplier_name_key(_row_get(candidate, "supplier_name", 2, "") or "")
        same_supplier = bool(
            (supplier_scope_ids and candidate_supplier_id in supplier_scope_ids)
            or (supplier_name_key and candidate_supplier_key and supplier_name_key == candidate_supplier_key)
        )
        candidate_total = _float_or_zero(_row_get(candidate, "total_with_vat", 3) or _row_get(candidate, "total_base", 4))
        candidate_signature = _warehouse_invoice_items_signature(_json_list_or_empty(_row_get(candidate, "items", 5)))
        match = match_warehouse_invoice_duplicate(
            incoming_number=invoice_number,
            incoming_date=invoice_date,
            incoming_total=input_total,
            incoming_items_signature=input_signature,
            candidate_number=_row_get(candidate, "number", 8, ""),
            candidate_date=_row_get(candidate, "date", 9),
            candidate_total=candidate_total,
            candidate_items_signature=candidate_signature,
            same_supplier=same_supplier,
        )
        if match:
            return {
                "id": _row_get(candidate, "id", 0),
                "supplierName": _row_get(candidate, "supplier_name", 2, "") or "",
                "totalWithVat": candidate_total,
                "match": match,
            }
    return None

def _find_existing_supplier_invoice_duplicate(cur, *, company_id, invoice_number, invoice_date, project_name, supplier_id=None, supplier_name="", amount=0, warehouse_invoice_id=None, request_id=None, offer_id=None):
    company_id = _positive_int_or_none(company_id) or 1
    warehouse_invoice_id = _positive_int_or_none(warehouse_invoice_id)
    supplier_id = _positive_int_or_none(supplier_id)
    supplier_name_key = _normalize_supplier_name_key(supplier_name or "")
    supplier_scope_ids = set(supplier_related_ids(cur, supplier_id)) if supplier_id else set()
    supplier_identity = (
        "ids:" + ",".join(str(value) for value in sorted(supplier_scope_ids))
        if supplier_scope_ids
        else "name:" + supplier_name_key if supplier_name_key else ""
    )
    request_id = _positive_int_or_none(request_id)
    offer_id = _positive_int_or_none(offer_id)
    invoice_date_key = normalize_invoice_date(invoice_date)
    invoice_number_lookup_keys = list(build_invoice_number_lookup_keys(invoice_number))
    for duplicate_lock_key in build_supplier_invoice_lock_keys(
        company_id=company_id,
        invoice_number=invoice_number,
        invoice_date=invoice_date,
        supplier_identity=supplier_identity,
        offer_id=offer_id,
        request_id=request_id,
        warehouse_invoice_id=warehouse_invoice_id,
    ):
        cur.execute(
            "SELECT pg_advisory_xact_lock(hashtext(%s))",
            (duplicate_lock_key,),
        )

    if warehouse_invoice_id:
        cur.execute(
            """
            SELECT id, warehouse_invoice_id, supplier_id, supplier_name, amount
              FROM supplier_invoices
             WHERE COALESCE(status,'') <> 'Аннулирован'
               AND COALESCE(company_id,1)=%s
               AND warehouse_invoice_id=%s
             ORDER BY id DESC
             LIMIT 1
            """,
            (company_id, warehouse_invoice_id),
        )
        row = cur.fetchone()
        if row:
            return {
                "id": _row_get(row, "id", 0),
                "warehouseInvoiceId": _row_get(row, "warehouse_invoice_id", 1),
                "supplierName": _row_get(row, "supplier_name", 3, "") or "",
                "amount": _float_or_zero(_row_get(row, "amount", 4)),
                "match": "warehouse_invoice_id",
            }

    if not invoice_number_lookup_keys or not invoice_date_key:
        return None

    cur.execute(
        """
        SELECT id, warehouse_invoice_id, supplier_id, supplier_name, amount,
               request_id, offer_id, invoice_number, invoice_date
          FROM supplier_invoices
         WHERE COALESCE(status,'') <> 'Аннулирован'
           AND COALESCE(company_id,1)=%s
           AND regexp_replace(upper(COALESCE(invoice_number,'')), '[^[:alnum:]]', '', 'g')=ANY(%s::text[])
           AND COALESCE(invoice_date::text,'')=COALESCE(%s::text,'')
         ORDER BY id DESC
        """,
        (company_id, invoice_number_lookup_keys, invoice_date_key),
    )
    for candidate in cur.fetchall() or []:
        candidate_id = _row_get(candidate, "id", 0)
        candidate_warehouse_id = _positive_int_or_none(_row_get(candidate, "warehouse_invoice_id", 1))
        candidate_supplier_id = _positive_int_or_none(_row_get(candidate, "supplier_id", 2))
        candidate_supplier_key = _normalize_supplier_name_key(_row_get(candidate, "supplier_name", 3, "") or "")
        candidate_amount = _float_or_zero(_row_get(candidate, "amount", 4))
        candidate_request_id = _positive_int_or_none(_row_get(candidate, "request_id", 5))
        candidate_offer_id = _positive_int_or_none(_row_get(candidate, "offer_id", 6))
        same_supplier = bool(
            (supplier_scope_ids and candidate_supplier_id in supplier_scope_ids)
            or (supplier_name_key and candidate_supplier_key and supplier_name_key == candidate_supplier_key)
        )
        match = match_supplier_invoice_duplicate(
            incoming_number=invoice_number,
            incoming_date=invoice_date,
            candidate_number=_row_get(candidate, "invoice_number", 7, ""),
            candidate_date=_row_get(candidate, "invoice_date", 8),
            same_supplier=same_supplier,
            same_offer=bool(
                offer_id and candidate_offer_id and offer_id == candidate_offer_id
            ),
            same_request=bool(
                request_id
                and candidate_request_id
                and request_id == candidate_request_id
            ),
        )
        if match:
            return {
                "id": candidate_id,
                "warehouseInvoiceId": candidate_warehouse_id,
                "supplierName": _row_get(candidate, "supplier_name", 3, "") or "",
                "amount": candidate_amount,
                "match": match,
            }
    return None

def _supplier_invoice_duplicate_score(row) -> int:
    status = str(_row_get(row, "status", default="") or "")
    score = 0
    if _float_or_zero(_row_get(row, "paid_amount", default=0)) > 0:
        score += 100
    if status in ("Оплачен", "Частично оплачен", "Оплачена", "Частично оплачена"):
        score += 70
    elif status in ("Утверждён", "Утвержден", "К оплате"):
        score += 30
    if _positive_int_or_none(_row_get(row, "warehouse_invoice_id")):
        score += 25
    if _positive_int_or_none(_row_get(row, "offer_id")):
        score += 15
    if _positive_int_or_none(_row_get(row, "request_id")):
        score += 12
    if str(_row_get(row, "file_url", default="") or "").strip():
        score += 5
    if str(_row_get(row, "photo_url", default="") or "").strip():
        score += 5
    return score

def _supplier_invoice_duplicate_summary(row) -> dict:
    return {
        "id": _row_get(row, "id"),
        "supplierId": _row_get(row, "supplier_id"),
        "supplierName": _row_get(row, "supplier_name", default="") or "",
        "invoiceNumber": _row_get(row, "invoice_number", default="") or "",
        "invoiceDate": str(_row_get(row, "invoice_date", default="") or ""),
        "projectName": _row_get(row, "project_name", default="") or "",
        "amount": _float_or_zero(_row_get(row, "amount", default=0)),
        "paidAmount": _float_or_zero(_row_get(row, "paid_amount", default=0)),
        "status": _row_get(row, "status", default="") or "",
        "warehouseInvoiceId": _row_get(row, "warehouse_invoice_id"),
        "offerId": _row_get(row, "offer_id"),
        "requestId": _row_get(row, "request_id"),
    }

def _supplier_invoice_duplicate_group_safety(cur, rows) -> dict:
    if len(rows or []) < 2:
        return {"safe": False, "reason": "В группе меньше двух документов"}
    amounts = {round(_float_or_zero(_row_get(row, "amount", default=0)), 2) for row in rows}
    if len(amounts) > 1:
        return {"safe": False, "reason": "В группе разные суммы счетов"}

    paid_rows = [
        row for row in rows
        if _float_or_zero(_row_get(row, "paid_amount", default=0)) > 0
        or str(_row_get(row, "status", default="") or "") in ("Оплачен", "Частично оплачен", "Оплачена", "Частично оплачена")
    ]
    if len(paid_rows) > 1:
        return {"safe": False, "reason": "В группе несколько документов с оплатой или оплаченным статусом"}

    supplier_ids = [
        _positive_int_or_none(_row_get(row, "supplier_id"))
        for row in rows
        if _positive_int_or_none(_row_get(row, "supplier_id"))
    ]
    supplier_keys = {
        _normalize_supplier_name_key(_row_get(row, "supplier_name", default="") or "")
        for row in rows
        if _normalize_supplier_name_key(_row_get(row, "supplier_name", default="") or "")
    }
    same_supplier = False
    if supplier_ids:
        related = set(supplier_related_ids(cur, supplier_ids[0]) or [supplier_ids[0]])
        same_supplier = all(supplier_id in related for supplier_id in supplier_ids)
        if not same_supplier and len(supplier_keys) <= 1:
            same_supplier = True
    else:
        same_supplier = len(supplier_keys) <= 1

    request_ids = {
        _positive_int_or_none(_row_get(row, "request_id"))
        for row in rows
        if _positive_int_or_none(_row_get(row, "request_id"))
    }
    offer_ids = {
        _positive_int_or_none(_row_get(row, "offer_id"))
        for row in rows
        if _positive_int_or_none(_row_get(row, "offer_id"))
    }
    same_chain = (len(request_ids) <= 1 and len(offer_ids) <= 1 and (bool(request_ids) or bool(offer_ids)))

    if not same_supplier and not same_chain:
        return {"safe": False, "reason": "Поставщик/цепочка не совпадают уверенно, нужна ручная сверка"}
    return {"safe": True, "reason": ""}

def _pick_supplier_invoice_canonical(rows):
    ordered = sorted(
        rows or [],
        key=lambda row: (-_supplier_invoice_duplicate_score(row), int(_row_get(row, "id", default=0) or 0)),
    )
    return ordered[0] if ordered else None

