def _supplier_invoice_template_key(value: str) -> str:
    return _normalize_supplier_name_key(value or "")

def _supplier_invoice_template_json(value, fallback):
    if isinstance(value, (dict, list)):
        return value
    if not value:
        return fallback
    try:
        return json.loads(value)
    except Exception:
        return fallback

def _supplier_invoice_template_row(row):
    if not row:
        return None
    return {
        "id": row["id"],
        "supplierId": row.get("supplier_id") or 0,
        "supplierKey": row.get("supplier_key") or "",
        "supplierName": row.get("supplier_name") or "",
        "templateName": row.get("template_name") or "",
        "documentType": row.get("document_type") or "",
        "matchKeywords": _supplier_invoice_template_json(row.get("match_keywords"), []),
        "columnMap": _supplier_invoice_template_json(row.get("column_map"), {}),
        "sample": _supplier_invoice_template_json(row.get("sample_json"), {}),
        "active": bool(row.get("active", True)),
        "usageCount": int(row.get("usage_count") or 0),
        "lastUsedAt": str(row.get("last_used_at")) if row.get("last_used_at") else "",
        "updatedBy": row.get("updated_by") or "",
        "updatedAt": str(row.get("updated_at")) if row.get("updated_at") else "",
        "createdAt": str(row.get("created_at")) if row.get("created_at") else "",
    }

def _scan_invoice_supplier_name(payload: dict) -> str:
    payload = payload or {}
    for key in ("supplier", "supplierName", "supplier_name", "seller", "shipper", "consignor", "sender"):
        text = str(payload.get(key) or "").strip()
        if text:
            return text
    document = payload.get("document") if isinstance(payload.get("document"), dict) else {}
    for key in ("supplier", "supplierName", "seller"):
        text = str(document.get(key) or "").strip()
        if text:
            return text
    return ""

def _find_supplier_by_name_key(cur, supplier_name: str):
    if not _supplier_invoice_template_key(supplier_name):
        return None
    return _supplier_find_match(cur, {"supplierName": supplier_name, "supplier": supplier_name})

def _supplier_invoice_template_match_score(row, supplier_name: str) -> float:
    supplier_key = _supplier_invoice_template_key(supplier_name)
    template_key = str(row.get("supplier_key") or "").strip()
    if supplier_key and template_key and supplier_key == template_key:
        return 1.0
    haystack = " ".join([
        supplier_name or "",
        str(row.get("supplier_name") or ""),
        " ".join(_supplier_invoice_template_json(row.get("match_keywords"), [])),
    ])
    hay_key = _supplier_invoice_template_key(haystack)
    if supplier_key and hay_key:
        if supplier_key in hay_key or hay_key in supplier_key:
            return 0.92
        supplier_words = [w for w in supplier_key.split() if len(w) > 2]
        if supplier_words:
            hits = len([w for w in supplier_words if w in hay_key])
            return hits / max(len(supplier_words), 1)
    return 0.0

def _find_supplier_invoice_template(cur, payload: dict):
    supplier_name = _scan_invoice_supplier_name(payload)
    supplier_key = _supplier_invoice_template_key(supplier_name)
    if not supplier_key:
        return None, supplier_name
    cur.execute("""SELECT *
                   FROM supplier_invoice_templates
                   WHERE active=TRUE
                   ORDER BY usage_count DESC, updated_at DESC, id DESC
                   LIMIT 100""")
    best = None
    for row in cur.fetchall() or []:
        score = _supplier_invoice_template_match_score(row, supplier_name)
        if score >= 0.72 and (not best or score > best["score"]):
            best = {"row": row, "score": score}
    return best, supplier_name

def _invoice_scan_template_hint(limit: int = 12) -> str:
    try:
        conn = get_db()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        cur.execute("""SELECT supplier_name, template_name, document_type, match_keywords, sample_json, usage_count
                       FROM supplier_invoice_templates
                       WHERE active=TRUE
                       ORDER BY usage_count DESC, updated_at DESC, id DESC
                       LIMIT %s""", (limit,))
        rows = cur.fetchall()
        cur.close(); conn.close()
    except Exception as exc:
        print("INVOICE TEMPLATE HINT ERROR:", str(exc))
        return ""
    if not rows:
        return ""
    lines = []
    for row in rows:
        keywords = _supplier_invoice_template_json(row.get("match_keywords"), [])
        if not isinstance(keywords, list):
            keywords = []
        sample = _supplier_invoice_template_json(row.get("sample_json"), {})
        sample_items = sample.get("items") if isinstance(sample, dict) else []
        sample_names = []
        if isinstance(sample_items, list):
            for item in sample_items[:3]:
                if isinstance(item, dict) and item.get("name"):
                    sample_names.append(str(item.get("name")))
        lines.append(
            "- " + (row.get("supplier_name") or "Поставщик")
            + " / " + (row.get("template_name") or "типовой шаблон")
            + " / " + (row.get("document_type") or "любой документ")
            + (": ключи " + ", ".join(str(k) for k in keywords[:4]) if keywords else "")
            + ("; пример строк: " + "; ".join(sample_names) if sample_names else "")
        )
    return "\n".join(lines)

def _apply_supplier_invoice_template_metadata(payload: dict, current_user: dict = None) -> dict:
    payload = dict(payload or {})
    recognition = {
        "method": "ai_ocr",
        "label": "Распознано через AI/OCR",
        "confidence": payload.get("confidence"),
        "templateId": None,
        "templateName": "",
        "supplierId": 0,
        "supplierName": _scan_invoice_supplier_name(payload),
        "warnings": [],
    }
    try:
        conn = get_db()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        supplier_lookup_payload = {
            **payload,
            "supplierName": recognition["supplierName"],
            "supplier": recognition["supplierName"] or payload.get("supplier") or "",
        }
        supplier = _supplier_find_match(cur, supplier_lookup_payload, allow_contact_match=False)
        if supplier:
            recognition["supplierId"] = supplier["id"]
            recognition["supplierName"] = supplier["name"] or recognition["supplierName"]
            _update_supplier_missing_fields(cur, supplier["id"], supplier_lookup_payload)
            _remember_supplier_alias(cur, supplier["id"], supplier_lookup_payload, source="invoice_scan")
        match, _supplier_name = _find_supplier_invoice_template(cur, payload)
        if match:
            row = match["row"]
            template = _supplier_invoice_template_row(row)
            recognition.update({
                "method": "template",
                "label": "Распознано по шаблону поставщика",
                "templateId": template["id"],
                "templateName": template["templateName"] or template["supplierName"],
                "supplierId": template["supplierId"] or recognition["supplierId"],
                "supplierName": template["supplierName"] or recognition["supplierName"],
                "confidence": max(float(payload.get("confidence") or 0), min(1.0, float(match["score"]))),
            })
            payload["supplier"] = recognition["supplierName"] or payload.get("supplier") or ""
            if recognition["supplierId"]:
                _remember_supplier_alias(cur, recognition["supplierId"], supplier_lookup_payload, source="invoice_template")
            cur.execute("""UPDATE supplier_invoice_templates
                           SET usage_count=COALESCE(usage_count,0)+1, last_used_at=NOW()
                           WHERE id=%s""", (template["id"],))
            conn.commit()
        else:
            if recognition["supplierId"]:
                recognition["warnings"].append("Поставщик найден в справочнике, но шаблон еще не сохранен.")
                conn.commit()
            else:
                conn.rollback()
        cur.close(); conn.close()
    except Exception as exc:
        print("INVOICE TEMPLATE APPLY ERROR:", str(exc))
    payload["recognition"] = recognition
    payload["scanRecognition"] = recognition
    return payload


@app.get("/warehouse-invoices")
def get_warehouse_invoices(
    x_company_id: Optional[str] = Header(default=None, alias="X-Company-Id"),
    x_company_mode: Optional[str] = Header(default=None, alias="X-Company-Mode"),
    current_user: dict = Depends(get_current_user),
):
    if not can_see_warehouse_data(current_user):
        return []
    conn = get_db()
    cur = conn.cursor()
    _ensure_warehouse_invoice_accounting_columns(cur)
    _ensure_invoice_document_link_columns(cur)
    conn.commit()
    scope_cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    try:
        company_context = _resolve_work_company_context(
            scope_cur,
            current_user,
            None,
            "read",
            x_company_id=x_company_id,
            x_company_mode=x_company_mode,
        )
        company_filter_sql, company_filter_params = company_id_scope_filter(company_context, "company_id")
    except Exception:
        scope_cur.close()
        cur.close(); conn.close()
        raise
    scope_cur.close()
    invoice_cols = (
        "id,number,date,supplier_id,supplier_name,accepted_by,location,project,vat,items,"
        "total_base,total_vat,total_with_vat,status,added_by,photo_url,source_type,source_id,"
        "supply_delivery_id,supply_request_id,photo_urls,pages_count,warehouse_target,selected_action,"
        "material_match_json,accounting_status,accounting_comment,accounting_updated_by,accounting_updated_at,"
        "paid_amount,paid_at,paid_by,supplier_invoice_id,company_id"
    )
    package_names = user_package_names(current_user) if current_user.get("role") in PACKAGE_LIMIT_ROLES else []
    if current_user.get("role") == "прораб":
        allowed_projects = user_project_names(current_user)
        if not allowed_projects:
            cur.close(); conn.close()
            return []
        cur.execute(f"SELECT {invoice_cols} FROM warehouse_invoices WHERE TRUE{company_filter_sql} AND (project = ANY(%s) OR location = ANY(%s)) ORDER BY id DESC", tuple(company_filter_params + [allowed_projects, allowed_projects]))
    elif current_user.get("role") in ("снабженец", "кладовщик"):
        allowed_projects = user_project_names(current_user)
        if not allowed_projects:
            cur.close(); conn.close()
            return []
        cur.execute(f"SELECT {invoice_cols} FROM warehouse_invoices WHERE TRUE{company_filter_sql} AND (project = ANY(%s) OR location = ANY(%s)) ORDER BY id DESC", tuple(company_filter_params + [allowed_projects, allowed_projects]))
    else:
        cur.execute(f"SELECT {invoice_cols} FROM warehouse_invoices WHERE TRUE{company_filter_sql} ORDER BY id DESC", company_filter_params)
    rows = cur.fetchall()
    cur.close(); conn.close()
    result = []
    for r in rows:
        items = _json_list_or_empty(r[9])
        total_base = float(r[10] or 0)
        total_vat = float(r[11] or 0)
        total_with_vat = float(r[12] or 0)
        if package_names:
            filtered_items = []
            for item in items:
                item_package = (item.get("workPackage") or item.get("work_package") or "Основная").strip() or "Основная"
                if item_package in package_names:
                    filtered_items.append(item)
            if not filtered_items:
                continue
            items = filtered_items
            total_base = sum(_float_or_zero(item.get("total") or item.get("totalBase") or 0) for item in items)
            if total_base <= 0:
                total_base = sum(_float_or_zero(item.get("quantity") or 0) * _float_or_zero(item.get("price") or item.get("pricePerUnit") or 0) for item in items)
            total_vat = 0
            total_with_vat = total_base
        try:
            photo_urls = _json_list_or_empty(r[20])
        except Exception:
            photo_urls = []
        if not photo_urls and r[15]:
            photo_urls = [r[15]]
        material_match = _json_list_or_empty(r[24]) if len(r) > 24 else []
        invoice_result = {"id":r[0],"number":r[1],"date":str(r[2]) if r[2] else "","supplierId":r[3],"supplierName":r[4] or "","acceptedBy":r[5] or "","location":r[6] or "","project":r[7] or "","vat":r[8] or "Без НДС","items":items,"totalBase":total_base,"totalVat":total_vat,"totalWithVat":total_with_vat,"status":r[13] or "Принята","addedBy":r[14] or "","photoUrl":r[15] or "","photos":photo_urls,"pagesCount":r[21] or len(photo_urls) or 1,"sourceType":r[16] or "","sourceId":r[17],"supplyDeliveryId":r[18],"supplyRequestId":r[19],"warehouseTarget":(r[22] if len(r) > 22 else "") or ("object" if r[7] else "main"),"selectedAction":(r[23] if len(r) > 23 else "") or "","materialMatch":material_match,"accountingStatus":(r[25] if len(r) > 25 else "") or "","accountingComment":(r[26] if len(r) > 26 else "") or "","accountingUpdatedBy":(r[27] if len(r) > 27 else "") or "","accountingUpdatedAt":str(r[28]) if len(r) > 28 and r[28] else "","paidAmount":float(r[29] or 0) if len(r) > 29 else 0,"paidAt":(r[30] if len(r) > 30 else "") or "","paidBy":(r[31] if len(r) > 31 else "") or "","supplierInvoiceId":r[32] if len(r) > 32 else None,"companyId":r[33] if len(r) > 33 else None}
        invoice_result["accountingRequired"] = warehouse_invoice_accounting_required(invoice_result)
        result.append(invoice_result)
    return result

def _create_warehouse_invoice_record(data: dict, current_user: dict, *, x_company_id=None, x_company_mode=None):
    import json as j
    target_location = (data.get("location") or "").strip()
    target_project = (data.get("project") or "").strip() or (target_location if target_location and target_location != "Основной склад" else "")
    def _invoice_float(value, default=0.0):
        try:
            return float(str(value).replace(" ", "").replace(",", "."))
        except Exception:
            return default

    conn = get_db()
    cur = conn.cursor()
    conn.autocommit = False
    try:
        _ensure_invoice_document_link_columns(cur)
        source_type = (data.get("sourceType") or "").strip()
        source_id = data.get("sourceId") or None
        supply_delivery_id = data.get("supplyDeliveryId") or None
        supply_request_id = data.get("supplyRequestId") or None
        supplier_invoice_id = int(data.get("supplierInvoiceId") or data.get("supplier_invoice_id") or 0) or None
        supplier_invoice_company_id = None
        if supplier_invoice_id:
            cur.execute("""SELECT project_name, warehouse_invoice_id, company_id
                           FROM supplier_invoices
                           WHERE id=%s AND COALESCE(status,'') <> 'Аннулирован'""", (supplier_invoice_id,))
            supplier_invoice_row = cur.fetchone()
            if not supplier_invoice_row:
                raise HTTPException(status_code=404, detail="Счёт поставщика для связи не найден")
            supplier_invoice_project = (_row_get(supplier_invoice_row, "project_name", 0, "") or "").strip()
            supplier_invoice_warehouse_id = _row_get(supplier_invoice_row, "warehouse_invoice_id", 1)
            supplier_invoice_company_id = _row_get(supplier_invoice_row, "company_id", 2)
            if supplier_invoice_project and target_project and supplier_invoice_project != target_project:
                raise HTTPException(status_code=400, detail="Счёт поставщика относится к другому объекту")
            if supplier_invoice_warehouse_id:
                raise HTTPException(status_code=409, detail="Счёт поставщика уже связан с другой складской накладной")
        if supply_delivery_id or source_type == "supply_delivery":
            raise HTTPException(status_code=400, detail="Накладная по поставке создаётся автоматически при приёмке поставки. Ручное создание отключено, чтобы не задвоить склад.")
        if target_project:
            source_type = source_type or "manual_project_invoice"
        else:
            source_type = source_type or "manual_main_invoice"
        claimed_company_id = _positive_int_or_none(data.get("companyId") or data.get("company_id"))
        project_company_id = _positive_int_or_none(_project_company_id(cur, target_project or target_location))
        request_company_id = None
        if supply_request_id:
            cur.execute("SELECT company_id FROM supply_requests WHERE id=%s", (supply_request_id,))
            request_company_id = _positive_int_or_none(_row_get(cur.fetchone(), "company_id", 0))
        resource_company_ids = {
            value for value in (
                _positive_int_or_none(supplier_invoice_company_id),
                request_company_id,
                project_company_id,
            ) if value
        }
        if len(resource_company_ids) > 1:
            raise HTTPException(status_code=409, detail="Связанные документы накладной относятся к разным компаниям")
        resource_company_id = next(iter(resource_company_ids), None)
        if claimed_company_id and resource_company_id and claimed_company_id != resource_company_id:
            raise HTTPException(status_code=409, detail="companyId не совпадает с компанией объекта или связанного документа")
        scope_cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        try:
            company_context = _resolve_work_company_context(
                scope_cur,
                current_user,
                resource_company_id or claimed_company_id,
                "write",
                x_company_id=x_company_id,
                x_company_mode=x_company_mode,
            )
        finally:
            scope_cur.close()
        company_id = int(company_context.get("companyId") or 0)
        actors = effective_company_actors(current_user, company_context)
        actor = actors[0] if len(actors) == 1 else {}
        if company_id <= 0 or not actor:
            raise HTTPException(status_code=409, detail="Компания складской накладной не определена")
        if (actor.get("role") or "") not in WAREHOUSE_ROLES:
            raise HTTPException(status_code=403, detail="Роль в выбранной компании не позволяет принимать складские накладные")
        current_user = actor
        try:
            receipt_policy = resolve_warehouse_receipt_policy(
                data,
                target_project=target_project,
                role=current_user.get("role") or "",
            )
        except WarehouseReceiptPolicyError as exc:
            raise HTTPException(status_code=exc.status_code, detail=str(exc))
        inventory_only = bool(receipt_policy.get("inventoryOnly"))
        accounting_required = bool(receipt_policy.get("accountingRequired"))
        if inventory_only:
            source_type = "manual_main_receipt"
            data["supplierId"] = None
            data["supplierName"] = ""
            data["supplier"] = ""
            data["syncSupplierInvoice"] = False
        if target_project:
            require_project_or_warehouse_access(current_user, target_project)
        if supplier_invoice_id and current_user.get("role") not in FINANCE_ROLES:
            raise HTTPException(status_code=403, detail="Связать накладную со счётом поставщика может только бухгалтерия или руководство выбранной компании")
        if not target_project and current_user.get("role") not in MAIN_WAREHOUSE_WRITE_ROLES:
            raise HTTPException(
                status_code=403,
                detail="Ручную приходную накладную на основной склад может принять директор, замдиректора, снабженец или кладовщик. Прораб принимает накладные только на закреплённый объект.",
            )
        if supply_delivery_id:
            cur.execute("""SELECT id FROM warehouse_invoices
                           WHERE COALESCE(status,'Принята') <> 'Аннулирована'
                             AND supply_delivery_id=%s
                           LIMIT 1""", (supply_delivery_id,))
            if cur.fetchone():
                raise HTTPException(status_code=409, detail="По этой поставке накладная уже принята")
        if source_type and source_id:
            cur.execute("""SELECT id FROM warehouse_invoices
                           WHERE COALESCE(status,'Принята') <> 'Аннулирована'
                             AND company_id=%s
                             AND source_type=%s AND source_id=%s
                           LIMIT 1""", (company_id, source_type, source_id))
            if cur.fetchone():
                raise HTTPException(status_code=409, detail="По этому источнику накладная уже принята")
        invoice_number = (data.get("number") or "").strip()
        if inventory_only and not invoice_number:
            invoice_number = build_internal_receipt_number()
            data["number"] = invoice_number
        invoice_date = data.get("date") or None
        supplier_name = (data.get("supplierName") or "").strip()
        supplier_lookup_payload = {
            **(data or {}),
            "supplierName": supplier_name or data.get("supplier") or "",
            "supplier": data.get("supplier") or supplier_name,
        }
        matched_supplier = _supplier_find_match(
            cur,
            supplier_lookup_payload,
            allow_alias_name_match=not has_legal_supplier_identity(supplier_lookup_payload),
            allow_contact_match=False,
        )
        if matched_supplier:
            data["supplierId"] = matched_supplier["id"]
            data["supplierName"] = matched_supplier["name"] or supplier_name
            supplier_name = data["supplierName"]
            _update_supplier_missing_fields(cur, matched_supplier["id"], supplier_lookup_payload)
            _remember_supplier_alias(cur, matched_supplier["id"], supplier_lookup_payload, source="warehouse_invoice")
        if invoice_number:
            cur.execute("""SELECT id FROM warehouse_invoices
                           WHERE COALESCE(status,'Принята') <> 'Аннулирована'
                             AND COALESCE(company_id,1)=%s
                             AND number=%s
                             AND COALESCE(date::text,'')=COALESCE(%s::text,'')
                             AND COALESCE(supplier_name,'')=%s
                             AND COALESCE(location,'')=%s
                           LIMIT 1""",
                        (company_id, invoice_number, invoice_date, supplier_name, target_location))
            duplicate = cur.fetchone()
            if duplicate:
                raise HTTPException(
                    status_code=409,
                    detail="Эта накладная уже есть в базе. Повторная загрузка отменена. Если в документе есть исправление, сначала аннулируйте старую накладную.",
                )
        items_list = data.get("items", []) or []
        if not isinstance(items_list, list):
            items_list = []
        normalized_invoice_items = []
        for raw_item in items_list:
            if not isinstance(raw_item, dict):
                continue
            item = dict(raw_item)
            item["workPackage"] = _supply_work_package(item.get("workPackage") or item.get("work_package") or data.get("workPackage") or data.get("work_package"))
            if target_project:
                item = _apply_material_alias_to_invoice_item(cur, target_project, item)
            normalized_invoice_items.append(item)
        items_list = normalized_invoice_items
        try:
            from backend.features.material_packaging import normalize_invoice_packaging_items
        except ModuleNotFoundError:
            from features.material_packaging import normalize_invoice_packaging_items
        try:
            from backend.features.material_traceability.receipt_lots import (
                create_receipt_lot,
                ensure_receipt_lot_schema,
            )
        except ModuleNotFoundError:
            from features.material_traceability.receipt_lots import (
                create_receipt_lot,
                ensure_receipt_lot_schema,
            )
        items_list = normalize_invoice_packaging_items(
            cur,
            items_list,
            company_id=company_id,
            supplier_id=data.get("supplierId") or data.get("supplier_id"),
        )
        if target_project:
            items_list = _attach_supply_estimate_control(
                cur,
                target_project,
                items_list,
                company_id=company_id,
            )
            items_list = _canonicalize_invoice_items_from_estimate_control(items_list)
            manual_project_invoice_override = (
                target_project
                and source_type.endswith("_project_invoice")
                and current_user.get("role") in PROJECT_WAREHOUSE_INVOICE_OVERRIDE_ROLES
            )
            _enforce_supply_estimate_control(
                items_list,
                source="накладная",
                allow_manual_project_override=manual_project_invoice_override,
                override_by=current_user.get("name") or current_user.get("email") or "",
            )
        photo_urls = data.get("photos") or data.get("photoUrls") or []
        if isinstance(photo_urls, str):
            try:
                photo_urls = j.loads(photo_urls)
            except Exception:
                photo_urls = [x.strip() for x in photo_urls.split(",") if x.strip()]
        if not isinstance(photo_urls, list):
            photo_urls = []
        photo_urls = [str(x).strip() for x in photo_urls if str(x or "").strip()]
        first_photo_url = (data.get("photoUrl") or (photo_urls[0] if photo_urls else "") or "").strip()
        if first_photo_url and first_photo_url not in photo_urls:
            photo_urls.insert(0, first_photo_url)
        pages_count = int(data.get("pagesCount") or data.get("pages_count") or len(photo_urls) or 1)
        warehouse_target = str(data.get("warehouseTarget") or data.get("warehouse_target") or ("object" if target_project else "main")).strip()
        warehouse_target = warehouse_target if warehouse_target in {"main", "object"} else ("object" if target_project else "main")
        selected_action = receipt_policy.get("selectedAction") or "receive_to_warehouse"
        material_match = data.get("materialMatch") or data.get("material_match") or []
        if isinstance(material_match, str):
            try:
                material_match = j.loads(material_match)
            except Exception:
                material_match = []
        if not isinstance(material_match, list):
            material_match = []
        normalized_invoice = _normalize_invoice_totals_payload({**data, "items": items_list})
        items_list = normalized_invoice.get("items") or items_list
        invoice_vat = normalized_invoice.get("vat") or data.get("vat") or "Без НДС"
        total_base = normalized_invoice.get("totalBase", 0)
        total_vat = normalized_invoice.get("totalVat", 0)
        total_with_vat = normalized_invoice.get("totalWithVat", 0)
        invoice_items_signature = _warehouse_invoice_items_signature(items_list)
        for duplicate_lock_key in build_warehouse_invoice_lock_keys(
            company_id=company_id,
            invoice_number=invoice_number,
            invoice_date=invoice_date,
            total_with_vat=total_with_vat,
            items_signature=invoice_items_signature,
        ):
            cur.execute(
                "SELECT pg_advisory_xact_lock(hashtext(%s))",
                (duplicate_lock_key,),
            )
        broad_duplicate = _find_existing_warehouse_invoice_duplicate(
            cur,
            company_id=company_id,
            invoice_number=invoice_number,
            invoice_date=invoice_date,
            supplier_id=data.get("supplierId") or data.get("supplier_id"),
            supplier_name=data.get("supplierName") or supplier_name,
            total_with_vat=total_with_vat,
            items=items_list,
        )
        if broad_duplicate:
            duplicate_supplier = (broad_duplicate.get("supplierName") or "поставщик не указан").strip()
            raise HTTPException(
                status_code=409,
                detail=(
                    "Эта накладная уже есть в базе, поэтому повторная загрузка отменена: "
                    + "№" + str(invoice_number)
                    + (" от " + str(invoice_date) if invoice_date else "")
                    + (" · " + duplicate_supplier if duplicate_supplier else "")
                    + ". Если в документе есть исправление, сначала аннулируйте старую накладную."
                ),
            )
        cur.execute("""INSERT INTO warehouse_invoices
                       (company_id,number,date,supplier_id,supplier_name,accepted_by,location,project,vat,items,
                        total_base,total_vat,total_with_vat,status,added_by,photo_url,
                        source_type,source_id,supply_delivery_id,supply_request_id,photo_urls,pages_count,
                        warehouse_target,selected_action,material_match_json,supplier_invoice_id)
                       VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                       RETURNING id""",
            (company_id,data.get("number",""),data.get("date") or None,data.get("supplierId") or None,data.get("supplierName",""),data.get("acceptedBy",""),target_location,target_project,invoice_vat,j.dumps(items_list,ensure_ascii=False),total_base,total_vat,total_with_vat,data.get("status","Принята"),data.get("addedBy",""),first_photo_url,source_type,source_id,supply_delivery_id,supply_request_id,j.dumps(photo_urls,ensure_ascii=False),pages_count,warehouse_target,selected_action,j.dumps(material_match,ensure_ascii=False),supplier_invoice_id))
        invoice_id = cur.fetchone()[0]
        # A few long-lived database schemas have an INSERT-side normalizer. Verify
        # that it did not drop the source lines before stock/history derives from them.
        if items_list:
            cur.execute("SELECT items FROM warehouse_invoices WHERE id=%s FOR UPDATE", (invoice_id,))
            stored_invoice_items = _json_list_or_empty(_row_get(cur.fetchone(), "items", 0, ""))
            if not stored_invoice_items:
                cur.execute(
                    "UPDATE warehouse_invoices SET items=%s WHERE id=%s",
                    (j.dumps(items_list, ensure_ascii=False), invoice_id),
                )
                cur.execute("SELECT items FROM warehouse_invoices WHERE id=%s", (invoice_id,))
                stored_invoice_items = _json_list_or_empty(_row_get(cur.fetchone(), "items", 0, ""))
                if not stored_invoice_items:
                    raise HTTPException(
                        status_code=500,
                        detail="Не удалось сохранить строки накладной; приход отменён до изменения остатков",
                    )
        ensure_receipt_lot_schema(cur)
        project_id = None
        if target_project:
            cur.execute("SELECT id FROM projects WHERE name=%s AND company_id=%s ORDER BY id LIMIT 1", (target_project, company_id))
            project_row = cur.fetchone()
            project_id = _positive_int_or_none(_row_get(project_row, "id", 0))
        if supplier_invoice_id:
            cur.execute("UPDATE supplier_invoices SET company_id=%s, warehouse_invoice_id=%s WHERE id=%s", (company_id, invoice_id, supplier_invoice_id))

        sup = data.get("supplierName","")
        rcv_date = data.get("date") or None
        accepted_by = data.get("acceptedBy") or data.get("addedBy") or current_user.get("name","")
        date_time = dt.datetime.now().strftime("%d.%m.%Y, %H:%M")
        inspections_added = 0
        cables_added = 0
        stock_rows_added = 0
        history_added = 0
        lot_rows_added = 0
        restricted_packages = user_package_names(current_user) if current_user.get("role") in PACKAGE_LIMIT_ROLES else []

        for item_index, it in enumerate(items_list):
            name = (it.get("name") or "").strip()
            qty = _invoice_float(it.get("quantity"), 0)
            if not name or qty <= 0:
                continue
            unit = _norm_base_unit(it.get("unit") or "шт") or "шт"
            it["unit"] = unit
            price = _invoice_float(it.get("price"), 0)
            category = (it.get("category") or "").strip()
            work_package = _supply_work_package(it.get("workPackage") or it.get("work_package") or data.get("workPackage") or data.get("work_package"))
            it["workPackage"] = work_package
            if restricted_packages and work_package not in restricted_packages:
                raise HTTPException(status_code=403, detail="Нет доступа к разделу сметы накладной: " + work_package)

            if target_project:
                cur.execute(f"""SELECT id FROM materials
                               WHERE LOWER(name)=LOWER(%s)
                                 AND project=%s
                                 AND company_id=%s
                                 AND COALESCE(NULLIF(work_package,''),'Основная')=%s
                                 AND {_sql_norm_unit('unit')}=%s
                               ORDER BY id LIMIT 1 FOR UPDATE""",
                            (name, target_project, company_id, work_package, unit))
                row = cur.fetchone()
                if row:
                    cur.execute("""UPDATE materials
                                   SET quantity=COALESCE(quantity,0)+%s,
                                       unit=COALESCE(NULLIF(%s,''), unit),
                                       price=CASE WHEN %s > 0 THEN %s ELSE price END,
                                       category=COALESCE(NULLIF(%s,''), category)
                                   WHERE id=%s""",
                                (qty, unit, price, price, category, row[0]))
                else:
                    cur.execute("""INSERT INTO materials
                                      (name,unit,quantity,price,min_quantity,project,category,work_package,company_id)
                                   VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                                (name, unit, qty, price, 0, target_project, category, work_package, company_id))
                history_project = target_project
            else:
                cur.execute(f"""SELECT id FROM warehouse_main
                               WHERE LOWER(name)=LOWER(%s)
                                 AND company_id=%s
                                 AND {_sql_norm_unit('unit')}=%s
                               ORDER BY id LIMIT 1 FOR UPDATE""", (name, company_id, unit))
                row = cur.fetchone()
                if row:
                    cur.execute("""UPDATE warehouse_main
                                   SET quantity=COALESCE(quantity,0)+%s,
                                       unit=COALESCE(NULLIF(%s,''), unit),
                                       price=CASE WHEN %s > 0 THEN %s ELSE price END,
                                       category=COALESCE(NULLIF(%s,''), category)
                                   WHERE id=%s""",
                                (qty, unit, price, price, category, row[0]))
                else:
                    cur.execute("""INSERT INTO warehouse_main
                                      (name,unit,quantity,price,min_quantity,category,company_id)
                                   VALUES (%s,%s,%s,%s,%s,%s,%s)""",
                                (name, unit, qty, price, 0, category, company_id))
                history_project = "Основной склад"

            stock_rows_added += 1
            cur.execute("""INSERT INTO warehouse_history
                              (company_id,material,type,quantity,unit,date,project,issued_by,work_package,date_time,
                               source_type,source_id,source_invoice_id,source_invoice_line_index)
                           VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                        (company_id, name, "приход", qty, unit, rcv_date, history_project, accepted_by, work_package, date_time,
                         source_type or "warehouse_invoice", invoice_id, invoice_id, item_index))
            history_added += 1
            if create_receipt_lot(
                cur,
                company_id=company_id,
                project_id=project_id,
                project_name=target_project,
                warehouse_location=history_project,
                warehouse_target=warehouse_target,
                warehouse_invoice_id=invoice_id,
                invoice_line_index=item_index,
                material_name=name,
                document_quantity=it.get("documentQuantity", qty),
                document_unit=it.get("documentUnit") or unit,
                received_quantity=qty,
                unit=unit,
                created_by=accepted_by,
            ):
                lot_rows_added += 1

            if target_project:
                source_item_key = _journal_item_key(name, unit, qty, work_package, item_index)
                if _ensure_material_inspection_row(
                    cur,
                    project=target_project,
                    material_name=name,
                    qty=qty,
                    unit=unit,
                    supplier=sup,
                    received_at=rcv_date,
                    invoice_id=invoice_id,
                    work_package=work_package,
                    source_type=source_type or "warehouse_invoice",
                    source_id=invoice_id,
                    source_item_key=source_item_key,
                ):
                    inspections_added += 1
                if _ensure_cable_journal_row(
                    cur,
                    project=target_project,
                    cable_brand=name,
                    qty=qty,
                    supplier=sup,
                    received_at=rcv_date,
                    invoice_id=invoice_id,
                    work_package=work_package,
                    source_type=source_type or "warehouse_invoice",
                    source_id=invoice_id,
                    source_item_key=source_item_key,
                ):
                    cables_added += 1

        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        cur.close(); conn.close()
    _run_project_ai_control_safely(target_project, "warehouse_invoice:create")
    result = {
        "id": invoice_id,
        "ok": True,
        "number": invoice_number,
        "inventoryOnly": inventory_only,
        "accountingRequired": accounting_required,
        "stockRowsAdded": stock_rows_added,
        "historyAdded": history_added,
        "receiptLotsAdded": lot_rows_added,
        "inspectionsAdded": inspections_added,
        "cablesAdded": cables_added,
    }
    if accounting_required and (data or {}).get("syncSupplierInvoice") is not False and (data or {}).get("sync_supplier_invoice") is not False:
        try:
            accounting_link = _sync_supplier_invoice_from_warehouse(invoice_id, data, current_user)
            result["supplierInvoiceId"] = accounting_link.get("id")
            result["accountingStatus"] = accounting_link.get("accountingStatus") or "На проверке"
            result["supplierId"] = accounting_link.get("supplierId")
            result["supplierName"] = accounting_link.get("supplierName")
        except Exception as exc:
            result["accountingWarning"] = getattr(exc, "detail", str(exc)) or "Не удалось связать бухгалтерскую первичку"
    return result

def _sync_supplier_invoice_from_warehouse(warehouse_invoice_id: int, payload: dict = None, actor: dict = None):
    payload = payload or {}
    actor = actor or {}
    review_uncertain_supplier_match = bool(
        payload.get("reviewUncertainSupplierMatch")
        or payload.get("review_uncertain_supplier_match")
        or payload.get("backfillReview")
        or payload.get("backfill_review")
    )
    conn = get_db()
    conn.autocommit = False
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    try:
        _ensure_warehouse_invoice_accounting_columns(cur)
        _ensure_invoice_document_link_columns(cur)
        cur.execute(
            """
            SELECT id,number,date,supplier_id,supplier_name,location,project,items,
                   total_base,total_vat,total_with_vat,photo_url,photo_urls,
                   supplier_invoice_id,source_type,company_id
              FROM warehouse_invoices
             WHERE id=%s AND COALESCE(status,'Принята') <> 'Аннулирована'
             FOR UPDATE
            """,
            (warehouse_invoice_id,),
        )
        warehouse_invoice = cur.fetchone()
        if not warehouse_invoice:
            raise HTTPException(status_code=404, detail="Складская накладная для бухгалтерии не найдена")
        existing_supplier_invoice_id = warehouse_invoice.get("supplier_invoice_id")
        if existing_supplier_invoice_id and warehouse_invoice_accounting_required(warehouse_invoice):
            conn.commit()
            return {"id": existing_supplier_invoice_id, "ok": True, "alreadyExists": True}
        if not warehouse_invoice_accounting_required(warehouse_invoice):
            raise HTTPException(
                status_code=409,
                detail="Приход на основной склад без поставщика не создаёт первичку и задолженность",
            )

        items = _json_list_or_empty(warehouse_invoice.get("items"))
        first_item = items[0] if items and isinstance(items[0], dict) else {}
        project_name = (
            warehouse_invoice.get("project")
            or (warehouse_invoice.get("location") if warehouse_invoice.get("location") != "Основной склад" else "")
            or ""
        )
        company_id = (
            _positive_int_or_none(payload.get("companyId") or payload.get("company_id"))
            or _positive_int_or_none(warehouse_invoice.get("company_id"))
            or _company_id_for_project_or_user(cur, project_name, actor)
        )
        supplier_name = (
            payload.get("supplierName")
            or payload.get("supplier")
            or warehouse_invoice.get("supplier_name")
            or ""
        ).strip()
        supplier_payload = {
            **payload,
            "supplierName": supplier_name,
            "supplier": payload.get("supplier") or supplier_name,
            "sourceType": "max_invoice" if str(warehouse_invoice.get("source_type") or "").startswith("max_") else "warehouse_invoice",
            "sourceDetail": "Создано/обновлено из складской накладной #" + str(warehouse_invoice_id),
        }
        if warehouse_invoice.get("supplier_id") and not (supplier_payload.get("supplierId") or supplier_payload.get("supplier_id")):
            supplier_payload["supplierId"] = warehouse_invoice.get("supplier_id")

        supplier_id = warehouse_invoice.get("supplier_id")
        legal_supplier_identity = has_legal_supplier_identity(supplier_payload)
        if legal_supplier_identity and not supplier_id:
            identity_requisites = _supplier_extract_requisites(supplier_payload)
            identity_key = (
                "inn:" + identity_requisites["inn"]
                if identity_requisites["inn"]
                else "ogrn:" + identity_requisites["ogrn"]
            )
            cur.execute("SELECT pg_advisory_xact_lock(hashtext(%s))", ("supplier:" + identity_key,))
        matched_supplier = _supplier_find_match(
            cur,
            supplier_payload,
            allow_alias_name_match=not legal_supplier_identity,
            allow_contact_match=False,
        )
        created_supplier = False
        if matched_supplier:
            supplier_id = matched_supplier["id"]
            supplier_name = matched_supplier["name"] or supplier_name
            _update_supplier_missing_fields(cur, supplier_id, supplier_payload)
            _remember_supplier_alias(cur, supplier_id, supplier_payload, source="warehouse_accounting")
        elif supplier_name:
            req = _supplier_extract_requisites(supplier_payload)
            if legal_supplier_identity:
                cur.execute(
                    """
                    INSERT INTO suppliers
                        (name,phone,email,specialization,category,rating,status,
                         inn,kpp,ogrn,notes,source_type,source_detail)
                    VALUES (%s,'','','','Материалы',5.0,'На проверке',%s,%s,%s,%s,%s,%s)
                    RETURNING id,name
                    """,
                    (
                        supplier_name,
                        req.get("inn") or "",
                        req.get("kpp") or "",
                        req.get("ogrn") or "",
                        "Создано из складской накладной #" + str(warehouse_invoice_id),
                        supplier_payload["sourceType"],
                        supplier_payload["sourceDetail"],
                    ),
                )
                supplier_row = cur.fetchone()
                supplier_id = supplier_row.get("id")
                supplier_name = supplier_row.get("name") or supplier_name
                created_supplier = True
                _remember_supplier_alias(cur, supplier_id, supplier_payload, source="warehouse_accounting")

        review_state = {"needsReview": False, "reviewReason": "", "accountingStatus": "На проверке", "supplierInvoiceStatus": "На утверждении"}
        if review_uncertain_supplier_match or (supplier_name and not supplier_id):
            review_state = _supplier_backfill_review_state(
                cur,
                warehouse_invoice,
                supplier_payload,
                supplier_id=supplier_id,
                matched_supplier=matched_supplier,
                created_supplier=created_supplier,
            )
        supplier_invoice_status = review_state.get("supplierInvoiceStatus") or "На утверждении"
        accounting_status = review_state.get("accountingStatus") or "На проверке"
        accounting_comment = (
            "Нужно уточнение: " + review_state.get("reviewReason")
            if review_state.get("needsReview") and review_state.get("reviewReason")
            else "Первичка создана автоматически из складской накладной. Проверить реквизиты, сумму и фото перед оплатой."
        )

        invoice_number = str(payload.get("invoiceNumber") or payload.get("number") or warehouse_invoice.get("number") or "").strip()
        invoice_date = payload.get("invoiceDate") or payload.get("date") or warehouse_invoice.get("date") or None
        amount = _float_or_zero(payload.get("amount") or payload.get("totalWithVat") or warehouse_invoice.get("total_with_vat") or warehouse_invoice.get("total_base"))
        vat_amount = _float_or_zero(payload.get("vatAmount") or payload.get("totalVat") or warehouse_invoice.get("total_vat"))
        work_package = (
            payload.get("workPackage")
            or payload.get("work_package")
            or first_item.get("workPackage")
            or first_item.get("work_package")
            or ""
        )
        material_name = payload.get("materialName") or first_item.get("name") or ""
        photo_urls = _json_list_or_empty(warehouse_invoice.get("photo_urls"))
        photo_url = payload.get("photoUrl") or warehouse_invoice.get("photo_url") or (photo_urls[0] if photo_urls else "")
        file_url = payload.get("fileUrl") or payload.get("file_url") or ""
        description = payload.get("description") or (
            "Первичка по складской накладной #" + str(warehouse_invoice_id)
            + (" из MAX" if str(warehouse_invoice.get("source_type") or "").startswith("max_") else "")
        )

        duplicate_invoice = _find_existing_supplier_invoice_duplicate(
            cur,
            company_id=company_id,
            invoice_number=invoice_number,
            invoice_date=invoice_date,
            project_name=project_name,
            supplier_id=supplier_id,
            supplier_name=supplier_name,
            amount=amount,
            warehouse_invoice_id=warehouse_invoice_id,
        )
        if duplicate_invoice:
            supplier_invoice_id = duplicate_invoice.get("id")
            linked_warehouse_id = _positive_int_or_none(duplicate_invoice.get("warehouseInvoiceId"))
            if not linked_warehouse_id:
                cur.execute(
                    """
                    UPDATE supplier_invoices
                       SET company_id=%s,
                           warehouse_invoice_id=%s,
                           supplier_id=COALESCE(supplier_id,%s),
                           supplier_name=COALESCE(NULLIF(supplier_name,''),%s),
                           status=CASE WHEN %s THEN %s ELSE status END
                     WHERE id=%s
                    """,
                    (company_id, warehouse_invoice_id, supplier_id, supplier_name, bool(review_state.get("needsReview")), supplier_invoice_status, supplier_invoice_id),
                )
            else:
                cur.execute(
                    """
                    UPDATE supplier_invoices
                       SET company_id=%s,
                           supplier_id=COALESCE(supplier_id,%s),
                           supplier_name=COALESCE(NULLIF(supplier_name,''),%s),
                           status=CASE WHEN %s THEN %s ELSE status END
                     WHERE id=%s
                    """,
                    (company_id, supplier_id, supplier_name, bool(review_state.get("needsReview")), supplier_invoice_status, supplier_invoice_id),
                )
            actor_name = actor.get("name") or actor.get("email") or "MAX"
            cur.execute(
                """
                UPDATE warehouse_invoices
                   SET company_id=%s,
                       supplier_invoice_id=%s,
                       supplier_id=COALESCE(supplier_id,%s),
                       supplier_name=COALESCE(NULLIF(supplier_name,''),%s),
                       accounting_status=CASE WHEN %s THEN %s ELSE COALESCE(NULLIF(accounting_status,''),'На проверке') END,
                       accounting_comment=COALESCE(NULLIF(accounting_comment,''),'Первичка связана с уже существующим счетом поставщика без создания дубля.'),
                       accounting_updated_by=%s,
                       accounting_updated_at=NOW()
                 WHERE id=%s
                """,
                (
                    company_id,
                    supplier_invoice_id,
                    supplier_id,
                    supplier_name,
                    bool(review_state.get("needsReview")),
                    accounting_status,
                    actor_name,
                    warehouse_invoice_id,
                ),
            )
            conn.commit()
            return {
                "id": supplier_invoice_id,
                "ok": True,
                "alreadyExists": True,
                "duplicateDocument": True,
                "supplierId": supplier_id,
                "supplierName": supplier_name,
                "warehouseInvoiceId": warehouse_invoice_id,
                "accountingStatus": accounting_status,
                "needsReview": bool(review_state.get("needsReview")),
                "reviewReason": review_state.get("reviewReason") or "",
            }

        supplier_invoice_id = None
        if invoice_number and (supplier_id or supplier_name):
            supplier_match_sql = []
            supplier_match_params = []
            if supplier_id:
                supplier_match_sql.append("supplier_id=%s")
                supplier_match_params.append(supplier_id)
            if supplier_name:
                supplier_match_sql.append("COALESCE(supplier_name,'')=%s")
                supplier_match_params.append(supplier_name)
            cur.execute(
                f"""
                SELECT id, warehouse_invoice_id
                  FROM supplier_invoices
                 WHERE COALESCE(status,'') <> 'Аннулирован'
                   AND COALESCE(company_id,1)=%s
                   AND COALESCE(invoice_number,'')=%s
                   AND COALESCE(invoice_date::text,'')=COALESCE(%s::text,'')
                   AND COALESCE(project_name,'')=%s
                   AND ({" OR ".join(supplier_match_sql)})
                 ORDER BY id DESC
                 LIMIT 1
                """,
                (company_id, invoice_number, invoice_date, project_name, *supplier_match_params),
            )
            existing = cur.fetchone()
            if existing:
                linked_warehouse_id = existing.get("warehouse_invoice_id")
                if linked_warehouse_id and int(linked_warehouse_id) != int(warehouse_invoice_id):
                    raise HTTPException(status_code=409, detail="Счет поставщика уже связан с другой складской накладной")
                supplier_invoice_id = existing.get("id")

        if supplier_invoice_id:
            cur.execute(
                """
                UPDATE supplier_invoices
                   SET company_id=%s,
                       warehouse_invoice_id=%s,
                       status=CASE WHEN %s THEN %s ELSE status END
                 WHERE id=%s
                """,
                (company_id, warehouse_invoice_id, bool(review_state.get("needsReview")), supplier_invoice_status, supplier_invoice_id),
            )
        else:
            cur.execute(
                """
                INSERT INTO supplier_invoices
                    (company_id,supplier_id,supplier_name,project_name,invoice_number,invoice_date,
                     amount,vat_amount,description,file_url,photo_url,status,
                     offer_id,request_id,payment_terms,material_name,work_package,warehouse_invoice_id)
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                        NULL,NULL,%s,%s,%s,%s)
                RETURNING id
                """,
                (
                    company_id,
                    supplier_id,
                    supplier_name,
                    project_name,
                    invoice_number,
                    invoice_date or None,
                    amount,
                    vat_amount,
                    description,
                    file_url,
                    photo_url,
                    supplier_invoice_status,
                    payload.get("paymentTerms") or payload.get("payment_terms") or "",
                    material_name,
                    work_package,
                    warehouse_invoice_id,
                ),
            )
            supplier_invoice_id = cur.fetchone().get("id")

        actor_name = actor.get("name") or actor.get("email") or "MAX"
        cur.execute(
            """
            UPDATE warehouse_invoices
               SET company_id=%s,
                   supplier_invoice_id=%s,
                   supplier_id=COALESCE(supplier_id,%s),
                   supplier_name=COALESCE(NULLIF(supplier_name,''),%s),
                   accounting_status=CASE WHEN %s THEN %s ELSE COALESCE(NULLIF(accounting_status,''),'На проверке') END,
                   accounting_comment=COALESCE(NULLIF(accounting_comment,''),%s),
                   accounting_updated_by=%s,
                   accounting_updated_at=NOW()
             WHERE id=%s
            """,
            (
                company_id,
                supplier_invoice_id,
                supplier_id,
                supplier_name,
                bool(review_state.get("needsReview")),
                accounting_status,
                accounting_comment,
                actor_name,
                warehouse_invoice_id,
            ),
        )
        conn.commit()
        return {
            "id": supplier_invoice_id,
            "ok": True,
            "supplierId": supplier_id,
            "supplierName": supplier_name,
            "warehouseInvoiceId": warehouse_invoice_id,
            "accountingStatus": accounting_status,
            "needsReview": bool(review_state.get("needsReview")),
            "reviewReason": review_state.get("reviewReason") or "",
        }
    except Exception:
        conn.rollback()
        raise
    finally:
        cur.close()
        conn.close()

@app.post("/warehouse-invoices")
def create_warehouse_invoice(
    data: dict,
    x_company_id: Optional[str] = Header(default=None, alias="X-Company-Id"),
    x_company_mode: Optional[str] = Header(default=None, alias="X-Company-Mode"),
    _current_user: dict = Depends(get_current_user),
):
    return _create_warehouse_invoice_record(
        data,
        _current_user,
        x_company_id=x_company_id,
        x_company_mode=x_company_mode,
    )

@app.post("/supplier-documents/backfill")
def backfill_supplier_documents(data: dict = None, _current_user: dict = Depends(require_roles(*FINANCE_ROLES))):
    """Сверяет старые складские накладные с первичкой поставщиков без повторного склада/оплат."""
    data = data or {}
    apply_changes = bool(data.get("apply") or data.get("commit"))
    target_ids = []
    raw_ids = data.get("warehouseInvoiceIds") or data.get("warehouse_invoice_ids") or []
    if not isinstance(raw_ids, list):
        raw_ids = [raw_ids]
    raw_single_id = data.get("warehouseInvoiceId") or data.get("warehouse_invoice_id")
    if raw_single_id:
        raw_ids.append(raw_single_id)
    for raw_id in raw_ids:
        value = _positive_int_or_none(raw_id)
        if value and value not in target_ids:
            target_ids.append(value)
    try:
        limit = int(data.get("limit") or 200)
    except Exception:
        limit = 200
    limit = max(1, min(limit, 500))
    conn = get_db()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    _ensure_invoice_document_link_columns(cur)
    _ensure_warehouse_invoice_accounting_columns(cur)
    conn.commit()
    where = [
        "COALESCE(status,'Принята') <> 'Аннулирована'",
        "supplier_invoice_id IS NULL",
        "(supplier_id IS NOT NULL OR COALESCE(supplier_name,'') <> '')",
    ]
    params = []
    if target_ids:
        where.append("id = ANY(%s)")
        params.append(target_ids)
        limit = min(limit, max(len(target_ids), 1))
    params.append(limit)
    cur.execute(
        f"""
        SELECT id, number, date, supplier_id, supplier_name, location, project,
               total_with_vat, total_base, supplier_invoice_id
          FROM warehouse_invoices
         WHERE {" AND ".join(where)}
         ORDER BY id
         LIMIT %s
        """,
        tuple(params),
    )
    candidates = [dict(r) for r in cur.fetchall()]
    cur.close()
    conn.close()

    checked = []
    linked = 0
    errors = []
    for row in candidates:
        item = {
            "warehouseInvoiceId": row.get("id"),
            "number": row.get("number") or "",
            "date": str(row.get("date")) if row.get("date") else "",
            "supplierId": row.get("supplier_id"),
            "supplierName": row.get("supplier_name") or "",
            "projectName": row.get("project") or row.get("location") or "",
            "amount": float(row.get("total_with_vat") or row.get("total_base") or 0),
            "action": "preview" if not apply_changes else "sync",
        }
        preview_review = _supplier_backfill_preview_review_state(row)
        item.update({
            "needsReview": preview_review.get("needsReview"),
            "reviewReason": preview_review.get("reviewReason") or "",
            "accountingStatus": preview_review.get("accountingStatus") or "На проверке",
        })
        if not apply_changes:
            checked.append(item)
            continue
        try:
            result = _sync_supplier_invoice_from_warehouse(
                row.get("id"),
                {"reviewUncertainSupplierMatch": True},
                _current_user,
            )
            item.update({
                "supplierInvoiceId": result.get("id"),
                "supplierId": result.get("supplierId"),
                "supplierName": result.get("supplierName") or item["supplierName"],
                "accountingStatus": result.get("accountingStatus") or "На проверке",
                "needsReview": bool(result.get("needsReview")),
                "reviewReason": result.get("reviewReason") or "",
                "ok": True,
            })
            linked += 1
        except Exception as exc:
            item["ok"] = False
            item["error"] = getattr(exc, "detail", str(exc)) or "Не удалось связать документ"
            errors.append(item)
        checked.append(item)
    return {
        "ok": True,
        "dryRun": not apply_changes,
        "checked": len(checked),
        "linked": linked,
        "errors": errors,
        "items": checked,
    }

@app.post("/supplier-documents/dedupe")
def dedupe_supplier_accounting_documents(data: dict = None, _current_user: dict = Depends(require_roles(*FINANCE_ROLES))):
    """Находит и безопасно схлопывает старые дубли бухгалтерской первички без удаления склада/оплат."""
    data = data or {}
    apply_changes = bool(data.get("apply") or data.get("commit"))
    force_review = bool(data.get("force") or data.get("forceReview"))
    project_filter = str(data.get("projectName") or data.get("project_name") or "").strip()
    raw_ids = data.get("supplierInvoiceIds") or data.get("supplier_invoice_ids") or []
    if not isinstance(raw_ids, list):
        raw_ids = [raw_ids]
    raw_single_id = data.get("supplierInvoiceId") or data.get("supplier_invoice_id")
    if raw_single_id:
        raw_ids.append(raw_single_id)
    target_ids = []
    for raw_id in raw_ids:
        value = _positive_int_or_none(raw_id)
        if value and value not in target_ids:
            target_ids.append(value)
    try:
        limit = int(data.get("limit") or 50)
    except Exception:
        limit = 50
    limit = max(1, min(limit, 200))

    conn = get_db()
    conn.autocommit = False
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    try:
        _ensure_invoice_document_link_columns(cur)
        _ensure_warehouse_invoice_accounting_columns(cur)
        where = [
            "COALESCE(status,'') <> 'Аннулирован'",
            "COALESCE(invoice_number,'') <> ''",
        ]
        params = []
        if project_filter:
            require_project_access(_current_user, project_filter)
            where.append("COALESCE(project_name,'')=%s")
            params.append(project_filter)
        if target_ids:
            seed_where = where + ["id = ANY(%s)"]
            seed_params = params + [target_ids]
            cur.execute(
                f"""
                SELECT DISTINCT COALESCE(company_id,1) AS company_id,
                       COALESCE(invoice_number,'') AS invoice_number,
                       COALESCE(invoice_date::text,'') AS invoice_date_key,
                       COALESCE(project_name,'') AS project_name,
                       ROUND(COALESCE(amount,0)::numeric, 2) AS amount_key,
                       COUNT(*) OVER () AS total_count,
                       MAX(id) OVER () AS latest_id
                  FROM supplier_invoices
                 WHERE {" AND ".join(seed_where)}
                 ORDER BY latest_id DESC
                 LIMIT %s
                """,
                tuple(seed_params + [limit]),
            )
        else:
            cur.execute(
                f"""
                SELECT COALESCE(company_id,1) AS company_id,
                       COALESCE(invoice_number,'') AS invoice_number,
                       COALESCE(invoice_date::text,'') AS invoice_date_key,
                       COALESCE(project_name,'') AS project_name,
                       ROUND(COALESCE(amount,0)::numeric, 2) AS amount_key,
                       COUNT(*) AS total_count,
                       MAX(id) AS latest_id
                  FROM supplier_invoices
                 WHERE {" AND ".join(where)}
                 GROUP BY COALESCE(company_id,1), COALESCE(invoice_number,''),
                          COALESCE(invoice_date::text,''), COALESCE(project_name,''),
                          ROUND(COALESCE(amount,0)::numeric, 2)
                HAVING COUNT(*) > 1
                 ORDER BY MAX(id) DESC
                 LIMIT %s
                """,
                tuple(params + [limit]),
            )
        keys = [dict(row) for row in cur.fetchall() or []]
        groups = []
        applied_groups = 0
        annulled_rows = 0
        linked_warehouse_rows = 0
        for key in keys:
            project_name = key.get("project_name") or ""
            if project_name:
                require_project_access(_current_user, project_name)
            cur.execute(
                """
                SELECT id, company_id, supplier_id, supplier_name, project_name,
                       invoice_number, invoice_date, amount, paid_amount, status,
                       warehouse_invoice_id, offer_id, request_id, file_url, photo_url,
                       payment_terms, material_name, work_package, description, paid_note
                  FROM supplier_invoices
                 WHERE COALESCE(status,'') <> 'Аннулирован'
                   AND COALESCE(company_id,1)=%s
                   AND COALESCE(invoice_number,'')=%s
                   AND COALESCE(invoice_date::text,'')=%s
                   AND COALESCE(project_name,'')=%s
                   AND ROUND(COALESCE(amount,0)::numeric, 2)=%s
                 ORDER BY id
                """,
                (
                    key.get("company_id") or 1,
                    key.get("invoice_number") or "",
                    key.get("invoice_date_key") or "",
                    project_name,
                    key.get("amount_key") or 0,
                ),
            )
            rows = [dict(row) for row in cur.fetchall() or []]
            if len(rows) < 2:
                continue
            canonical = _pick_supplier_invoice_canonical(rows)
            safety = _supplier_invoice_duplicate_group_safety(cur, rows)
            needs_manual_review = not bool(safety.get("safe"))
            canonical_id = canonical.get("id") if canonical else None
            duplicate_rows = [row for row in rows if int(row.get("id") or 0) != int(canonical_id or 0)]
            group = {
                "companyId": key.get("company_id") or 1,
                "invoiceNumber": key.get("invoice_number") or "",
                "invoiceDate": key.get("invoice_date_key") or "",
                "projectName": project_name,
                "amount": _float_or_zero(key.get("amount_key")),
                "canonicalId": canonical_id,
                "duplicateIds": [row.get("id") for row in duplicate_rows],
                "needsManualReview": needs_manual_review,
                "reviewReason": safety.get("reason") or "",
                "applied": False,
                "rows": [_supplier_invoice_duplicate_summary(row) for row in rows],
            }
            if apply_changes and canonical_id and (safety.get("safe") or force_review):
                canonical_warehouse_id = _positive_int_or_none(canonical.get("warehouse_invoice_id"))
                actor_note = "Схлопнуто как дубль бухгалтерской первички в счет #" + str(canonical_id)
                for duplicate in duplicate_rows:
                    duplicate_id = int(duplicate.get("id") or 0)
                    if not duplicate_id:
                        continue
                    duplicate_warehouse_id = _positive_int_or_none(duplicate.get("warehouse_invoice_id"))
                    cur.execute(
                        """
                        UPDATE supplier_invoices
                           SET supplier_id=COALESCE(supplier_id,%s),
                               supplier_name=COALESCE(NULLIF(supplier_name,''),%s),
                               offer_id=COALESCE(offer_id,%s),
                               request_id=COALESCE(request_id,%s),
                               warehouse_invoice_id=COALESCE(warehouse_invoice_id,%s),
                               file_url=COALESCE(NULLIF(file_url,''),%s),
                               photo_url=COALESCE(NULLIF(photo_url,''),%s),
                               payment_terms=COALESCE(NULLIF(payment_terms,''),%s),
                               material_name=COALESCE(NULLIF(material_name,''),%s),
                               work_package=COALESCE(NULLIF(work_package,''),%s)
                         WHERE id=%s
                        """,
                        (
                            duplicate.get("supplier_id"),
                            duplicate.get("supplier_name") or "",
                            duplicate.get("offer_id"),
                            duplicate.get("request_id"),
                            duplicate_warehouse_id,
                            duplicate.get("file_url") or "",
                            duplicate.get("photo_url") or "",
                            duplicate.get("payment_terms") or "",
                            duplicate.get("material_name") or "",
                            duplicate.get("work_package") or "",
                            canonical_id,
                        ),
                    )
                    if duplicate_warehouse_id:
                        cur.execute(
                            "UPDATE warehouse_invoices SET supplier_invoice_id=%s WHERE id=%s AND COALESCE(status,'') <> 'Аннулирована'",
                            (canonical_id, duplicate_warehouse_id),
                        )
                        linked_warehouse_rows += cur.rowcount
                        if not canonical_warehouse_id:
                            cur.execute("UPDATE supplier_invoices SET warehouse_invoice_id=%s WHERE id=%s", (duplicate_warehouse_id, canonical_id))
                            canonical_warehouse_id = duplicate_warehouse_id
                    cur.execute(
                        "UPDATE warehouse_invoices SET supplier_invoice_id=%s WHERE supplier_invoice_id=%s AND COALESCE(status,'') <> 'Аннулирована'",
                        (canonical_id, duplicate_id),
                    )
                    linked_warehouse_rows += cur.rowcount
                    cur.execute(
                        """
                        UPDATE supplier_invoices
                           SET status='Аннулирован',
                               paid_note=COALESCE(NULLIF(paid_note,''),'') ||
                                   CASE WHEN COALESCE(paid_note,'')<>'' THEN E'\n' ELSE '' END || %s
                         WHERE id=%s
                           AND COALESCE(status,'') <> 'Аннулирован'
                           AND COALESCE(paid_amount,0)=0
                        """,
                        (actor_note, duplicate_id),
                    )
                    annulled_rows += cur.rowcount
                group["applied"] = True
                applied_groups += 1
            groups.append(group)
        if apply_changes:
            conn.commit()
        else:
            conn.rollback()
        return {
            "ok": True,
            "dryRun": not apply_changes,
            "checkedGroups": len(groups),
            "appliedGroups": applied_groups,
            "annulledRows": annulled_rows,
            "linkedWarehouseRows": linked_warehouse_rows,
            "groups": groups,
        }
    except Exception:
        conn.rollback()
        raise
    finally:
        cur.close()
        conn.close()

@app.put("/warehouse-invoices/{id}/accounting")
def update_warehouse_invoice_accounting(
    id: int,
    data: dict,
    x_company_id: Optional[str] = Header(default=None, alias="X-Company-Id"),
    x_company_mode: Optional[str] = Header(default=None, alias="X-Company-Mode"),
    _current_user: dict = Depends(get_current_user),
):
    conn = get_db()
    conn.autocommit = False
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    try:
        _ensure_warehouse_invoice_accounting_columns(cur)
        _ensure_invoice_document_link_columns(cur)
        cur.execute("""SELECT id, number, date, supplier_id, supplier_name, location, project, items,
                              total_base, total_vat, total_with_vat, status, photo_url, photo_urls,
                              accounting_status, accounting_comment, paid_amount, supplier_invoice_id,
                              company_id, warehouse_target, selected_action
                       FROM warehouse_invoices WHERE id=%s FOR UPDATE""", (id,))
        row = cur.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Накладная не найдена")
        _company_context, actor = resolve_resource_company_actor(
            cur,
            _current_user,
            row.get("company_id"),
            "update",
            claimed_company_id=data.get("companyId") if "companyId" in data else data.get("company_id"),
            x_company_id=x_company_id,
            x_company_mode=x_company_mode,
            allowed_roles=FINANCE_ROLES,
            forbidden_detail="Роль в выбранной компании не позволяет менять бухгалтерский статус накладной",
            platform_staff_roles=PLATFORM_STAFF_ROLES,
            client_account_roles=CLIENT_ACCOUNT_ROLES,
        )
        _current_user = actor
        if not warehouse_invoice_accounting_required(row):
            raise HTTPException(
                status_code=409,
                detail="Приход на основной склад без поставщика не является документом к оплате",
            )
        if row.get("status") == "Аннулирована":
            raise HTTPException(status_code=409, detail="Аннулированную накладную нельзя отправить в оплату")

        target_project = row.get("project") or (row.get("location") if row.get("location") != "Основной склад" else "")
        if target_project:
            require_project_access(_current_user, target_project)

        supplier_payload_present = "supplierId" in data or "supplier_id" in data
        requested_supplier_id = None
        requested_supplier = None
        if supplier_payload_present:
            raw_supplier_id = data.get("supplierId")
            if raw_supplier_id is None:
                raw_supplier_id = data.get("supplier_id")
            requested_supplier_id = _positive_int_or_none(raw_supplier_id)
            if not requested_supplier_id:
                raise HTTPException(status_code=400, detail="Выберите существующую карточку поставщика")
            cur.execute("SELECT id,name FROM suppliers WHERE id=%s LIMIT 1", (requested_supplier_id,))
            requested_supplier = cur.fetchone()
            if not requested_supplier:
                raise HTTPException(status_code=404, detail="Карточка поставщика не найдена")
            current_supplier_id = _positive_int_or_none(row.get("supplier_id"))
            if current_supplier_id and current_supplier_id != requested_supplier_id:
                raise HTTPException(status_code=409, detail="У накладной уже указан другой поставщик")

        link_payload_present = "supplierInvoiceId" in data or "supplier_invoice_id" in data
        current_supplier_invoice_id = row.get("supplier_invoice_id")
        linked_supplier_invoice_id = current_supplier_invoice_id
        supplier_invoice_row = None
        if link_payload_present:
            raw_supplier_invoice_id = data.get("supplierInvoiceId")
            if raw_supplier_invoice_id is None:
                raw_supplier_invoice_id = data.get("supplier_invoice_id")
            linked_supplier_invoice_id = int(raw_supplier_invoice_id or 0) or None
        if linked_supplier_invoice_id:
            cur.execute("""SELECT id, supplier_id, project_name, supplier_name, amount, paid_amount,
                                  status, warehouse_invoice_id, company_id
                           FROM supplier_invoices
                           WHERE id=%s AND COALESCE(status,'') <> 'Аннулирован'
                           FOR UPDATE""", (linked_supplier_invoice_id,))
            supplier_invoice_row = cur.fetchone()
            if not supplier_invoice_row:
                raise HTTPException(status_code=404, detail="Счёт поставщика для связи не найден")
            if _positive_int_or_none(supplier_invoice_row.get("company_id")) != _positive_int_or_none(row.get("company_id")):
                raise HTTPException(status_code=409, detail="Счёт поставщика относится к другой компании")
            supplier_project = (supplier_invoice_row.get("project_name") or "").strip()
            if supplier_project and target_project and supplier_project != target_project:
                raise HTTPException(status_code=400, detail="Счёт поставщика относится к другому объекту")
            existing_warehouse_invoice_id = supplier_invoice_row.get("warehouse_invoice_id")
            if existing_warehouse_invoice_id and int(existing_warehouse_invoice_id) != int(id):
                raise HTTPException(status_code=409, detail="Счёт поставщика уже связан с другой складской накладной")
            invoice_supplier_id = _positive_int_or_none(supplier_invoice_row.get("supplier_id"))
            if requested_supplier_id and invoice_supplier_id and invoice_supplier_id != requested_supplier_id:
                raise HTTPException(status_code=409, detail="Счёт поставщика связан с другой карточкой поставщика")

        supplier_recognition_requested = isinstance(
            data.get("supplierRequisites") or data.get("supplier_requisites"),
            dict,
        )
        linked_supplier_resolution_requested = (
            data.get("resolveLinkedSupplier") is True
            or data.get("resolve_linked_supplier") is True
        )
        supplier_recognition_created = False
        supplier_needs_review = False
        existing_supplier_id = (
            requested_supplier_id
            or _positive_int_or_none(row.get("supplier_id"))
            or _positive_int_or_none((supplier_invoice_row or {}).get("supplier_id"))
        )
        if supplier_recognition_requested and not existing_supplier_id:
            requested_supplier = _resolve_or_create_document_supplier(
                cur,
                data,
                fallback_name=row.get("supplier_name") or (supplier_invoice_row or {}).get("supplier_name") or "",
                source_detail="Определено из накладной #" + str(id),
            )
            requested_supplier_id = _positive_int_or_none(requested_supplier.get("id"))
            supplier_recognition_created = bool(requested_supplier.get("created"))

        if linked_supplier_resolution_requested:
            requested_linked_status = str(
                data.get("accountingStatus")
                or data.get("accounting_status")
                or data.get("status")
                or ""
            ).strip()
            if requested_linked_status != "К оплате":
                raise HTTPException(
                    status_code=400,
                    detail="Автоматическое определение поставщика доступно только при переводе в статус «К оплате»",
                )
            if not supplier_invoice_row:
                raise HTTPException(
                    status_code=409,
                    detail="Для автоматического определения поставщика нужен связанный счёт",
                )
            if not existing_supplier_id and not requested_supplier_id:
                requested_supplier = _resolve_or_create_linked_invoice_supplier(
                    cur,
                    supplier_invoice_row,
                    fallback_name=row.get("supplier_name") or "",
                    warehouse_invoice_id=id,
                )
                requested_supplier_id = _positive_int_or_none(requested_supplier.get("id"))
                supplier_recognition_created = bool(requested_supplier.get("created"))
                supplier_needs_review = bool(requested_supplier.get("needsReview"))

        requested_status = str(
            data.get("accountingStatus")
            or data.get("accounting_status")
            or data.get("status")
            or ""
        ).strip()
        if requested_status and requested_status not in WAREHOUSE_INVOICE_ACCOUNTING_STATUSES:
            raise HTTPException(status_code=400, detail="Недопустимый бухгалтерский статус накладной")

        current_photos = _json_list_or_empty(row.get("photo_urls"))
        first_existing_photo = str(row.get("photo_url") or "").strip()
        if first_existing_photo and first_existing_photo not in current_photos:
            current_photos.insert(0, first_existing_photo)

        incoming_photos = data.get("photos") or data.get("photoUrls") or data.get("photo_urls") or []
        if isinstance(incoming_photos, str):
            try:
                incoming_photos = json.loads(incoming_photos)
            except Exception:
                incoming_photos = [x.strip() for x in incoming_photos.split(",") if x.strip()]
        if not isinstance(incoming_photos, list):
            incoming_photos = []
        for photo_url in incoming_photos:
            photo_url = str(photo_url or "").strip()
            if photo_url and photo_url not in current_photos:
                current_photos.append(photo_url)

        next_status = requested_status or str(row.get("accounting_status") or "").strip()
        if current_photos and next_status in ("", "Нет фото"):
            next_status = "На проверке"
        if not current_photos and not next_status:
            next_status = "Нет фото"
        resolved_supplier_id = (
            requested_supplier_id
            or _positive_int_or_none(row.get("supplier_id"))
            or _positive_int_or_none((supplier_invoice_row or {}).get("supplier_id"))
        )
        if next_status in ("К оплате", "Частично оплачена", "Оплачена") and not resolved_supplier_id:
            raise HTTPException(
                status_code=409,
                detail="Перед оплатой нужно определить поставщика: выберите существующий счёт поставщика или уточните реквизиты накладной",
            )
        if next_status in ("К оплате", "Частично оплачена", "Оплачена") and not current_photos:
            raise HTTPException(status_code=400, detail="Перед оплатой нужно прикрепить фото накладной")

        comment = data.get("accountingComment")
        if comment is None:
            comment = data.get("accounting_comment")
        if comment is None:
            comment = row.get("accounting_comment") or ""
        comment = str(comment or "").strip()
        if linked_supplier_resolution_requested and requested_supplier:
            comment = _remove_resolved_supplier_clarification(comment)
        if requested_supplier:
            selected_supplier_name = str(requested_supplier.get("name") or "").strip()
            original_supplier_name = str(row.get("supplier_name") or "").strip()
            if linked_supplier_resolution_requested:
                audit_note = (
                    "Новый поставщик создан по связанному счёту: "
                    if supplier_recognition_created
                    else "Поставщик определён по связанному счёту: "
                ) + selected_supplier_name
                if supplier_needs_review:
                    audit_note += " (реквизиты требуют проверки)"
            elif supplier_recognition_requested:
                audit_note = (
                    "Новый поставщик создан по реквизитам документа: "
                    if supplier_recognition_created
                    else "Поставщик определён по реквизитам документа: "
                ) + selected_supplier_name
            else:
                audit_note = "Поставщик выбран вручную: " + selected_supplier_name
            if original_supplier_name and original_supplier_name != selected_supplier_name:
                audit_note += " (в накладной: " + original_supplier_name + ")"
            if audit_note not in comment:
                comment = (comment + "\n" if comment else "") + audit_note

        paid_amount_before = _float_or_zero(row.get("paid_amount"))
        payment_amount = _float_or_zero(data.get("paymentAmount") or data.get("payment_amount"))
        payment_id = None
        payment_already_recorded = False
        paid_amount_after = paid_amount_before
        paid_at = str(data.get("paidAt") or data.get("paid_at") or dt.date.today().isoformat()).strip()
        actor_name = _current_user.get("name") or _current_user.get("email") or ""

        if payment_amount > 0:
            if not target_project:
                raise HTTPException(status_code=400, detail="Для оплаты накладной нужна привязка к объекту")
            invoice_total = _float_or_zero(row.get("total_with_vat") or row.get("total_base"))
            items = _json_list_or_empty(row.get("items"))
            work_package = str(data.get("workPackage") or data.get("work_package") or "").strip()
            if not work_package and items:
                first_item = items[0] if isinstance(items[0], dict) else {}
                work_package = str(first_item.get("workPackage") or first_item.get("work_package") or "").strip()
            if not has_package_access(_current_user, work_package or "Основная"):
                raise HTTPException(status_code=403, detail="Нет доступа к пакету платежа")
            note = "Оплата счёта по накладной " + str(row.get("supplier_name") or "").strip()
            if row.get("number"):
                note += " №" + str(row.get("number"))
            if work_package:
                note += " · " + work_package
            cur.execute("""SELECT id FROM project_payments
                           WHERE company_id=%s AND project_name=%s
                             AND COALESCE(work_package,'')=%s AND amount=%s
                             AND COALESCE(note,'')=%s AND date IS NOT DISTINCT FROM %s
                             AND COALESCE(added_by,'')=%s
                           ORDER BY id DESC LIMIT 1""",
                        (row.get("company_id"), target_project, work_package,
                         payment_amount, note, paid_at, actor_name))
            existing_payment = cur.fetchone()
            if existing_payment:
                payment_id = existing_payment["id"]
                payment_already_recorded = True
                paid_amount_after = max(paid_amount_before, payment_amount)
            else:
                if invoice_total > 0:
                    remaining_to_pay = max(0, invoice_total - paid_amount_before)
                    if payment_amount > remaining_to_pay + 0.01:
                        raise HTTPException(status_code=400, detail=f"Оплата превышает долг по накладной. Остаток к оплате: {round(remaining_to_pay, 2)} ₽")
                cur.execute("""INSERT INTO project_payments
                                  (company_id, project_name, work_package, amount, note, date, added_by)
                               VALUES (%s,%s,%s,%s,%s,%s,%s) RETURNING id""",
                            (row.get("company_id"), target_project, work_package,
                             payment_amount, note, paid_at, actor_name))
                payment_id = cur.fetchone()["id"]
                paid_amount_after = round(paid_amount_before + payment_amount, 2)
            if invoice_total > 0 and paid_amount_after + 0.01 >= invoice_total:
                next_status = "Оплачена"
            else:
                next_status = "Частично оплачена"

        invoice_total = _float_or_zero(row.get("total_with_vat") or row.get("total_base"))
        if invoice_total > 0 and paid_amount_after + 0.01 >= invoice_total:
            next_status = "Оплачена"
            paid_amount_after = min(paid_amount_after, invoice_total)
        elif paid_amount_after > 0 and next_status in ("", "К оплате", "Частично оплачена", "Оплачена"):
            next_status = "Частично оплачена"

        cur.execute("""UPDATE warehouse_invoices
                       SET accounting_status=%s,
                           accounting_comment=%s,
                           accounting_updated_by=%s,
                           accounting_updated_at=NOW(),
                           photo_urls=%s,
                           photo_url=%s,
                           paid_amount=%s,
                           paid_at=CASE WHEN %s > 0 THEN %s ELSE paid_at END,
                           paid_by=CASE WHEN %s > 0 THEN %s ELSE paid_by END,
                           supplier_id=COALESCE(supplier_id,%s),
                           supplier_name=CASE WHEN %s IS NOT NULL THEN %s ELSE supplier_name END,
                           supplier_invoice_id=%s
                       WHERE id=%s""",
                    (
                        next_status,
                        comment,
                        actor_name,
                        json.dumps(current_photos, ensure_ascii=False),
                        current_photos[0] if current_photos else "",
                        paid_amount_after,
                        payment_amount,
                        paid_at,
                        payment_amount,
                        actor_name,
                        resolved_supplier_id,
                        requested_supplier_id,
                        (requested_supplier or {}).get("name") or (supplier_invoice_row or {}).get("supplier_name") or "",
                        linked_supplier_invoice_id,
                        id,
                    ))
        if current_supplier_invoice_id and current_supplier_invoice_id != linked_supplier_invoice_id:
            cur.execute("""UPDATE supplier_invoices
                           SET warehouse_invoice_id=NULL
                           WHERE id=%s AND warehouse_invoice_id=%s""", (current_supplier_invoice_id, id))
        if linked_supplier_invoice_id:
            supplier_sets = ["warehouse_invoice_id=%s"]
            supplier_vals = [id]
            linked_invoice_next_status = None
            if requested_supplier_id:
                supplier_sets += ["supplier_id=%s", "supplier_name=%s"]
                supplier_vals += [requested_supplier_id, (requested_supplier or {}).get("name") or ""]
            if payment_amount > 0:
                supplier_amount = _float_or_zero(supplier_invoice_row.get("amount") if supplier_invoice_row else 0)
                supplier_paid_before = _float_or_zero(supplier_invoice_row.get("paid_amount") if supplier_invoice_row else 0)
                if payment_already_recorded:
                    supplier_paid_after = max(supplier_paid_before, min(supplier_amount or payment_amount, payment_amount))
                else:
                    supplier_paid_after = supplier_paid_before + payment_amount
                if supplier_amount > 0:
                    supplier_paid_after = min(supplier_paid_after, supplier_amount)
                supplier_status = "Оплачен" if supplier_amount > 0 and supplier_paid_after + 0.01 >= supplier_amount else "Частично оплачен"
                supplier_sets += ["paid_amount=%s", "status=%s", "paid_at=%s", "paid_by=%s", "paid_note=%s"]
                supplier_vals += [
                    supplier_paid_after,
                    supplier_status,
                    paid_at,
                    actor_name,
                    "Оплата по складской накладной №" + str(row.get("number") or id),
                ]
            else:
                linked_invoice_next_status = _linked_supplier_invoice_status_after_accounting(
                    (supplier_invoice_row or {}).get("status"),
                    next_status,
                    resolved_automatically=linked_supplier_resolution_requested,
                )
            if linked_invoice_next_status:
                supplier_sets.append("status=%s")
                supplier_vals.append(linked_invoice_next_status)
            supplier_vals.append(linked_supplier_invoice_id)
            cur.execute("UPDATE supplier_invoices SET " + ", ".join(supplier_sets) + " WHERE id=%s", supplier_vals)
        conn.commit()
        return {
            "ok": True,
            "accountingStatus": next_status,
            "photos": current_photos,
            "paidAmount": paid_amount_after,
            "paymentId": payment_id,
            "supplierId": resolved_supplier_id,
            "supplierName": (requested_supplier or {}).get("name") or (supplier_invoice_row or {}).get("supplier_name") or row.get("supplier_name") or "",
            "supplierCreated": supplier_recognition_created,
            "supplierNeedsReview": supplier_needs_review,
        }
    except Exception:
        conn.rollback()
        raise
    finally:
        cur.close(); conn.close()

@app.post("/workflow/invoice/preview")
def workflow_invoice_preview(data: dict, _workflow: dict = Depends(require_workflow_token)):
    """Safe Workflow entrypoint: validate/preview invoice data without writing stock."""
    document = data.get("document") if isinstance(data.get("document"), dict) else {}
    totals = data.get("totals") if isinstance(data.get("totals"), dict) else {}

    photos = data.get("photos") or data.get("photoUrls") or data.get("images") or data.get("pages") or []
    if isinstance(photos, str):
        photos = [photos]
    if not isinstance(photos, list):
        photos = []
    photos = [str(photo).strip() for photo in photos if str(photo or "").strip()]

    items = data.get("items") or data.get("positions") or []
    if not isinstance(items, list):
        items = []

    project_name = (
        data.get("projectName")
        or data.get("project")
        or data.get("project_name")
        or ""
    )
    warehouse_target = (data.get("warehouseTarget") or data.get("target") or "object").strip() or "object"
    selected_action = (data.get("selectedAction") or data.get("action") or "receive_to_warehouse").strip()
    warnings = []
    status = "ok"

    if selected_action not in ("receive_to_warehouse", "warehouse_invoice", "stock_receipt"):
        status = "needs_review"
        warnings.append("Маршрут не похож на складскую накладную. Проверьте, что документ не ушел в мои траты.")
    if warehouse_target in ("object", "project") and not str(project_name).strip():
        status = "needs_review"
        warnings.append("Для прихода на объект нужно указать объект.")
    if not photos:
        status = "needs_review"
        warnings.append("Фото накладной не переданы. Workflow подключен, но распознавание не запускалось.")
    if len(photos) > 8:
        status = "needs_review"
        warnings.append("Передано больше 8 страниц. Сейчас безопасный лимит распознавания — 8 фото.")

    invoice_preview = _normalize_invoice_totals_payload({
        **data,
        "document": document,
        "totals": totals,
        "items": items,
    })
    total_base = invoice_preview.get("totalBase", 0)
    total_vat = invoice_preview.get("totalVat", 0)
    total_with_vat = invoice_preview.get("totalWithVat", 0)
    if total_with_vat and total_base and total_vat and abs((total_base + total_vat) - total_with_vat) > 2:
        status = "needs_review"
        warnings.append("Итог с НДС не сходится с суммой без НДС и НДС.")

    normalized_items = []
    for idx, raw_item in enumerate((invoice_preview.get("items") or [])[:300], start=1):
        if not isinstance(raw_item, dict):
            continue
        qty = _float_or_zero(raw_item.get("quantity") or raw_item.get("qty"))
        price = _float_or_zero(raw_item.get("price") or raw_item.get("priceWithVat") or raw_item.get("price_with_vat"))
        line_total = _float_or_zero(raw_item.get("lineTotalWithVat") or raw_item.get("lineTotal") or raw_item.get("total"))
        normalized_items.append({
            "row": idx,
            "name": str(raw_item.get("name") or raw_item.get("title") or "").strip(),
            "quantity": qty,
            "unit": _norm_base_unit(raw_item.get("unit") or "шт") or "шт",
            "price": price,
            "lineTotal": line_total or (qty * price if qty and price else 0),
            "page": raw_item.get("page") or raw_item.get("pageNumber") or None,
            "confidence": _float_or_zero(raw_item.get("confidence") or 0),
            "needsReview": bool(raw_item.get("needsReview") or raw_item.get("needs_review")),
        })
    vat_label = str(invoice_preview.get("vat") or data.get("vat") or document.get("vat") or "").strip()

    if len(items) > 300:
        status = "needs_review"
        warnings.append("В накладной больше 300 позиций. Вернули первые 300 для безопасного предпросмотра.")

    pages_detected = int(_float_or_zero(data.get("pagesDetected") or document.get("pagesDetected")) or len(photos))

    return {
        "ok": True,
        "status": status,
        "route": "warehouse_invoice",
        "document": {
            "type": "invoice_preview",
            "number": data.get("number") or data.get("invoiceNumber") or document.get("number") or document.get("invoiceNumber") or "",
            "date": data.get("date") or data.get("invoiceDate") or document.get("date") or document.get("invoiceDate") or "",
            "supplierName": data.get("supplierName") or data.get("supplier") or document.get("supplierName") or document.get("supplier") or "",
            "vat": vat_label,
            "pagesDetected": pages_detected,
        },
        "projectName": project_name,
        "warehouseTarget": warehouse_target,
        "selectedAction": selected_action,
        "items": normalized_items,
        "totals": {
            "totalBase": total_base,
            "totalVat": total_vat,
            "totalWithVat": total_with_vat,
        },
        "photos": photos,
        "warnings": warnings,
        "message": "Workflow подключен. Это предпросмотр без записи в склад и без создания трат.",
    }

@app.delete("/warehouse-invoices/{id}")
def delete_warehouse_invoice(
    id: int,
    x_company_id: Optional[str] = Header(default=None, alias="X-Company-Id"),
    x_company_mode: Optional[str] = Header(default=None, alias="X-Company-Mode"),
    _current_user: dict = Depends(get_current_user),
):
    import json as j
    conn = get_db()
    conn.autocommit = False
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    try:
        _ensure_invoice_document_link_columns(cur)
        cur.execute("""SELECT id, COALESCE(project,'') AS project, COALESCE(location,'') AS location,
                              COALESCE(status,'') AS status, items, COALESCE(accepted_by,'') AS accepted_by,
                              COALESCE(added_by,'') AS added_by, date, supply_delivery_id, supplier_invoice_id,
                              company_id
                       FROM warehouse_invoices WHERE id=%s FOR UPDATE""", (id,))
        row = cur.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Накладная не найдена")
        _company_context, actor = resolve_resource_company_actor(
            cur,
            _current_user,
            row.get("company_id"),
            "delete",
            x_company_id=x_company_id,
            x_company_mode=x_company_mode,
            allowed_roles=(*LEADERSHIP_ROLES, "кладовщик", "снабженец"),
            forbidden_detail="Роль в выбранной компании не позволяет аннулировать складскую накладную",
            platform_staff_roles=PLATFORM_STAFF_ROLES,
            client_account_roles=CLIENT_ACCOUNT_ROLES,
        )
        _current_user = actor
        if row.get("supply_delivery_id"):
            raise HTTPException(status_code=409, detail="Накладная создана при приёмке поставки. Исправляйте поставку/претензию, а не удаляйте накладную отдельно.")
        if row.get("status") == "Аннулирована":
            conn.rollback()
            return {"ok": True, "annulled": True, "alreadyAnnulled": True, "stockRowsRestored": 0}
        target_project = row.get("project") or (row.get("location") if row.get("location") != "Основной склад" else "")
        if target_project:
            require_project_or_warehouse_access(_current_user, target_project)
        if row.get("supplier_invoice_id"):
            cur.execute("SELECT company_id FROM supplier_invoices WHERE id=%s FOR UPDATE", (row.get("supplier_invoice_id"),))
            linked_supplier_invoice = cur.fetchone()
            if linked_supplier_invoice and _positive_int_or_none(linked_supplier_invoice.get("company_id")) != _positive_int_or_none(row.get("company_id")):
                raise HTTPException(status_code=409, detail="Связанный счёт поставщика относится к другой компании")
        try:
            items_list = j.loads(row.get("items") or "[]") if isinstance(row.get("items"), str) else (row.get("items") or [])
        except Exception:
            items_list = []
        restored = 0
        actor_name = _current_user.get("name") or row.get("accepted_by") or row.get("added_by") or ""
        date_time = dt.datetime.now().strftime("%d.%m.%Y, %H:%M")
        for it in items_list:
            name = (it.get("name") or "").strip()
            try:
                qty = float(str(it.get("quantity") or 0).replace(" ", "").replace(",", "."))
            except Exception:
                qty = 0
            if not name or qty <= 0:
                continue
            unit = _norm_base_unit(it.get("unit") or "шт") or "шт"
            work_package = (it.get("workPackage") or it.get("work_package") or "").strip()
            if target_project:
                cur.execute(f"""SELECT id, quantity FROM materials
                               WHERE LOWER(name)=LOWER(%s)
                                 AND project=%s
                                 AND company_id=%s
                                 AND COALESCE(work_package,'')=%s
                                 AND {_sql_norm_unit('unit')}=%s
                               ORDER BY id LIMIT 1 FOR UPDATE""", (name, target_project, row.get("company_id"), work_package, unit))
                mat = cur.fetchone()
                if not mat:
                    raise HTTPException(status_code=409, detail="Нельзя аннулировать накладную: материал «"+name+"» уже отсутствует на складе объекта")
                if float(mat.get("quantity") or 0) < qty:
                    raise HTTPException(status_code=409, detail="Нельзя аннулировать накладную: по материалу «"+name+"» остаток меньше прихода. Сначала проверьте списания/перемещения.")
                cur.execute("UPDATE materials SET quantity=COALESCE(quantity,0)-%s WHERE id=%s", (qty, mat["id"]))
                history_project = target_project
            else:
                cur.execute(f"""SELECT id, quantity FROM warehouse_main
                               WHERE LOWER(name)=LOWER(%s)
                                 AND company_id=%s
                                 AND {_sql_norm_unit('unit')}=%s
                               ORDER BY id LIMIT 1 FOR UPDATE""", (name, row.get("company_id"), unit))
                mat = cur.fetchone()
                if not mat:
                    raise HTTPException(status_code=409, detail="Нельзя аннулировать накладную: материал «"+name+"» уже отсутствует на основном складе")
                if float(mat.get("quantity") or 0) < qty:
                    raise HTTPException(status_code=409, detail="Нельзя аннулировать накладную: по материалу «"+name+"» остаток меньше прихода. Сначала проверьте списания/перемещения.")
                cur.execute("UPDATE warehouse_main SET quantity=COALESCE(quantity,0)-%s WHERE id=%s", (qty, mat["id"]))
                history_project = "Основной склад"
            cur.execute("""INSERT INTO warehouse_history
                              (company_id,material,type,quantity,unit,date,project,issued_by,work_package,date_time)
                           VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                        (row.get("company_id"), name, "сторно прихода по накладной", qty, unit, row.get("date") or None, history_project, actor_name, work_package, date_time))
            restored += 1
        cur.execute("""UPDATE material_inspection_journal
                       SET status=%s, remarks=COALESCE(NULLIF(remarks,''),'') || %s
                       WHERE invoice_id=%s""",
                    ("Аннулирована", "\nНакладная аннулирована: приход сторнирован.", id))
        cur.execute("UPDATE cable_journal SET status=%s WHERE invoice_id=%s", ("Аннулирована", id))
        cur.execute("UPDATE warehouse_invoices SET status=%s WHERE id=%s", ("Аннулирована", id))
        if row.get("supplier_invoice_id"):
            cur.execute("""UPDATE supplier_invoices
                           SET warehouse_invoice_id=NULL
                           WHERE id=%s AND warehouse_invoice_id=%s AND company_id=%s""", (row.get("supplier_invoice_id"), id, row.get("company_id")))
        conn.commit()
        _run_project_ai_control_safely(target_project, "warehouse_invoice:annul")
        return {"ok": True, "annulled": True, "stockRowsRestored": restored}
    except HTTPException:
        conn.rollback()
        raise
    except Exception as e:
        conn.rollback()
        raise HTTPException(status_code=500, detail=str(e))
    finally:
        cur.close(); conn.close()

def _norm_list(value):
    if isinstance(value, list):
        return [str(v).strip() for v in value if str(v).strip()]
    if not value:
        return []
    if isinstance(value, str):
        raw = value.strip()
        if not raw:
            return []
        try:
            parsed = json.loads(raw)
            if isinstance(parsed, list):
                return [str(v).strip() for v in parsed if str(v).strip()]
        except Exception:
            pass
        return [v.strip() for v in raw.replace("\n", ",").split(",") if v.strip()]
    return []

def _material_norm_row(row):
    return {
        "id": row["id"],
        "ruleKey": row["rule_key"] or "",
        "name": row["name"] or "",
        "work": _norm_list(row["work_keywords"]),
        "blockWork": _norm_list(row["block_work_keywords"]),
        "material": _norm_list(row["material_keywords"]),
        "workUnit": row["work_unit"] or "",
        "materialUnit": row["material_unit"] or "",
        "qtyPerUnit": float(row["qty_per_unit"] or 0),
        "thicknessBaseMm": float(row["thickness_base_mm"]) if row["thickness_base_mm"] is not None else None,
        "defaultThicknessMm": float(row["default_thickness_mm"]) if row["default_thickness_mm"] is not None else None,
        "label": row["label"] or "",
        "active": bool(row["active"]),
        "updatedBy": row["updated_by"] or "",
        "updatedAt": str(row["updated_at"]) if row["updated_at"] else "",
    }

def _material_norm_values(data: MaterialNormModel, user_name: str):
    rule_key = (data.ruleKey or "").strip() or ("custom_" + uuid.uuid4().hex[:8])
    return (
        rule_key,
        data.name.strip() or rule_key,
        json.dumps(_norm_list(data.work), ensure_ascii=False),
        json.dumps(_norm_list(data.blockWork), ensure_ascii=False),
        json.dumps(_norm_list(data.material), ensure_ascii=False),
        data.workUnit or "м2",
        data.materialUnit or "кг",
        data.qtyPerUnit or 0,
        data.thicknessBaseMm,
        data.defaultThicknessMm,
        data.label.strip(),
        bool(data.active),
        user_name or "",
    )

