def log_audit(
    user_name="",
    user_role="",
    action="",
    entity_type="",
    entity_id=None,
    description="",
    project_name="",
    user_id=None,
    owner_scope=None,
    company_id=None,
    project_id=None,
):
    """Запись действия в audit_log. Тихо игнорирует ошибки чтобы не ломать основные операции."""
    conn = None
    cur = None
    try:
        try:
            from backend.features.audit_ownership.runtime import insert_audit_event
        except ModuleNotFoundError:
            from features.audit_ownership.runtime import insert_audit_event
        conn = get_db()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        result = insert_audit_event(
            cur,
            user_id=user_id,
            user_name=user_name,
            user_role=user_role,
            action=action,
            entity_type=entity_type,
            entity_id=entity_id,
            description=description,
            project_name=project_name,
            owner_scope=owner_scope,
            company_id=company_id,
            project_id=project_id,
        )
        conn.commit()
        if result["owner"]["scope"] == "legacy":
            print(
                "AUDIT OWNER LEGACY:",
                str(action or ""),
                str(entity_type or ""),
                entity_id,
                result["owner"].get("reason"),
            )
        return result["id"]
    except Exception as e:
        if conn:
            try:
                conn.rollback()
            except Exception:
                pass
        print("AUDIT LOG ERROR:", str(e))
        return None
    finally:
        if cur:
            try:
                cur.close()
            except Exception:
                pass
        if conn:
            try:
                conn.close()
            except Exception:
                pass


